import type { Task } from '../types';

export const TS_TASKS: Record<string, Task[]> = {
typebasics: [
  { id: 1, level: 1, title: "The User Registration Fields", scenario: "You are building a signup form and need to store a new user's basic info with correct TypeScript types.", objective: "Declare `let username: string = \"coder123\"`. Declare `let age: number = 25`. Declare `let subscribed: boolean = false`.", constraints: "Every variable must have an explicit type annotation. Do not use `any`.", expectedOutput: "`console.log(username, age, subscribed)` prints: coder123 25 false", check: "Attempting `age = \"twenty-five\"` must produce a compile-time type error. `typeof age` at runtime is \"number\"." },
  { id: 2, level: 1, title: "The Product Price List", scenario: "An online store needs to store a list of product prices for a shopping cart summary.", objective: "Declare `const prices: number[] = [19.99, 5.5, 42.0]`. Log the array and its `.length`.", constraints: "Must use the `number[]` array type annotation. Do not use `any[]`.", expectedOutput: "`console.log(prices, prices.length)` prints: [ 19.99, 5.5, 42 ] 3", check: "Attempting `prices.push(\"free\")` must produce a compile-time type error since \"free\" is a string, not a number." },
  { id: 3, level: 1, title: "The Silent Logger Function", scenario: "You are writing a small utility function that only logs a message and has no meaningful return value.", objective: "Write `function logInfo(message: string): void { console.log(\"[INFO]\", message); }` and call it with \"Server started\".", constraints: "The return type must be `void`, not left off entirely. `message` must be typed `string`.", expectedOutput: "`logInfo(\"Server started\")` prints: [INFO] Server started", check: "`const result = logInfo(\"x\")` followed by `console.log(result)` logs undefined, confirming void functions return no usable value." },
  { id: 4, level: 1, title: "The Escape-Hatch Warning", scenario: "A legacy third-party function returns a value whose real type your team has not yet determined, so you fall back to `any` temporarily.", objective: "Declare `let legacyValue: any = 42;` then reassign it to `\"now text\"` and then to `true`, logging it each time.", constraints: "Must use `any` explicitly (not omit the annotation). Add a code comment noting `any` disables type checking.", expectedOutput: "Three console.log calls print: 42, then now text, then true — with no compile errors despite the changing types.", check: "Confirm that changing `any` to `number` on the declaration causes the string and boolean reassignments to become compile errors." },
  { id: 5, level: 1, title: "The Nullable Middle Name", scenario: "A user profile form has a middle name field that many users intentionally leave blank.", objective: "Declare `let middleName: string | null = null;`. Log it. Then reassign it to \"Marie\" and log again.", constraints: "Must use the union type `string | null`, not just `string`. Do not use `any`.", expectedOutput: "First log: null. Second log: Marie.", check: "Attempting `middleName = undefined` (instead of null) should be a compile-time type error, since undefined is not part of the declared union." },
  { id: 6, level: 2, title: "The RGB Color Tuple", scenario: "A design system utility needs to represent a color as exactly three numeric channels, in a fixed order.", objective: "Declare `let rgb: [number, number, number] = [255, 99, 71];`. Log `rgb[0]`, `rgb[1]`, `rgb[2]` individually.", constraints: "Must use a 3-element tuple type, not `number[]`. Do not add a fourth element.", expectedOutput: "`console.log(rgb[0], rgb[1], rgb[2])` prints: 255 99 71", check: "Attempting `rgb = [1, 2, 3, 4]` (4 elements) must produce a compile-time tuple-length error." },
  { id: 7, level: 2, title: "The Traffic Light Enum", scenario: "A simulation app models a traffic light with three fixed states that a developer keeps confusing with raw strings.", objective: "Declare `enum Light { Red, Yellow, Green }`. Log `Light.Red`, `Light.Yellow`, `Light.Green`.", constraints: "Must use `enum`, not a union of string literals. Do not assign custom values to the members.", expectedOutput: "`console.log(Light.Red, Light.Yellow, Light.Green)` prints: 0 1 2", check: "Confirm `Light.Green === 2` is true, demonstrating default zero-based numeric auto-increment." },
  { id: 8, level: 2, title: "The Order Status Literal Union", scenario: "An order tracking system must restrict status values to a fixed, known set to prevent typos like \"shiped\".", objective: "Declare `let status: \"pending\" | \"shipped\" | \"delivered\" = \"pending\";` then reassign to \"shipped\" and log both states.", constraints: "Must use a string literal union type, not `string`. Do not use an enum for this task.", expectedOutput: "First log: pending. Second log: shipped.", check: "Attempting `status = \"shiped\"` (typo) must produce a compile-time type error since it does not match any literal in the union." },
  { id: 9, level: 2, title: "The Frozen Settings Array", scenario: "An app's default keyboard shortcuts list should never be mutated once defined.", objective: "Declare `const shortcuts: readonly string[] = [\"Ctrl+S\", \"Ctrl+Z\", \"Ctrl+C\"];`. Log the array and its length.", constraints: "Must use the `readonly` modifier on the array type. Do not attempt to actually call `.push()` in the working code.", expectedOutput: "`console.log(shortcuts, shortcuts.length)` prints: [ 'Ctrl+S', 'Ctrl+Z', 'Ctrl+C' ] 3", check: "Attempting `shortcuts.push(\"Ctrl+X\")` must produce a compile-time error since push does not exist on a readonly array type." },
  { id: 10, level: 2, title: "The Safe DOM Value Assertion", scenario: "You query a DOM element and know from context it will be an input element, but its declared type is broader.", objective: "Simulate: `let el: unknown = \"user@example.com\";` then narrow it with `const email = el as string;` and log `email.toUpperCase()`.", constraints: "Must start with `unknown`, not `any`. Must use an `as` type assertion, not `any`, to narrow it.", expectedOutput: "`console.log(email.toUpperCase())` prints: USER@EXAMPLE.COM", check: "Attempting `el.toUpperCase()` directly (without the assertion) on the unknown-typed variable must be a compile-time error." },
  { id: 11, level: 3, title: "The Product Catalog Entry", scenario: "An e-commerce catalog page needs to render a single product with a name, price, and an optional discount percentage.", objective: "Declare `let product: { name: string; price: number; discountPct?: number } = { name: \"Mug\", price: 12.5 };`. Log `product.discountPct ?? 0`.", constraints: "Must use an inline object type with `discountPct` marked optional. Do not include discountPct in the initial object literal.", expectedOutput: "`console.log(product.discountPct ?? 0)` prints: 0", check: "Adding `discountPct: 10` to product and re-running must log 10, confirming the optional field works both ways." },
  { id: 12, level: 3, title: "The Unknown API Payload", scenario: "You fetch data from an API you do not fully trust yet, and must safely determine its shape before use.", objective: "Declare `let payload: unknown = \"42\";`. Write an `if (typeof payload === \"string\")` narrowing check, and inside it log `Number(payload) + 8`.", constraints: "payload must be typed `unknown`, not `any`. Must use a `typeof` narrowing check before treating payload as a string.", expectedOutput: "Inside the narrowed branch, `console.log(Number(payload) + 8)` prints: 50", check: "Attempting to call `payload.length` before the typeof narrowing check must be a compile-time error." },
  { id: 13, level: 3, title: "The Permission Level Constants", scenario: "A codebase has scattered magic numbers (0, 1, 2) representing permission levels, causing confusion during code review.", objective: "Declare `enum Permission { None = 0, Read = 1, Write = 2 }`. Write a function `describePermission(p: Permission): string` returning a human-readable label using a switch statement.", constraints: "Must use a numeric enum with explicit values. The function parameter must be typed `Permission`, not `number`.", expectedOutput: "`describePermission(Permission.Write)` returns: \"Write\"", check: "Calling `describePermission(Permission.None)` returns \"None\", confirming every enum branch is handled." },
  { id: 14, level: 3, title: "The Locked Application Config", scenario: "Your app's configuration object should be readable everywhere but never accidentally reassigned after startup.", objective: "Declare `const config: { readonly apiUrl: string; readonly timeout: number } = { apiUrl: \"https://api.example.com\", timeout: 5000 };`. Log both properties.", constraints: "Both properties must be marked `readonly` in the type. Do not use `Object.freeze` for this task — rely on the type system alone.", expectedOutput: "`console.log(config.apiUrl, config.timeout)` prints: https://api.example.com 5000", check: "Attempting `config.timeout = 9999` must produce a compile-time error due to the readonly modifier." },
  { id: 15, level: 3, title: "The Shape Area Discriminator", scenario: "A drawing app computes area for different shapes, each represented with a discriminant \"kind\" literal field.", objective: "Declare a union type `Shape = { kind: \"circle\"; radius: number } | { kind: \"square\"; side: number };`. Write `function area(s: Shape): number` that narrows on `s.kind` before computing.", constraints: "Must use a literal-typed \"kind\" field to discriminate. Must narrow with an `if (s.kind === \"circle\")` check before accessing radius.", expectedOutput: "`area({ kind: \"square\", side: 4 })` returns: 16", check: "Calling `area({ kind: \"circle\", radius: 2 })` returns approximately 12.57 (Math.PI * 2 * 2)." },
  { id: 16, level: 4, title: "The Const-Asserted Direction List", scenario: "A compass widget needs a fixed, precisely-typed list of valid directions instead of a generic string array.", objective: "Declare `const directions = [\"N\", \"S\", \"E\", \"W\"] as const;`. Declare `type Direction = typeof directions[number];` and a variable `let dir: Direction = \"N\";`.", constraints: "Must use `as const` on the array. Must derive the Direction type from `typeof directions[number]`, not write it manually.", expectedOutput: "`console.log(dir)` prints: N", check: "Attempting `dir = \"NE\"` must be a compile-time error since \"NE\" is not one of the four literal values captured by the const assertion." },
  { id: 17, level: 4, title: "The Non-Null DOM Guarantee", scenario: "Your app queries a DOM element you are certain (by prior verified logic) will always exist at this point in the code.", objective: "Simulate: `function findEl(): { text: string } | null { return { text: \"Hello\" }; }` then write `const el = findEl()!;` and log `el.text`.", constraints: "Must use the non-null assertion operator `!` rather than an `if` check or optional chaining. Add a comment explaining why it is safe here.", expectedOutput: "`console.log(el.text)` prints: Hello", check: "Removing the `!` and accessing `el.text` directly must produce a compile-time \"possibly null\" error." },
  { id: 18, level: 4, title: "The String Enum Status Codes", scenario: "An HTTP-adjacent module wants readable status labels that also serialize meaningfully when logged or sent over the wire.", objective: "Declare `enum ResponseStatus { Success = \"SUCCESS\", Failure = \"FAILURE\", Pending = \"PENDING\" }`. Log `ResponseStatus.Success` and `typeof ResponseStatus.Success`.", constraints: "Must be a string enum (every member explicitly assigned a string). Do not mix numeric and string values.", expectedOutput: "`console.log(ResponseStatus.Success, typeof ResponseStatus.Success)` prints: SUCCESS string", check: "Confirm `ResponseStatus.Success === \"SUCCESS\"` evaluates to true." },
  { id: 19, level: 4, title: "The Exhaustive Enum Switch", scenario: "A billing module handles subscription tiers and must guarantee every tier is explicitly handled, even after future additions.", objective: "Declare `enum Tier { Free, Pro, Enterprise }`. Write `function monthlyPrice(t: Tier): number` using a switch with a `default: const _exhaustive: never = t; throw new Error(\"Unhandled tier\");` fallback.", constraints: "Must include the `never`-typed exhaustiveness check in the default case. Every real Tier value must have its own case returning a specific number.", expectedOutput: "`monthlyPrice(Tier.Pro)` returns: 15 (or any consistent price you assign to Pro)", check: "Temporarily adding a new enum member without a matching switch case should cause the `never` assignment in default to fail to compile, proving the exhaustiveness check works." },
  { id: 20, level: 4, title: "The Mixed-Type Inventory Array", scenario: "A warehouse dashboard displays a feed that can contain either numeric quantities or string status messages, in any order.", objective: "Declare `let feed: (number | string)[] = [10, \"low stock\", 25, \"restocked\"];`. Log the array and use `.filter()` with a `typeof` check to log only the numbers.", constraints: "Must use the union element type `(number | string)[]`. The filter callback must narrow with `typeof item === \"number\"`.", expectedOutput: "The filtered numbers log as: [ 10, 25 ]", check: "Confirm the filtered array's inferred type is number[], allowing a subsequent `.reduce((a,b) => a+b, 0)` to compile without errors." },
  { id: 21, level: 5, title: "The Type-Safe Event Payload Map", scenario: "A pub/sub system needs each event name to carry its own specific, correctly-typed payload shape, checked at compile time.", objective: "Declare a type `EventPayloads = { login: { userId: number }; logout: {} };` and a function `function emit<K extends keyof EventPayloads>(event: K, payload: EventPayloads[K]): void { console.log(event, payload); }`.", constraints: "Must use `keyof EventPayloads` to constrain the generic K. The payload parameter's type must depend on K via `EventPayloads[K]`.", expectedOutput: "`emit(\"login\", { userId: 7 })` prints: login { userId: 7 }", check: "Calling `emit(\"login\", {})` (missing userId) must be a compile-time error, proving the payload type is correctly linked to the event name." },
  { id: 22, level: 5, title: "The Branded ID Type", scenario: "A codebase has separate UserID and ProductID values that are both plain numbers, but mixing them up has caused real bugs.", objective: "Declare `type UserId = number & { readonly __brand: \"UserId\" };` and a helper `function toUserId(n: number): UserId { return n as UserId; }`. Create a UserId and log it.", constraints: "Must use an intersection with a unique brand property to simulate nominal typing. Must use `toUserId()` rather than a raw `as UserId` cast at the call site.", expectedOutput: "`console.log(toUserId(42))` prints: 42", check: "Confirm that a plain `number` variable cannot be assigned directly to a `UserId`-typed variable without going through toUserId or an explicit cast, demonstrating the branding effect." },
  { id: 23, level: 5, title: "The Deep Readonly Config Tree", scenario: "A large nested configuration object must be fully immutable at every level, not just its top-level properties.", objective: "Declare a nested object `const settings = { ui: { theme: \"dark\", fontSize: 14 }, network: { timeout: 3000 } } as const;`. Log `settings.ui.theme`.", constraints: "Must apply `as const` to the whole object so nested properties become deeply readonly and literal-typed. Do not manually annotate readonly on every nested field.", expectedOutput: "`console.log(settings.ui.theme)` prints: dark", check: "Attempting `settings.ui.theme = \"light\"` must be a compile-time error, confirming the const assertion applies recursively to nested objects." },
  { id: 24, level: 5, title: "The Unknown-to-Validated Type Guard", scenario: "Your app parses untrusted JSON and must safely confirm it matches an expected shape before trusting any of its fields.", objective: "Declare `function isUser(val: unknown): val is { name: string; age: number } { return typeof val === \"object\" && val !== null && \"name\" in val && \"age\" in val; }`. Use it to narrow a `let data: unknown` value and log `data.name` only inside the narrowed branch.", constraints: "Must write a custom type predicate using the `val is Type` syntax, not a plain boolean return. Must only access `.name` inside the narrowed `if (isUser(data))` block.", expectedOutput: "For `data = { name: \"Ann\", age: 30 }`, the narrowed branch logs: Ann", check: "Attempting `data.name` before the isUser() check (while data is still unknown) must be a compile-time error." },
  { id: 25, level: 5, title: "The Numeric Literal State Machine", scenario: "An elevator control system must only allow floor numbers from a small, fixed, safety-verified set — no arbitrary numbers.", objective: "Declare `type Floor = 1 | 2 | 3 | 4 | 5;`. Write `function goToFloor(f: Floor): void { console.log(\"Moving to floor\", f); }` and call it with a valid floor.", constraints: "Must use a numeric literal union type for Floor, not `number`. The function parameter must be typed `Floor`.", expectedOutput: "`goToFloor(3)` prints: Moving to floor 3", check: "Calling `goToFloor(10)` must be a compile-time error since 10 is not one of the five allowed literal values." },
],
interfaces: [
  { id: 1, level: 1, title: "The Book Catalog Shape", scenario: "A library app needs a consistent shape for book records displayed in a catalog list.", objective: "Declare `interface Book { title: string; author: string; pages: number; }`. Create `const b: Book = { title: \"Dune\", author: \"Herbert\", pages: 412 };` and log all three fields.", constraints: "Must use `interface`, not `type`, for this task. All three properties must be required (no `?`).", expectedOutput: "`console.log(b.title, b.author, b.pages)` prints: Dune Herbert 412", check: "Removing any one property from the object literal (e.g. omitting pages) must produce a compile-time error." },
  { id: 2, level: 1, title: "The Optional Bio Field", scenario: "A user profile interface needs a bio field that most new users have not filled in yet.", objective: "Declare `interface Profile { username: string; bio?: string; }`. Create a profile without bio, then log `profile.bio ?? \"No bio yet\"`.", constraints: "bio must be marked optional with `?`. Do not provide a bio in the object literal.", expectedOutput: "`console.log(profile.bio ?? \"No bio yet\")` prints: No bio yet", check: "Creating a second profile that DOES include bio: \"Loves TS\" and logging the same expression prints \"Loves TS\", confirming the optional field works both ways." },
  { id: 3, level: 1, title: "The Immutable API Key", scenario: "A configuration interface stores an API key that must never be reassigned after the config object is created.", objective: "Declare `interface Config { readonly apiKey: string; timeout: number; }`. Create a config object and log `config.apiKey`.", constraints: "apiKey must be marked `readonly`. timeout must remain a normal (non-readonly) property.", expectedOutput: "`console.log(config.apiKey)` prints whatever string you assigned, e.g.: sk-12345", check: "Attempting `config.apiKey = \"new-key\"` must be a compile-time error, while `config.timeout = 8000` must compile successfully." },
  { id: 4, level: 1, title: "The Type Alias Point", scenario: "A small graphics utility needs a simple, reusable 2D coordinate shape.", objective: "Declare `type Point = { x: number; y: number };`. Create two points and write a function `function distanceX(a: Point, b: Point): number { return Math.abs(a.x - b.x); }`.", constraints: "Must use `type`, not `interface`, for this task. Both point parameters in the function must be typed `Point`.", expectedOutput: "`distanceX({ x: 1, y: 1 }, { x: 5, y: 9 })` returns: 4", check: "Passing an object missing the y property to distanceX must be a compile-time error, since Point requires both x and y." },
  { id: 5, level: 1, title: "The Method-Bearing Shape", scenario: "A geometry app needs every shape to be able to report its own area through a consistent method.", objective: "Declare `interface Shape { area(): number; }`. Create `const square: Shape = { area() { return 16; } };` and log `square.area()`.", constraints: "The interface must declare area as a method signature, not a property holding a function type. The implementation must be an object literal, not a class.", expectedOutput: "`console.log(square.area())` prints: 16", check: "Creating an object literal without an area method and assigning it to a Shape-typed variable must be a compile-time error." },
  { id: 6, level: 2, title: "The Extended Employee Record", scenario: "An HR system has a base Person shape and needs an Employee shape that includes everything a Person has, plus job-specific fields.", objective: "Declare `interface Person { name: string; age: number; }` and `interface Employee extends Person { salary: number; }`. Create an Employee object and log all three fields.", constraints: "Employee must use `extends Person`, not redeclare name and age itself. All fields remain required.", expectedOutput: "`console.log(emp.name, emp.age, emp.salary)` prints: e.g. Ann 30 75000", check: "Creating an object missing the inherited `age` property and assigning it to an Employee-typed variable must be a compile-time error." },
  { id: 7, level: 2, title: "The Status Literal Union Ticket", scenario: "A support ticket system must restrict status to exactly three known values to prevent invalid states.", objective: "Declare `type Status = \"open\" | \"closed\" | \"escalated\";` and `interface Ticket { id: number; status: Status; }`. Create a ticket and log it.", constraints: "status must use the Status type alias, not a plain `string`. Must combine a type alias with an interface, as shown.", expectedOutput: "`console.log(ticket.id, ticket.status)` prints: e.g. 1 open", check: "Attempting to create a ticket with `status: \"pending\"` must be a compile-time error since \"pending\" is not part of the Status union." },
  { id: 8, level: 2, title: "The Product Price Index", scenario: "An inventory system needs a lookup structure mapping arbitrary product SKUs (strings) to their prices (numbers).", objective: "Declare `interface PriceList { [sku: string]: number; }`. Create `const prices: PriceList = { A100: 9.99, B200: 14.5 };` and log a computed sum of all values using `Object.values()`.", constraints: "Must use an index signature `[sku: string]: number`, not fixed named properties. Do not hardcode the two SKU names as separate properties.", expectedOutput: "`console.log(Object.values(prices).reduce((a, b) => a + b, 0))` prints: 24.49", check: "Adding a third entry like `prices.C300 = 5` at runtime must compile without error, confirming arbitrary string keys are accepted." },
  { id: 9, level: 2, title: "The Intersection Manager Role", scenario: "A staffing system needs a Manager type that combines an Employee shape with additional team-management fields.", objective: "Declare `interface Employee { name: string; salary: number; }` and `type Manager = Employee & { teamSize: number };`. Create a Manager object and log all three fields.", constraints: "Must use the `&` intersection operator on a type alias, not `extends` on an interface, for this task.", expectedOutput: "`console.log(mgr.name, mgr.salary, mgr.teamSize)` prints: e.g. Sam 90000 5", check: "Omitting teamSize from the object literal assigned to Manager must be a compile-time error, since the intersection requires all combined fields." },
  { id: 10, level: 2, title: "The Multi-Interface Combo Badge", scenario: "A gamification system awards badges that must satisfy two separate capability interfaces at once: being displayable and being shareable.", objective: "Declare `interface Displayable { label: string; }` and `interface Shareable { shareUrl: string; }` and `interface Badge extends Displayable, Shareable { earnedAt: string; }`. Create a Badge and log all three fields.", constraints: "Badge must extend BOTH Displayable and Shareable in a single extends clause. All three resulting fields must be required.", expectedOutput: "`console.log(badge.label, badge.shareUrl, badge.earnedAt)` prints: e.g. Champion https://x.co/b1 2026-01-01", check: "Omitting shareUrl from the Badge object literal must be a compile-time error, since it is inherited as required from Shareable." },
  { id: 11, level: 3, title: "The Comparable Currency Amount", scenario: "A finance app needs Money objects that can be compared to each other consistently across the codebase.", objective: "Declare `interface Comparable<T> { compareTo(other: T): number; }` and a class `class Money implements Comparable<Money> { constructor(public cents: number) {} compareTo(other: Money) { return this.cents - other.cents; } }`. Compare two Money instances.", constraints: "Must use a generic interface with `implements`, not a plain method with no interface. The class must be typed `Comparable<Money>`.", expectedOutput: "`new Money(500).compareTo(new Money(300))` returns: 200", check: "Removing the compareTo method from the class must produce a compile-time error stating the class incorrectly implements Comparable<Money>." },
  { id: 12, level: 3, title: "The Generic API Response Wrapper", scenario: "An API client needs one reusable response shape that works for many different endpoint data types.", objective: "Declare `interface ApiResponse<T> { status: number; data: T; }`. Create `const res: ApiResponse<string[]> = { status: 200, data: [\"a\", \"b\"] };` and log `res.data.length`.", constraints: "Must use a generic interface with a type parameter `T` for the data field. Must instantiate it with `ApiResponse<string[]>`, not `ApiResponse<any>`.", expectedOutput: "`console.log(res.data.length)` prints: 2", check: "Instantiating `ApiResponse<number>` and assigning `data: [\"x\"]` (a string array) must be a compile-time error." },
  { id: 13, level: 3, title: "The Nested Address Interface", scenario: "A shipping form needs a customer record with a nested, independently-defined address shape.", objective: "Declare `interface Address { city: string; zip: string; }` and `interface Customer { name: string; address: Address; }`. Create a customer and log `customer.address.city`.", constraints: "Address must be its own separate interface, not an inline object type inside Customer. Both interfaces' fields remain required.", expectedOutput: "`console.log(customer.address.city)` prints: e.g. Reno", check: "Creating a Customer whose address object is missing the zip field must be a compile-time error." },
  { id: 14, level: 3, title: "The Recursive Comment Thread", scenario: "A discussion forum needs comments that can have their own nested replies, of the exact same shape, to any depth.", objective: "Declare `interface Comment { text: string; replies: Comment[]; }`. Create a comment with one nested reply and log `comment.replies[0].text`.", constraints: "The interface must reference itself in the replies field type (Comment[]), demonstrating a self-referential interface.", expectedOutput: "`console.log(comment.replies[0].text)` prints: e.g. Nice point!", check: "Creating a reply object missing the required replies field (even as an empty array) must be a compile-time error." },
  { id: 15, level: 3, title: "The Excess Property Catch", scenario: "A form-submission handler expects a strict Config shape, and a typo in a field name should be caught immediately, not silently ignored.", objective: "Declare `interface Config { timeout: number; }` and `function setup(cfg: Config): void { console.log(cfg.timeout); }`. Call setup with a correctly-shaped object literal.", constraints: "Must call setup with an inline object literal (not a pre-declared variable) to trigger excess property checking.", expectedOutput: "`setup({ timeout: 3000 })` prints: 3000", check: "Calling `setup({ timeout: 3000, retries: 3 })` (an unrecognized extra field on a literal) must be a compile-time excess-property error." },
  { id: 16, level: 4, title: "The Discriminated Payment Method", scenario: "A checkout system supports multiple payment methods, each with different required fields, and must handle each type safely.", objective: "Declare `type Payment = { kind: \"card\"; last4: string } | { kind: \"paypal\"; email: string };`. Write `function describe(p: Payment): string` that narrows on `p.kind` before accessing the type-specific field.", constraints: "Must use a literal \"kind\" discriminant field. Must narrow with an `if (p.kind === \"card\")` (or switch) check before accessing last4 or email.", expectedOutput: "`describe({ kind: \"card\", last4: \"4242\" })` returns: e.g. \"Card ending in 4242\"", check: "Calling describe with `{ kind: \"paypal\", email: \"a@b.com\" }` returns a string referencing the email, confirming both branches are handled." },
  { id: 17, level: 4, title: "The Callable Debounce Interface", scenario: "A UI utility wraps a function in a debounce mechanism, and the wrapped result is itself callable but also exposes a cancel method.", objective: "Declare `interface Debounced { (msg: string): void; cancel(): void; }`. Create an object satisfying this hybrid type (a function with an attached cancel property) using `Object.assign`.", constraints: "Must use a call signature alongside a named method in the same interface. The implementation must actually be callable AND have a cancel method.", expectedOutput: "Calling the debounced object like `fn(\"go\")` logs \"go\", and `fn.cancel()` runs without error.", check: "Removing the call signature from the interface (keeping only cancel) and then calling `fn(\"go\")` as a function must become a compile-time error." },
  { id: 18, level: 4, title: "The Constrained Repository Add", scenario: "A generic data repository must only accept items that at least have an `id` field, for any entity type used with it.", objective: "Declare `interface Identifiable { id: number; }` and `interface Repository<T extends Identifiable> { items: T[]; add(item: T): void; }`. Implement it for a `{ id: number; name: string }` item type and add one item.", constraints: "The generic parameter T must be constrained with `extends Identifiable`. The concrete item type used must include an id field.", expectedOutput: "After `repo.add({ id: 1, name: \"Widget\" })`, `console.log(repo.items.length)` prints: 1", check: "Attempting to instantiate Repository with an item type that has no id field must be a compile-time error due to the generic constraint." },
  { id: 19, level: 4, title: "The Declaration-Merged Plugin Config", scenario: "A plugin architecture lets independently-loaded plugin files each contribute their own optional settings to one shared config interface.", objective: "Declare `interface PluginConfig { core: boolean; }` in one place, then declare a second `interface PluginConfig { analytics?: boolean; }` elsewhere in the same file, and create an object satisfying the merged shape.", constraints: "Must declare PluginConfig twice with the same name to demonstrate declaration merging. The merged interface must end up requiring core and allowing optional analytics.", expectedOutput: "`console.log(cfg.core, cfg.analytics)` prints: e.g. true undefined (if analytics is omitted)", check: "Confirm that an object providing only `{ core: true }` (omitting analytics) still satisfies the merged PluginConfig type, since analytics is optional." },
  { id: 20, level: 4, title: "The Keyed Event Handler Map", scenario: "An event system must only allow registering handlers for known event names, catching typos like \"clcik\" at compile time.", objective: "Declare `interface EventMap { click: () => void; hover: () => void; }` and `function on<K extends keyof EventMap>(event: K, handler: EventMap[K]): void { console.log(\"registered\", event); }`. Register a handler for \"click\".", constraints: "Must constrain the generic K with `keyof EventMap`. The handler parameter's type must be `EventMap[K]`, not a generic function type.", expectedOutput: "`on(\"click\", () => {})` prints: registered click", check: "Calling `on(\"scroll\", () => {})` must be a compile-time error since \"scroll\" is not a key of EventMap." },
  { id: 21, level: 5, title: "The Generic Linked List Node", scenario: "A data-structures library needs a reusable, generic, self-referential node type for a singly linked list of any element type.", objective: "Declare `interface Node<T> { value: T; next: Node<T> | null; }`. Build a 2-node linked list of numbers and log the second node's value via `.next?.value`.", constraints: "Must be generic over T and self-referential via `next: Node<T> | null`. Must use optional chaining (`?.`) to access next.value safely.", expectedOutput: "`console.log(head.next?.value)` prints: e.g. 2", check: "Setting next to null on the last node and accessing `.next?.value` on it must safely log undefined, not throw a runtime error." },
  { id: 22, level: 5, title: "The Type-Predicate Shape Validator", scenario: "A drawing app receives unknown JSON-like data and must safely confirm it matches a Circle interface before using it as one.", objective: "Declare `interface Circle { kind: \"circle\"; radius: number; }` and `function isCircle(val: unknown): val is Circle { return typeof val === \"object\" && val !== null && (val as Circle).kind === \"circle\"; }`. Use it to narrow an unknown value and log its radius.", constraints: "Must use a custom type predicate (`val is Circle`), not a plain boolean return. Must only access `.radius` inside the narrowed branch.", expectedOutput: "For a matching value, the narrowed branch logs the radius, e.g.: 5", check: "Accessing `.radius` on the unknown-typed value before calling isCircle() must be a compile-time error." },
  { id: 23, level: 5, title: "The Generic Constrained Max Function", scenario: "A ranking utility needs to find the \"larger\" of two items for any type that knows how to compare itself, using a shared Comparable contract.", objective: "Declare `interface Comparable<T> { compareTo(other: T): number; }` and `function max<T extends Comparable<T>>(a: T, b: T): T { return a.compareTo(b) >= 0 ? a : b; }`. Use it with a class implementing Comparable.", constraints: "The generic T must be constrained with `extends Comparable<T>`. Must demonstrate the function with at least one concrete class.", expectedOutput: "Given two Money-like instances of value 100 and 50, `max(a, b)` returns the instance representing 100.", check: "Attempting to call max with a plain object that lacks a compareTo method must be a compile-time error due to the generic constraint." },
  { id: 24, level: 5, title: "The Mapped Partial Update Shape", scenario: "An update-profile API endpoint should accept any subset of a full Profile's fields, since users only send the fields they changed.", objective: "Declare `interface Profile { name: string; email: string; age: number; }` and `type ProfileUpdate = { [K in keyof Profile]?: Profile[K] };`. Apply a partial update object to a base profile using `Object.assign` or spread.", constraints: "Must use a mapped type with `[K in keyof Profile]?:`, not simply reference a manually-written optional interface. Demonstrate merging a partial update into a full Profile.", expectedOutput: "Merging `{ email: \"new@x.com\" }` into a profile leaves name and age unchanged and updates only email.", check: "Confirm ProfileUpdate accepts an empty object `{}` as valid, since a mapped type with all-optional fields permits omitting every property." },
  { id: 25, level: 5, title: "The Branded Nominal ID Interface", scenario: "A large system has UserId and OrderId that are both structurally plain numbers, but a real bug occurred from passing one where the other was expected.", objective: "Declare `interface Branded<T, B> { value: T; readonly __brand: B; }` and `type UserId = Branded<number, \"UserId\">;` and a helper `function makeUserId(n: number): UserId { return { value: n, __brand: \"UserId\" } as UserId; }`.", constraints: "Must use a generic Branded interface, not hardcode the brand logic separately for each ID type. Must construct UserId only through makeUserId.", expectedOutput: "`console.log(makeUserId(42).value)` prints: 42", check: "Confirm that constructing an object shaped like UserId but with a different __brand literal (e.g. \"OrderId\") is not assignable to the UserId type, demonstrating the nominal-typing simulation." },
],
functiontypes: [
  { id: 1, level: 1, title: "The Typed Rectangle Area", scenario: "A geometry helper module needs a simple, fully-typed function that computes rectangle area.", objective: "Write `function area(width: number, height: number): number { return width * height; }` and call it with 5 and 3.", constraints: "Both parameters and the return value must be explicitly typed `number`. Do not use `any`.", expectedOutput: "`console.log(area(5, 3))` prints: 15", check: "Calling `area(\"5\", 3)` must produce a compile-time error since the first parameter expects a number, not a string." },
  { id: 2, level: 1, title: "The Silent Alert Logger", scenario: "A notifications module has a function whose whole purpose is a side effect (logging), with no meaningful return value.", objective: "Write `function alertUser(message: string): void { console.log(\"ALERT:\", message); }` and call it with \"Low battery\".", constraints: "The return type must be explicitly `void`. message must be typed `string`.", expectedOutput: "`alertUser(\"Low battery\")` prints: ALERT: Low battery", check: "`const r = alertUser(\"x\"); console.log(r);` logs undefined, confirming the void function returns no usable value." },
  { id: 3, level: 1, title: "The Boolean Age Checker Arrow", scenario: "A form validator needs a small arrow function that checks whether an age value qualifies as an adult.", objective: "Write `const isAdult = (age: number): boolean => age >= 18;` and call it with 16 and with 20.", constraints: "Must be written as an arrow function with explicit parameter and return types, not a regular `function`.", expectedOutput: "`console.log(isAdult(16), isAdult(20))` prints: false true", check: "Calling `isAdult(true)` (a boolean instead of a number) must be a compile-time error." },
  { id: 4, level: 1, title: "The Uppercase String Transformer", scenario: "A text-processing utility needs a function that both accepts and returns a string, fully typed.", objective: "Write `function shout(text: string): string { return text.toUpperCase() + \"!\"; }` and call it with \"hello\".", constraints: "Both the parameter and return type must be `string`. Do not leave the return type implicit.", expectedOutput: "`console.log(shout(\"hello\"))` prints: HELLO!", check: "Calling `shout(42)` (a number) must be a compile-time error since the parameter requires a string." },
  { id: 5, level: 1, title: "The Even Number Predicate", scenario: "A filtering utility needs a small typed function that determines whether a number is even.", objective: "Write `function isEven(n: number): boolean { return n % 2 === 0; }` and use it inside `[1,2,3,4].filter(isEven)`.", constraints: "n must be typed `number`, and the return type must be `boolean`. Use the function directly as the filter callback (no wrapper arrow needed).", expectedOutput: "`console.log([1,2,3,4].filter(isEven))` prints: [ 2, 4 ]", check: "Confirm the filtered array's inferred type is number[], allowing further arithmetic operations on its elements without additional casts." },
  { id: 6, level: 2, title: "The Optional Greeting Title", scenario: "A greeting utility should work whether or not the caller provides an honorific title.", objective: "Write `function greet(name: string, title?: string): string { return title ? `${title} ${name}` : name; }`. Call it once with just a name, and once with a name and title.", constraints: "title must be marked optional with `?`, not given a default value. Both calls must compile without extra arguments.", expectedOutput: "`greet(\"Lee\")` returns \"Lee\"; `greet(\"Lee\", \"Dr.\")` returns \"Dr. Lee\"", check: "Calling `greet()` with zero arguments must be a compile-time error, since name remains required." },
  { id: 7, level: 2, title: "The Defaulted Tax Calculator", scenario: "A checkout function computes a total with tax, but most callers use the store's standard 8% rate and rarely override it.", objective: "Write `function totalWithTax(price: number, taxRate: number = 0.08): number { return price + price * taxRate; }`. Call it once with only a price, and once with a custom rate.", constraints: "taxRate must use a default parameter value (`= 0.08`), not be marked optional with `?`.", expectedOutput: "`totalWithTax(100)` returns 108; `totalWithTax(100, 0.1)` returns 110", check: "Confirm that inside the function body, taxRate is always a real number (never undefined) even when the caller omits it." },
  { id: 8, level: 2, title: "The Variadic Tag Joiner", scenario: "A blogging tool needs to join any number of hashtags into one string, without a fixed argument limit.", objective: "Write `function joinTags(...tags: string[]): string { return tags.map(t => \"#\" + t).join(\" \"); }` and call it with three tags.", constraints: "Must use a rest parameter (`...tags: string[]`), not a fixed-arity signature or an array parameter passed explicitly.", expectedOutput: "`console.log(joinTags(\"ts\", \"code\", \"learn\"))` prints: #ts #code #learn", check: "Calling joinTags with zero arguments must compile and return an empty string, confirming rest parameters accept any count including zero." },
  { id: 9, level: 2, title: "The Typed Math Operation Alias", scenario: "A calculator app wants a single reusable type describing any binary numeric operation function, to avoid repeating the signature everywhere.", objective: "Declare `type MathOp = (a: number, b: number) => number;`. Create `const add: MathOp = (a, b) => a + b;` and `const multiply: MathOp = (a, b) => a * b;`. Log both results for 4 and 5.", constraints: "Both add and multiply must be explicitly typed with the MathOp alias, not have their own separate inline function type annotations.", expectedOutput: "`console.log(add(4, 5), multiply(4, 5))` prints: 9 20", check: "Assigning a function that returns a string to a MathOp-typed variable must be a compile-time error." },
  { id: 10, level: 2, title: "The Callback-Accepting Processor", scenario: "A data-processing utility applies a caller-supplied transformation function to each item in a list.", objective: "Write `function processAll(items: number[], transform: (n: number) => number): number[] { return items.map(transform); }`. Call it with `[1,2,3]` and a doubling callback.", constraints: "The transform parameter must be typed as a function type expression `(n: number) => number`, not `Function` or `any`.", expectedOutput: "`console.log(processAll([1,2,3], x => x * 2))` prints: [ 2, 4, 6 ]", check: "Passing a callback typed `(n: string) => number` as transform must be a compile-time error due to the parameter type mismatch." },
  { id: 11, level: 3, title: "The Error-First Callback Loader", scenario: "A file-loading utility follows the classic Node-style pattern of a callback that receives either an error or data, never both.", objective: "Write `function loadFile(path: string, callback: (err: Error | null, data?: string) => void): void { callback(null, \"file contents\"); }`. Call it, logging data inside the callback.", constraints: "The callback parameter's error argument must be typed `Error | null`, and data must be optional. Must actually invoke callback inside loadFile.", expectedOutput: "The callback logs: file contents", check: "Writing a callback implementation that reads `data.length` without first checking `if (data)` should raise a compile-time \"possibly undefined\" warning." },
  { id: 12, level: 3, title: "The Discount Function With Safe Default", scenario: "A pricing function almost broke in production because an optional discount percent was used in arithmetic without a fallback, producing NaN.", objective: "Write `function applyDiscount(price: number, percent: number = 0): number { return price - price * percent; }`. Call it once with just a price and once with a 20% discount (0.2).", constraints: "Must use a default parameter (not `?`) specifically to guarantee percent is always a real number inside the function body.", expectedOutput: "`applyDiscount(100)` returns 100; `applyDiscount(100, 0.2)` returns 80", check: "Confirm that removing the default value and calling `applyDiscount(100)` without an argument would be a compile-time error, showing why the default matters." },
  { id: 13, level: 3, title: "The Validator Function Type Alias", scenario: "A form library wants every field validator to share one precise, reusable function type instead of ad-hoc inline types scattered everywhere.", objective: "Declare `type Validator = (value: string) => boolean;`. Write `const isNonEmpty: Validator = (v) => v.trim().length > 0;` and `const isEmail: Validator = (v) => v.includes(\"@\");`. Test both against \"a@b.com\".", constraints: "Both validators must be explicitly typed with the Validator alias. Do not give either its own separate inline type.", expectedOutput: "`console.log(isNonEmpty(\"a@b.com\"), isEmail(\"a@b.com\"))` prints: true true", check: "Assigning a function that takes a number instead of a string to a Validator-typed variable must be a compile-time error." },
  { id: 14, level: 3, title: "The Guaranteed-Throw Parse Helper", scenario: "A config-parsing module has an internal helper whose entire job is to fail loudly and stop execution — it must never return a value.", objective: "Write `function fail(message: string): never { throw new Error(message); }`. Write `function parsePort(raw: string): number { const n = Number(raw); if (isNaN(n)) fail(\"Invalid port: \" + raw); return n; }`. Call parsePort with \"8080\".", constraints: "fail must be typed to return `never`, and must always throw with no other code path. parsePort must call fail on invalid input.", expectedOutput: "`console.log(parsePort(\"8080\"))` prints: 8080", check: "Calling `parsePort(\"abc\")` must throw an Error with message \"Invalid port: abc\" rather than returning NaN." },
  { id: 15, level: 3, title: "The Middleware Chain Composer", scenario: "A small server framework runs each request through a chain of middleware functions that log and then call the next one in line.", objective: "Declare `type Middleware = (req: string, next: () => string) => string;`. Write `const logger: Middleware = (req, next) => `[${req}] ${next()}`;` and call it with `logger(\"GET /\", () => \"200 OK\")`.", constraints: "Must use the Middleware type alias for logger, not an inline type. next must be typed as a no-argument function returning a string.", expectedOutput: "`console.log(logger(\"GET /\", () => \"200 OK\"))` prints: [GET /] 200 OK", check: "Assigning a function whose next parameter takes an argument (e.g. `(req, next: (x: number) => string)`) to a Middleware-typed variable must be a compile-time error." },
  { id: 16, level: 4, title: "The Generic Identity Cache Getter", scenario: "A caching utility needs a generic function that works uniformly with any value type while preserving that exact type through the return.", objective: "Write `function identity<T>(value: T): T { return value; }`. Call it with a number, then with a string, and log both with their `typeof`.", constraints: "Must use a generic type parameter `<T>`, not `any`. The return type must be exactly T, not a union or any.", expectedOutput: "`console.log(identity(5), typeof identity(5))` prints: 5 number; `console.log(identity(\"x\"), typeof identity(\"x\"))` prints: x string", check: "Confirm that `const n: string = identity(5);` is a compile-time error, proving T is correctly inferred as number for that call and not widened to any." },
  { id: 17, level: 4, title: "The Length-Constrained Longest Finder", scenario: "A utility needs to return whichever of two values is \"longer,\" working for strings, arrays, or anything else with a length property.", objective: "Write `function longest<T extends { length: number }>(a: T, b: T): T { return a.length >= b.length ? a : b; }`. Call it with two strings and separately with two arrays.", constraints: "The generic T must be constrained with `extends { length: number }`, not left unconstrained or typed any.", expectedOutput: "`longest(\"hi\", \"hello\")` returns \"hello\"; `longest([1,2], [1,2,3])` returns [1,2,3]", check: "Calling `longest(5, 10)` (plain numbers, which have no length property) must be a compile-time error due to the generic constraint." },
  { id: 18, level: 4, title: "The Overloaded Normalize Function", scenario: "A utility function should accept either a single string or an array of strings, and always return an array — but callers should see precise per-case types.", objective: "Write overload signatures `function normalize(input: string): string[];` and `function normalize(input: string[]): string[];`, then implement `function normalize(input: string | string[]): string[] { return Array.isArray(input) ? input : [input]; }`.", constraints: "Must declare both overload signatures separately before the single shared implementation. The implementation signature's parameter must be broad enough to cover both.", expectedOutput: "`normalize(\"a\")` returns [\"a\"]; `normalize([\"a\",\"b\"])` returns [\"a\",\"b\"]", check: "Calling `normalize(42)` (a number, matching neither overload) must be a compile-time error." },
  { id: 19, level: 4, title: "The Retry-With-Backoff Wrapper", scenario: "A network utility wraps any zero-argument function and retries it a limited number of times if it throws, useful for flaky operations.", objective: "Write `function retry<T>(fn: () => T, attempts: number): T { try { return fn(); } catch { if (attempts <= 1) throw new Error(\"failed\"); return retry(fn, attempts - 1); } }`. Test it with a function that fails twice then succeeds.", constraints: "Must be generic over the return type T of fn. Must recursively call itself with a decremented attempts count.", expectedOutput: "Using a counter-based test function that fails until the 3rd call, `retry(fn, 5)` returns: \"ok\" (or whatever success value the test function returns)", check: "Confirm that after exhausting all attempts without success, retry ultimately throws an Error rather than returning a fake or undefined value." },
  { id: 20, level: 4, title: "The This-Aware Reset Method", scenario: "A standalone reset function is meant to always be called as a method on a counter-like object, and misuse (like detaching it) should be caught by the compiler.", objective: "Write `function reset(this: { count: number }): void { this.count = 0; }`. Attach it to an object like `const counter = { count: 5, reset };` and call `counter.reset()`.", constraints: "Must declare a `this` parameter as the first parameter with the expected shape `{ count: number }`. Do not use an arrow function for this task, since arrow functions cannot have a this parameter.", expectedOutput: "`counter.reset(); console.log(counter.count);` prints: 0", check: "Calling `reset()` on its own, detached from any object with a count property, must be a compile-time error due to the this parameter constraint." },
  { id: 21, level: 5, title: "The Generic Function Composer", scenario: "A functional-utilities module needs a reusable `compose` helper that chains two typed functions together, preserving full type safety through the chain.", objective: "Write `function compose<A, B, C>(f: (a: A) => B, g: (b: B) => C): (a: A) => C { return (a) => g(f(a)); }`. Compose an \"add 1\" function with a \"double\" function and call the result on 3.", constraints: "Must use three independent generic type parameters (A, B, C) matching the input, intermediate, and output types. Must return a new function, not immediately compute a value.", expectedOutput: "`compose((x: number) => x + 1, (x: number) => x * 2)(3)` returns: 8", check: "Composing two functions where g's parameter type does not match f's return type must be a compile-time error." },
  { id: 22, level: 5, title: "The Memoizing Function Wrapper", scenario: "An expensive calculation function is called repeatedly with the same inputs, and a generic memoization wrapper should cache results by argument.", objective: "Write `function memoize(fn: (n: number) => number): (n: number) => number { const cache = new Map<number, number>(); return (n) => { if (cache.has(n)) return cache.get(n)!; const result = fn(n); cache.set(n, result); return result; }; }`. Wrap a call-counting square function and call it twice with the same input.", constraints: "Must use a `Map<number, number>` for the cache, with the non-null assertion `!` when reading a confirmed-present cached value. The wrapped function's underlying call count must only increase once for repeated identical inputs.", expectedOutput: "Calling the memoized square(4) twice results in the underlying function only actually running once, confirmed by a call counter equal to 1.", check: "Calling the memoized function with a new input (e.g. 5) after caching 4 must invoke the underlying function again, proving the cache is keyed per argument." },
  { id: 23, level: 5, title: "The Curried Three-Argument Adder", scenario: "A functional programming exercise requires a fully curried addition function where each argument is supplied one call at a time.", objective: "Write `function curry(a: number): (b: number) => (c: number) => number { return (b) => (c) => a + b + c; }` and call `curry(1)(2)(3)`.", constraints: "Must return nested arrow functions with fully annotated parameter and return types at every level, not a single flattened function.", expectedOutput: "`console.log(curry(1)(2)(3))` prints: 6", check: "Confirm that `curry(1)` alone (without further calls) has the type `(b: number) => (c: number) => number`, a callable function, not a final number." },
  { id: 24, level: 5, title: "The Exhaustive Discriminated Handler", scenario: "A UI action-dispatch function must handle every possible action type in a Redux-like system, and the compiler should catch any missed case if a new action is ever added.", objective: "Declare `type Action = { type: \"increment\" } | { type: \"decrement\" } | { type: \"reset\" };` and `function reduce(state: number, action: Action): number` using a switch with a `default: const _exhaustive: never = action; throw new Error(\"Unhandled action\");` fallback.", constraints: "Must include the never-typed exhaustiveness check in the default case. Every real Action variant must have its own case.", expectedOutput: "`reduce(5, { type: \"increment\" })` returns: 6", check: "Temporarily adding a new Action variant without adding a matching switch case should cause the never assignment in default to fail to compile." },
  { id: 25, level: 5, title: "The Type-Safe Event Emitter Function", scenario: "A pub/sub emitter needs its `emit` function to only accept payloads matching the exact shape registered for each specific event name.", objective: "Declare `type Events = { login: { userId: number }; logout: undefined };` and `function emit<K extends keyof Events>(event: K, payload: Events[K]): void { console.log(event, payload); }`. Call emit for both event types.", constraints: "Must constrain the generic K with `keyof Events`. The payload parameter's type must depend on K via `Events[K]`, not be a fixed shape.", expectedOutput: "`emit(\"login\", { userId: 7 })` prints: login { userId: 7 }; `emit(\"logout\", undefined)` prints: logout undefined", check: "Calling `emit(\"login\", undefined)` (mismatched payload for that event) must be a compile-time error, proving the payload type is linked to the specific event name." },
],
arraystuples: [
  { id: 1, level: 1, title: "The GPS Coordinate Pair", scenario: "You are building a delivery tracking app that stores a driver's current location as a fixed latitude/longitude pair.", objective: "Declare `const location: [number, number] = [12.9716, 77.5946]`. Log `location[0]` and `location[1]` separately.", constraints: "Must use a tuple type [number, number], not a plain number[]. Do not use an object instead.", expectedOutput: "`console.log(location[0], location[1])` prints: 12.9716 77.5946", check: "Attempting `location = [1, 2, 3]` should be a type error since the tuple requires exactly 2 numbers." },
  { id: 2, level: 1, title: "The Blog Post Tag List", scenario: "A blogging platform lets authors attach an arbitrary number of tags to each post.", objective: "Declare `const tags: string[] = [\"typescript\", \"webdev\"]`. Push \"tutorial\" onto it. Log the final array.", constraints: "Must use the string[] array type. Use .push() to add the new tag, not reassignment.", expectedOutput: "`console.log(tags)` prints: [\"typescript\", \"webdev\", \"tutorial\"]", check: "`tags.length === 3`. `typeof tags[0] === \"string\"`." },
  { id: 3, level: 1, title: "The Traffic Light States", scenario: "You are building a crosswalk simulator where the traffic light can only ever be Red, Yellow, or Green.", objective: "Declare `enum TrafficLight { Red, Yellow, Green }`. Log `TrafficLight.Red` and `TrafficLight.Green`.", constraints: "Must use the enum keyword. Do not assign explicit numeric values — rely on auto-increment from 0.", expectedOutput: "`console.log(TrafficLight.Red, TrafficLight.Green)` prints: 0 2", check: "`TrafficLight.Yellow === 1`. `TrafficLight[0] === \"Red\"` (reverse mapping)." },
  { id: 4, level: 1, title: "The Immutable Product SKU List", scenario: "An inventory system loads a list of product SKUs at startup that must never be accidentally modified afterward.", objective: "Declare `const skus: readonly string[] = [\"SKU-001\", \"SKU-002\", \"SKU-003\"]`. Log the array and its length.", constraints: "Must use readonly string[]. Do not call any mutating array methods.", expectedOutput: "`console.log(skus, skus.length)` prints: [\"SKU-001\",\"SKU-002\",\"SKU-003\"] 3", check: "Attempting `skus.push(\"SKU-004\")` must be a compile-time type error." },
  { id: 5, level: 1, title: "The Weekly Sales Totals", scenario: "A dashboard tracks daily sales totals for a 7-day rolling week as a simple list of numbers.", objective: "Declare `const sales: number[] = [120, 340, 210, 450, 300, 500, 275]`. Log the sum using reduce.", constraints: "Must use number[] and Array.prototype.reduce for the sum, not a manual loop.", expectedOutput: "`console.log(sales.reduce((a, b) => a + b, 0))` prints: 2195", check: "`sales.length === 7`. The reduce call must use 0 as the initial accumulator value." },
  { id: 6, level: 2, title: "The Min-Max Range Finder", scenario: "A charting library needs a function that returns both the minimum and maximum of a dataset as a fixed pair.", objective: "Write `function minMax(nums: number[]): [number, number]` returning `[Math.min(...nums), Math.max(...nums)]`. Destructure the result into `lo` and `hi` and log them.", constraints: "The return type must be the tuple [number, number], not number[]. Use array destructuring to unpack the result.", expectedOutput: "For minMax([4, 1, 9, 3]): `console.log(lo, hi)` prints: 1 9", check: "`Array.isArray(minMax([4,1,9,3]))` is true and its length is exactly 2." },
  { id: 7, level: 2, title: "The HTTP Status Code Enum", scenario: "An API client needs named constants for common HTTP status codes to avoid magic numbers scattered through the code.", objective: "Declare `enum HttpStatus { OK = 200, NotFound = 404, ServerError = 500 }`. Write a function `isError(code: HttpStatus): boolean` returning true when code >= 400.", constraints: "Must give each member its real HTTP numeric value explicitly. isError must accept the HttpStatus type, not a raw number.", expectedOutput: "`console.log(isError(HttpStatus.NotFound), isError(HttpStatus.OK))` prints: true false", check: "`HttpStatus.ServerError === 500`. `isError(HttpStatus.ServerError) === true`." },
  { id: 8, level: 2, title: "The Leaderboard Score Formatter", scenario: "A game leaderboard needs to format an array of player scores into a comma-separated, sorted-descending string.", objective: "Given `const scores: number[] = [88, 42, 95, 67]`, sort a COPY in descending order (without mutating the original) and join with \", \".", constraints: "Must not mutate the original scores array — copy it first (e.g. with spread) before sorting.", expectedOutput: "`console.log([...scores].sort((a, b) => b - a).join(\", \"))` prints: 95, 88, 67, 42", check: "After running, `scores` must still equal [88, 42, 95, 67] in its original order." },
  { id: 9, level: 2, title: "The Optional Middle Coordinate", scenario: "A 2D-or-3D point library needs a tuple type that works for both flat and spatial coordinates.", objective: "Declare `type Point = [x: number, y: number, z?: number]`. Create a 2D point `[1, 2]` and a 3D point `[1, 2, 3]`, both typed Point. Log both lengths.", constraints: "The z element must be optional using the ? syntax. Both point literals must type-check as Point.", expectedOutput: "`console.log(point2D.length, point3D.length)` prints: 2 3", check: "A Point value with 4 or more elements must be a type error." },
  { id: 10, level: 2, title: "The Frozen Configuration Tuple", scenario: "A build tool loads a [environment, port] configuration pair at startup that should never be reassigned in place.", objective: "Declare `const config: readonly [string, number] = [\"production\", 8080]`. Log both elements.", constraints: "Must use a readonly tuple type. Reading elements is fine; writing to an index must not be attempted.", expectedOutput: "`console.log(config[0], config[1])` prints: production 8080", check: "Attempting `config[0] = \"dev\"` must be a compile-time type error." },
  { id: 11, level: 3, title: "The Labeled Database Row", scenario: "A lightweight ORM represents a users table row as a tuple for performance, but wants labels for editor readability.", objective: "Declare `type UserRow = [id: number, email: string, isActive: boolean]`. Create a row `[1, \"a@b.com\", true]` and log a formatted summary string using all three positions.", constraints: "Must use labeled tuple elements (id:, email:, isActive:). Access elements positionally (row[0], row[1], row[2]).", expectedOutput: "`console.log(`User #${row[0]}: ${row[1]} (active: ${row[2]})`)` prints: User #1: a@b.com (active: true)", check: "`row.length === 3`. `typeof row[2] === \"boolean\"`." },
  { id: 12, level: 3, title: "The Variable-Length CSV Row", scenario: "A CSV parser always has a row number as the first column, followed by any number of string cell values.", objective: "Declare `type CsvRow = [rowNumber: number, ...cells: string[]]`. Create rows with 2 and 4 cells and log both lengths.", constraints: "Must use a rest element after the fixed rowNumber position. Do not use a plain number[] or string[] instead.", expectedOutput: "For [1, \"a\", \"b\"] and [2, \"x\", \"y\", \"z\", \"w\"]: `console.log(row1.length, row2.length)` prints: 3 5", check: "A CsvRow with zero elements (missing rowNumber) must be a type error." },
  { id: 13, level: 3, title: "The Frozen Menu Items", scenario: "A restaurant app hardcodes today's special menu items and wants the exact literal values preserved and locked at the type level.", objective: "Declare `const menu = [\"Soup\", \"Salad\", \"Steak\"] as const`. Log `menu[0]` and `menu.length`. Define `type MenuItem = typeof menu[number]` and declare a variable of that type set to \"Salad\".", constraints: "Must use `as const`. MenuItem must be derived via `typeof menu[number]`, not manually retyped.", expectedOutput: "`console.log(menu[0], menu.length)` prints: Soup 3", check: "Assigning `const item: MenuItem = \"Pizza\"` (not in the menu) must be a type error." },
  { id: 14, level: 3, title: "The Card Suit Reverse Lookup", scenario: "A card game needs to convert between a suit's numeric enum value and its display name for UI rendering.", objective: "Declare `enum Suit { Hearts, Diamonds, Clubs, Spades }`. Given a numeric value `2`, log the suit NAME using reverse mapping. Given `Suit.Clubs`, log its numeric value.", constraints: "Must use the enum's built-in reverse mapping (Suit[2]), not a manual switch statement.", expectedOutput: "`console.log(Suit[2], Suit.Clubs)` prints: Clubs 2", check: "`Suit[Suit.Hearts] === \"Hearts\"` must be true, demonstrating the round-trip mapping." },
  { id: 15, level: 3, title: "The File Permission Flags", scenario: "A file system utility models Unix-style permissions (read, write, execute) as combinable bit flags.", objective: "Declare `enum Permission { None = 0, Read = 1, Write = 2, Execute = 4 }`. Compute `ReadWrite` by combining Read and Write with bitwise OR, and check if a value has Read permission using bitwise AND.", constraints: "Must use powers of two for Read, Write, Execute. Use | to combine and & to test membership.", expectedOutput: "`const rw = Permission.Read | Permission.Write; console.log(rw, (rw & Permission.Read) !== 0)` prints: 3 true", check: "`(rw & Permission.Execute) === 0` must be true, confirming Execute is not part of rw." },
  { id: 16, level: 4, title: "The Generic Pair Factory", scenario: "A utility library needs a fully generic function that pairs up any two values into a strongly-typed tuple, used across many different call sites with different types.", objective: "Write `function pair<T, U>(a: T, b: U): [T, U] { return [a, b]; }`. Call it with (1, \"one\") and with (true, [1,2]), logging both results.", constraints: "Must use two independent generic type parameters T and U. The return type must be exactly [T, U].", expectedOutput: "`console.log(pair(1, \"one\")); console.log(pair(true, [1, 2]));` prints: [1,\"one\"] then [true,[1,2]]", check: "TypeScript must infer the tuple's element types automatically from the arguments without explicit type arguments." },
  { id: 17, level: 4, title: "The Batched API Request Log", scenario: "An API gateway logs each request as a [method, statusCode] pair, collecting many of them into a request log array.", objective: "Declare `const log: [string, number][] = []`. Push three entries: [\"GET\", 200], [\"POST\", 201], [\"GET\", 404]. Log how many entries have a status >= 400.", constraints: "Must use the array-of-tuples type [string, number][]. Use .filter() to count error entries.", expectedOutput: "`console.log(log.filter(([, status]) => status >= 400).length)` prints: 1", check: "`log.length === 3`. Each entry must destructure cleanly as [method, status]." },
  { id: 18, level: 4, title: "The Zero-Overhead Build Mode", scenario: "A performance-critical build script uses a small set of mode constants and wants zero runtime overhead from them.", objective: "Declare `const enum BuildMode { Development, Production, Test }`. Use `BuildMode.Production` in an if-check and log a message based on it.", constraints: "Must use `const enum`, not a regular enum. Do not attempt Object.values or reverse-mapping on it (which would fail to compile).", expectedOutput: "For mode = BuildMode.Production: `console.log(mode === BuildMode.Production ? \"prod build\" : \"other build\")` prints: prod build", check: "The compiled JavaScript output for BuildMode.Production must be inlined as the literal number 1, with no runtime enum object." },
  { id: 19, level: 4, title: "The Generic Tuple Concatenator", scenario: "A functional-style utilities library wants a `concat` function that joins two tuples of any shape while preserving each element's exact type at compile time.", objective: "Write `function concat<T extends unknown[], U extends unknown[]>(a: [...T], b: [...U]): [...T, ...U] { return [...a, ...b]; }`. Call concat([1, \"a\"], [true]) and log the result.", constraints: "Must use variadic tuple types with the rest/spread syntax in both parameters and the return type.", expectedOutput: "`console.log(concat([1, \"a\"], [true]))` prints: [1,\"a\",true]", check: "The inferred return type must be [number, string, boolean], not a generic array like unknown[]." },
  { id: 20, level: 4, title: "The Read-Only Sensor Buffer", scenario: "An IoT dashboard receives a large buffer of sensor readings that downstream analytics code must never mutate.", objective: "Write `function summarize(readings: ReadonlyArray<number>): { min: number; max: number; avg: number }` computing min, max, and average without mutating readings.", constraints: "The parameter must be typed ReadonlyArray<number>. Do not call push, sort, splice, or reverse on readings inside the function.", expectedOutput: "For readings = [10, 20, 30]: `console.log(summarize(readings))` prints: {min: 10, max: 30, avg: 20}", check: "Attempting `readings.push(40)` inside the function body must be a compile-time type error." },
  { id: 21, level: 5, title: "The Type-Level Tuple Length", scenario: "A type-utilities library wants a way to compute a tuple's length purely at the TYPE level, for use in other generic constraints.", objective: "Define `type Length<T extends readonly unknown[]> = T[\"length\"]`. Use it to type a constant `len: Length<[1, 2, 3]>` and assign it the value 3. Log len.", constraints: "Must use the tuple's built-in \"length\" property type, not a manually recursive conditional type.", expectedOutput: "`console.log(len)` prints: 3", check: "Assigning `const bad: Length<[1, 2, 3]> = 4;` must be a compile-time type error, since the literal length type is exactly 3." },
  { id: 22, level: 5, title: "The Tuple-to-Union Extractor", scenario: "A design-system library defines its allowed spacing values as a readonly tuple and needs a matching union type for prop validation without duplicating the list.", objective: "Declare `const spacings = [4, 8, 16, 32] as const`. Define `type Spacing = typeof spacings[number]`. Declare a function `applyMargin(value: Spacing): string` returning a CSS string.", constraints: "Spacing must be derived from spacings via `typeof spacings[number]`, not written out manually as a union.", expectedOutput: "`console.log(applyMargin(16))` prints: margin: 16px", check: "Calling `applyMargin(10)` (not one of the four literal values) must be a compile-time type error." },
  { id: 23, level: 5, title: "The Traffic Light State Machine", scenario: "A traffic light controller must strictly enforce the cycle Red -> Green -> Yellow -> Red using enum-based transitions, rejecting any invalid jump.", objective: "Declare `enum Light { Red, Green, Yellow }`. Write `function next(current: Light): Light` implementing the exact cycle above using a switch statement with exhaustiveness checking via a never-typed default.", constraints: "Must use a switch over the Light enum. The default case must assign to a never-typed variable to enforce exhaustiveness.", expectedOutput: "`console.log(next(Light.Red), next(Light.Green), next(Light.Yellow))` prints: 1 2 0", check: "Adding a new Light member without updating the switch must cause a compile-time error via the never-typed default branch." },
  { id: 24, level: 5, title: "The Combinable Access Control Enum", scenario: "A permissions system for a document editor needs combinable capabilities (View, Comment, Edit, Share) represented compactly as a single stored number per user, with a helper to check any capability.", objective: "Declare a bit-flag enum `enum Capability { View = 1, Comment = 2, Edit = 4, Share = 8 }`. Write `function can(userFlags: number, cap: Capability): boolean` using bitwise AND. Combine View | Comment | Edit for a user and check for Share.", constraints: "Capability values must be powers of two. can() must use the & operator, not equality checks.", expectedOutput: "For userFlags = Capability.View | Capability.Comment | Capability.Edit: `console.log(can(userFlags, Capability.Edit), can(userFlags, Capability.Share))` prints: true false", check: "`can(userFlags, Capability.View)` must be true; `can(userFlags, Capability.Share)` must be false." },
  { id: 25, level: 5, title: "The Type-Safe Zip Utility", scenario: "A functional utilities package needs a generic `zip` function that pairs elements from two arrays of potentially different types into an array of tuples, fully type-checked.", objective: "Write `function zip<T, U>(a: T[], b: U[]): [T, U][] { return a.map((val, i) => [val, b[i]]); }`. Call zip([1, 2, 3], [\"a\", \"b\", \"c\"]) and log the result.", constraints: "The return type must be [T, U][] (an array of tuples), inferred generically from the two input arrays.", expectedOutput: "`console.log(zip([1, 2, 3], [\"a\", \"b\", \"c\"]))` prints: [[1,\"a\"],[2,\"b\"],[3,\"c\"]]", check: "The result's element type must be inferred as [number, string], and `zip([1,2,3], [\"a\",\"b\",\"c\"])[0][1]` must type as string." },
],
uniontypes: [
  { id: 1, level: 1, title: "The Flexible Product ID", scenario: "An e-commerce system has legacy products with numeric IDs and new products with string SKU-based IDs.", objective: "Write `function printId(id: string | number): void` that logs the id prefixed with \"ID: \".", constraints: "The parameter must be typed string | number. Do not use any or two overloaded functions.", expectedOutput: "`printId(42); printId(\"SKU-9\");` prints: ID: 42 then ID: SKU-9", check: "Calling `printId(true)` (a boolean) must be a compile-time type error." },
  { id: 2, level: 1, title: "The Theme Setting Field", scenario: "A settings panel lets users choose a UI theme from exactly three fixed options.", objective: "Declare `type Theme = \"light\" | \"dark\" | \"system\"`. Declare `let currentTheme: Theme = \"system\"`. Reassign it to \"dark\" and log it.", constraints: "Theme must be a union of exactly those three string literals. Do not use a plain string type.", expectedOutput: "`console.log(currentTheme)` prints: dark", check: "Assigning `currentTheme = \"blue\"` must be a compile-time type error." },
  { id: 3, level: 1, title: "The Combined User Profile", scenario: "A user profile page needs an object that has all the fields from both a basic `Person` shape and a `ContactInfo` shape.", objective: "Declare `interface Person { name: string; age: number }` and `interface ContactInfo { email: string }`. Declare `type FullProfile = Person & ContactInfo`. Create a value and log it.", constraints: "FullProfile must be an intersection (&) of Person and ContactInfo, requiring all three fields.", expectedOutput: "For { name: \"Ana\", age: 30, email: \"ana@x.com\" }: `console.log(profile.name, profile.email)` prints: Ana ana@x.com", check: "Omitting the email field from the object literal must be a compile-time type error." },
  { id: 4, level: 1, title: "The Nullable Search Result", scenario: "A search function may find a matching record or find nothing at all.", objective: "Write `function findUser(id: number): string | null` returning \"Alice\" for id 1 and null otherwise. Log the result of calling it with 1 and with 2.", constraints: "The return type must explicitly include null in the union.", expectedOutput: "`console.log(findUser(1), findUser(2))` prints: Alice null", check: "The function body must have a code path that returns null and one that returns a string." },
  { id: 5, level: 1, title: "The Combined Vehicle Spec", scenario: "A vehicle catalog needs a spec object that always has both engine details and pricing details together.", objective: "Declare `interface Engine { horsepower: number }` and `interface Pricing { price: number }`. Declare `type VehicleSpec = Engine & Pricing`. Create one and log the sum of both fields.", constraints: "VehicleSpec must be an intersection requiring both horsepower and price.", expectedOutput: "For { horsepower: 300, price: 45000 }: `console.log(spec.horsepower + spec.price)` prints: 45300", check: "A VehicleSpec object literal missing either field must be a compile-time type error." },
  { id: 6, level: 2, title: "The Discriminated Shape Area Calculator", scenario: "A drawing app computes the area of shapes that are either circles or rectangles, each with different required fields.", objective: "Declare `type Shape = { kind: \"circle\"; radius: number } | { kind: \"rectangle\"; width: number; height: number }`. Write `function area(s: Shape): number` using the kind discriminant to compute correctly.", constraints: "Must narrow on the \"kind\" field with an if or switch before accessing radius/width/height.", expectedOutput: "For { kind: \"rectangle\", width: 4, height: 5 }: `console.log(area(shape))` prints: 20", check: "Accessing radius without narrowing to the circle branch first must be a compile-time type error." },
  { id: 7, level: 2, title: "The Async Result Wrapper", scenario: "An API layer wraps every response in a Result type so callers must explicitly handle both success and failure.", objective: "Declare `type Result<T> = { ok: true; data: T } | { ok: false; error: string }`. Write `function unwrap<T>(r: Result<T>): T` that returns data or throws new Error(r.error).", constraints: "Must narrow on r.ok before accessing data or error. Must throw (not return) for the failure case.", expectedOutput: "For { ok: true, data: 42 }: `console.log(unwrap(result))` prints: 42", check: "Calling unwrap on { ok: false, error: \"boom\" } must throw an Error with message \"boom\"." },
  { id: 8, level: 2, title: "The Merged Component Props", scenario: "A UI component library builds a button component whose props must include both layout props and interaction props together.", objective: "Declare `interface LayoutProps { width: number; height: number }` and `interface InteractionProps { onClick: () => void }`. Declare `type ButtonProps = LayoutProps & InteractionProps`. Create a value and invoke onClick.", constraints: "ButtonProps must require all three fields via intersection. onClick must be called and its side effect (a logged message) observed.", expectedOutput: "Calling props.onClick() where onClick logs \"clicked\" prints: clicked", check: "A ButtonProps object literal missing onClick must be a compile-time type error." },
  { id: 9, level: 2, title: "The Flexible Logger Input", scenario: "A logging utility should accept either a single string message or an array of string messages, printing each on its own line.", objective: "Write `function log(input: string | string[]): void` that normalizes input into an array (wrapping a single string) and logs each entry.", constraints: "Must use a union parameter type and Array.isArray (or typeof) to normalize before iterating.", expectedOutput: "For log(\"hi\"): prints hi. For log([\"a\", \"b\"]): prints a then b.", check: "Calling log(42) (a number) must be a compile-time type error." },
  { id: 10, level: 2, title: "The Priority Level Union", scenario: "A task manager assigns each task a priority that must be exactly \"low\", \"medium\", or \"high\", used to sort a task list.", objective: "Declare `type Priority = \"low\" | \"medium\" | \"high\"`. Write `function weight(p: Priority): number` mapping low=1, medium=2, high=3. Sort an array of tasks by weight(task.priority) descending.", constraints: "Priority must be the exact three-literal union. weight must handle all three cases exhaustively.", expectedOutput: "For tasks with priorities [\"low\",\"high\",\"medium\"], sorted descending logs: high medium low", check: "Calling weight(\"urgent\") (not a valid Priority) must be a compile-time type error." },
  { id: 11, level: 3, title: "The Branded User ID", scenario: "A codebase mixes up plain numeric IDs for users and orders in function calls, causing bugs. You want a nominal-style ID that a plain number cannot be mistaken for.", objective: "Declare `type UserId = number & { readonly __brand: \"UserId\" }`. Write `function createUserId(n: number): UserId` using a type assertion, and `function greetUser(id: UserId): void` logging it.", constraints: "UserId must be an intersection of number with a unique brand tag. createUserId must be the only way to produce a UserId.", expectedOutput: "For createUserId(7): `greetUser(createUserId(7))` prints: Welcome, user 7", check: "Calling greetUser(7) directly with a plain number (not passed through createUserId) must be a compile-time type error." },
  { id: 12, level: 3, title: "The Exhaustive Action Reducer", scenario: "A state management reducer handles a growing set of action types and must be updated safely whenever a new action is added.", objective: "Declare `type Action = { type: \"increment\" } | { type: \"decrement\" } | { type: \"reset\" }`. Write `function reduce(state: number, action: Action): number` with a switch statement and a never-typed default case for exhaustiveness.", constraints: "The switch default branch must assign the action to a variable typed never to enforce exhaustiveness at compile time.", expectedOutput: "For reduce(5, { type: \"decrement\" }): `console.log(reduce(5, { type: \"decrement\" }))` prints: 4", check: "Adding a new Action variant without a matching case must cause a compile-time error via the never-typed default." },
  { id: 13, level: 3, title: "The Overlapping Field Conflict Fix", scenario: "Two interfaces both declare a `status` field with different literal types, and intersecting them naively makes the type unusable. You need to redesign it as a union instead.", objective: "Given `interface Draft { status: \"draft\"; content: string }` and `interface Published { status: \"published\"; publishedAt: string }`, declare `type Post = Draft | Published` (not an intersection) and write a function that safely logs based on status.", constraints: "Must use a union, not an intersection, since status cannot be both literals at once. Must narrow on status before accessing publishedAt or content.", expectedOutput: "For { status: \"published\", publishedAt: \"2026-01-01\" }: prints: Published at 2026-01-01", check: "Accessing publishedAt without first narrowing status to \"published\" must be a compile-time type error." },
  { id: 14, level: 3, title: "The Config With Shared Base", scenario: "Three plugin configuration shapes (Http, Worker, Cron) all need a common `enabled` flag plus their own unique fields.", objective: "Declare a `BaseConfig { enabled: boolean }` interface, three specific config interfaces, and `type PluginConfig = BaseConfig & (HttpConfig | WorkerConfig | CronConfig)`. Create one and log its enabled flag plus its unique field.", constraints: "Must intersect the shared base with a union of the specific variants, not duplicate enabled in each variant.", expectedOutput: "For an HttpConfig with enabled: true, port: 8080: prints: enabled=true port=8080", check: "A PluginConfig object literal missing the enabled field must be a compile-time type error regardless of which variant is used." },
  { id: 15, level: 3, title: "The Type-Safe Event Map", scenario: "A typed event emitter needs each event name to map to its own specific payload shape, so subscribers get correctly-typed data.", objective: "Declare `type EventMap = { click: { x: number; y: number }; keydown: { key: string } }`. Write `function emit<K extends keyof EventMap>(event: K, payload: EventMap[K]): void` that logs the event name and payload.", constraints: "The payload parameter's type must be derived from EventMap[K], not a generic union of all payload shapes.", expectedOutput: "For emit(\"keydown\", { key: \"Enter\" }): prints: keydown {\"key\":\"Enter\"}", check: "Calling emit(\"click\", { key: \"Enter\" }) (wrong payload for click) must be a compile-time type error." },
  { id: 16, level: 4, title: "The Exclude-Based Status Filter", scenario: "An order status union includes a \"cancelled\" state that a particular UI screen should never need to handle, and you want a derived type excluding it.", objective: "Declare `type OrderStatus = \"pending\" | \"shipped\" | \"delivered\" | \"cancelled\"`. Declare `type ActiveStatus = Exclude<OrderStatus, \"cancelled\">`. Write a function accepting only ActiveStatus and log a message.", constraints: "ActiveStatus must be derived using the Exclude utility type, not manually retyped.", expectedOutput: "For describe(\"shipped\" as ActiveStatus): prints: Order is shipped", check: "Assigning \"cancelled\" to a variable typed ActiveStatus must be a compile-time type error." },
  { id: 17, level: 4, title: "The Union-to-Intersection Merge Utility", scenario: "A plugin system collects an array of small config objects and needs a single merged type representing all of their combined fields at once.", objective: "Using `type UnionToIntersection<U> = (U extends any ? (k: U) => void : never) extends (k: infer I) => void ? I : never`, apply it to `{ a: number } | { b: string }` and create a value of the resulting type.", constraints: "Must use the UnionToIntersection utility type as given. The resulting value must have both a and b.", expectedOutput: "For { a: 1, b: \"x\" }: `console.log(merged.a, merged.b)` prints: 1 x", check: "Omitting either a or b from the merged object literal must be a compile-time type error." },
  { id: 18, level: 4, title: "The Distributive Non-Null Cleaner", scenario: "A form library needs a generic type that strips null and undefined from any given type, including from unions, for internal use in validated field types.", objective: "Declare `type CleanUp<T> = T extends null | undefined ? never : T`. Apply it to `string | number | null | undefined` and declare a variable of the resulting type set to a string.", constraints: "CleanUp must be written as a distributive conditional type using a naked type parameter T.", expectedOutput: "For const clean: CleanUp<string | number | null | undefined> = \"hi\": `console.log(clean)` prints: hi", check: "Assigning null or undefined to a CleanUp<...>-typed variable must be a compile-time type error." },
  { id: 19, level: 4, title: "The Key-Filtered String Properties", scenario: "A serialization helper needs a type containing only the string-valued properties of an arbitrary object type, for a CSV-safe export feature.", objective: "Declare `type OnlyStrings<T> = { [K in keyof T as T[K] extends string ? K : never]: T[K] }`. Apply it to `{ name: string; age: number; email: string }` and log the keys of a value typed that way.", constraints: "Must use key remapping with \"as\" inside a mapped type, filtering non-string properties via never.", expectedOutput: "For { name: \"Kim\", email: \"k@x.com\" } typed as OnlyStrings<...>: `console.log(Object.keys(value))` prints: [\"name\",\"email\"]", check: "Including an \"age\" field in the OnlyStrings-typed object literal must be a compile-time type error since it was filtered out." },
  { id: 20, level: 4, title: "The Extract-Based Payload Narrower", scenario: "A discriminated union of five WebSocket message types needs a way to extract just the type of a single specific variant's payload for use elsewhere in the code.", objective: "Declare a Message union with at least three variants (e.g. chat, join, leave, each with a type field). Declare `type ChatPayload = Extract<Message, { type: \"chat\" }>`. Write a function accepting only ChatPayload.", constraints: "ChatPayload must be derived with Extract<Message, { type: \"chat\" }>, not written manually as a duplicate interface.", expectedOutput: "For a chat message { type: \"chat\", text: \"hi\" }: prints: Chat: hi", check: "Passing a \"join\" variant message to the function expecting ChatPayload must be a compile-time type error." },
  { id: 21, level: 5, title: "The Recursive Union Flattener", scenario: "A CMS content tree can nest arrays of blocks within blocks arbitrarily, and you need a type utility that flattens the nested array-or-single-value union into a plain element union.", objective: "Declare `type Flatten<T> = T extends readonly (infer U)[] ? U : T`. Apply it to `readonly (string | number)[]` and declare a variable of the resulting type.", constraints: "Must use infer inside a conditional type to extract the array element type.", expectedOutput: "For const val: Flatten<readonly (string | number)[]> = \"x\": `console.log(val)` prints: x", check: "Assigning a boolean to the Flatten-derived type must be a compile-time type error, since only string | number are valid." },
  { id: 22, level: 5, title: "The Type-Level Function Return Extractor", scenario: "A plugin registry stores a union of differently-shaped handler functions and needs a type representing all their possible return values combined.", objective: "Declare `type ExtractReturn<T> = T extends (...args: any[]) => infer R ? R : never`. Apply it to a union of `(() => string) | (() => number)` and declare a variable of the resulting type.", constraints: "Must rely on distribution over the function-type union to produce string | number as the result.", expectedOutput: "For const result: ExtractReturn<(() => string) | (() => number)> = 5: `console.log(result)` prints: 5", check: "Assigning a boolean to the ExtractReturn-derived type must be a compile-time type error." },
  { id: 23, level: 5, title: "The Generic Discriminated Dispatcher", scenario: "A command-processing system wants a fully generic dispatch table so each command type's handler receives only its own precisely-narrowed variant of a large Command union.", objective: "Declare a Command union with at least 3 variants sharing a \"type\" field. Declare `type Handlers = { [K in Command[\"type\"]]: (cmd: Extract<Command, { type: K }>) => void }`. Implement a dispatch function using it.", constraints: "Handlers must be built with a mapped type keyed by Command[\"type\"], using Extract to compute each handler's precise parameter type.", expectedOutput: "For a command { type: \"ping\" } dispatched through handlers.ping: prints whatever the ping handler logs, e.g. pong", check: "A handlers object missing an entry for one of the Command variants must be a compile-time type error." },
  { id: 24, level: 5, title: "The IsUnion Type Detector", scenario: "A type-utilities library needs a way to detect, purely at the type level, whether a given type parameter is actually a union of more than one member versus a single type.", objective: "Declare `type IsUnion<T, U = T> = T extends U ? ([U] extends [T] ? false : true) : never`. Apply it to `\"a\" | \"b\"` and to `\"a\"` alone, declaring two variables of the resulting types.", constraints: "Must use the distributive-vs-non-distributive trick (tuple wrapping) exactly as shown to detect unions correctly.", expectedOutput: "For const isUnionTrue: IsUnion<\"a\" | \"b\"> = true and const isUnionFalse: IsUnion<\"a\"> = false: both compile and can be logged as true/false", check: "Assigning false to IsUnion<\"a\" | \"b\"> (which should be true) must be a compile-time type error." },
  { id: 25, level: 5, title: "The PickByType Value Filter", scenario: "A form-serialization utility needs a generic type that selects only the properties of an object type whose VALUE type matches a given constraint, for building numeric-only or string-only sub-forms.", objective: "Declare `type PickByType<T, V> = { [K in keyof T as T[K] extends V ? K : never]: T[K] }`. Apply it to `{ id: number; name: string; age: number }` with V = number, producing a type with only id and age.", constraints: "Must combine a mapped type, key remapping with \"as\", and a conditional type checking each property's value against V.", expectedOutput: "For a value { id: 1, age: 30 } typed as PickByType<..., number>: `console.log(Object.keys(value))` prints: [\"id\",\"age\"]", check: "Including \"name\" (a string field) in the PickByType<..., number>-typed object literal must be a compile-time type error." },
],
narrowing: [
  { id: 1, level: 1, title: "The String-or-Number Formatter", scenario: "A UI label component receives a value that could be a raw string or a number and must format each differently.", objective: "Write `function format(x: string | number): string` that returns `x.toUpperCase()` if it is a string, or `x.toFixed(2)` if it is a number.", constraints: "Must use a typeof check to narrow x before calling either method. Do not use `as` type assertions.", expectedOutput: "`console.log(format(\"hi\"), format(3.1))` prints: HI 3.10", check: "Calling format on a boolean must be a compile-time type error since it is outside the declared union." },
  { id: 2, level: 1, title: "The Optional Greeting", scenario: "A welcome banner greets a user by name if one is provided, otherwise shows a generic greeting.", objective: "Write `function greet(name: string | undefined): string` that returns `Hello, ${name}!` if name is truthy, otherwise \"Hello, stranger!\".", constraints: "Must use a truthiness check (if (name)) to narrow before using name in the template literal.", expectedOutput: "`console.log(greet(\"Sam\"), greet(undefined))` prints: Hello, Sam! then Hello, stranger!", check: "Accessing name inside the true branch must be narrowed to string, not string | undefined." },
  { id: 3, level: 1, title: "The Safe Error Logger", scenario: "A try/catch block catches an unknown error value and needs to safely extract a message before logging.", objective: "Write `function logError(e: unknown): void` that logs `e.message` only if `e instanceof Error`, otherwise logs \"Unknown error\".", constraints: "The catch parameter type is unknown. Must use instanceof Error to narrow before accessing .message.", expectedOutput: "For logError(new Error(\"boom\")): prints boom. For logError(\"oops\"): prints Unknown error.", check: "Accessing e.message without the instanceof check must be a compile-time type error." },
  { id: 4, level: 1, title: "The Nullable Array Length", scenario: "A component receives a list that might not have loaded yet, represented as null, and needs to safely report its size.", objective: "Write `function count(items: number[] | null): number` returning 0 if items is null, otherwise items.length.", constraints: "Must check for null explicitly before accessing .length.", expectedOutput: "`console.log(count(null), count([1, 2, 3]))` prints: 0 3", check: "Accessing items.length before the null check must be a compile-time type error." },
  { id: 5, level: 1, title: "The Type-Checked Sum", scenario: "A calculator utility receives two values that are supposed to be numbers but may arrive as strings from a form and need validation before adding.", objective: "Write `function add(a: unknown, b: unknown): number` that returns a + b only if both are numbers, otherwise returns 0.", constraints: "Must use typeof checks on both a and b combined with && before performing the addition.", expectedOutput: "`console.log(add(2, 3), add(\"2\", 3))` prints: 5 0", check: "Performing a + b without both typeof checks passing must be a compile-time type error." },
  { id: 6, level: 2, title: "The Discriminated Response Handler", scenario: "An API client returns a Result type that is either a success with data or a failure with an error message, and calling code must handle both.", objective: "Declare `type Result = { ok: true; data: string } | { ok: false; error: string }`. Write `function handle(r: Result): string` returning data if ok, or `Error: ${error}` otherwise.", constraints: "Must narrow on r.ok before accessing data or error.", expectedOutput: "For { ok: false, error: \"timeout\" }: `console.log(handle(r))` prints: Error: timeout", check: "Accessing r.data without narrowing r.ok to true first must be a compile-time type error." },
  { id: 7, level: 2, title: "The Custom isString Guard", scenario: "A validation library wants a reusable, properly-narrowing guard function to check for strings across many call sites.", objective: "Write `function isString(x: unknown): x is string { return typeof x === \"string\"; }`. Use it in `function shout(x: unknown): string` that calls x.toUpperCase() only when isString(x) is true, otherwise returns \"N/A\".", constraints: "isString must use the `x is string` type predicate syntax, not a plain boolean return type.", expectedOutput: "`console.log(shout(\"hi\"), shout(5))` prints: HI N/A", check: "Removing the `is string` predicate from isString's signature must cause shout's call to x.toUpperCase() to become a compile-time type error." },
  { id: 8, level: 2, title: "The Array-or-Single Normalizer", scenario: "A configuration loader accepts either a single plugin name or an array of plugin names and must always process a normalized array.", objective: "Write `function normalize(input: string | string[]): string[]` that wraps a single string into a one-element array using Array.isArray to narrow.", constraints: "Must use Array.isArray(input) as the narrowing check, not typeof.", expectedOutput: "`console.log(normalize(\"a\"), normalize([\"b\", \"c\"]))` prints: [\"a\"] then [\"b\",\"c\"]", check: "Calling .join on input before the Array.isArray check must be a compile-time type error." },
  { id: 9, level: 2, title: "The Exhaustive Shape Area", scenario: "A geometry module computes areas for three shape kinds and must be safeguarded against future shape additions being forgotten.", objective: "Declare a Shape union of circle, square, and triangle (each with a kind field and relevant dimensions). Write `function area(s: Shape): number` using a switch with a never-typed default for exhaustiveness.", constraints: "The switch default case must assign the unhandled value to a never-typed variable.", expectedOutput: "For a square with side 4: `console.log(area(shape))` prints: 16", check: "Adding a new Shape variant without a matching case must cause a compile-time error via the never-typed default." },
  { id: 10, level: 2, title: "The In-Operator Vehicle Router", scenario: "A fleet management dashboard renders different controls for vehicles depending on whether they have wheels or wings, without a shared discriminant field being available.", objective: "Declare `type Vehicle = { wheels: number } | { wings: number }`. Write `function describe(v: Vehicle): string` using the `in` operator to check for \"wheels\" and branch accordingly.", constraints: "Must use `\"wheels\" in v` for narrowing, since there is no shared discriminant literal field.", expectedOutput: "For { wings: 2 }: `console.log(describe(v))` prints: Flies with 2 wings", check: "Accessing v.wheels in the branch where \"wheels\" in v is false must be a compile-time type error." },
  { id: 11, level: 3, title: "The Assertion-Based Config Validator", scenario: "A startup routine loads a configuration object that must be verified to have a required apiKey field before the rest of the app proceeds, without wrapping every subsequent line in an if block.", objective: "Write `function assertHasApiKey(cfg: unknown): asserts cfg is { apiKey: string }` that throws if cfg is not an object with a string apiKey. Use it before accessing cfg.apiKey.", constraints: "Must use the `asserts cfg is Type` syntax, not a boolean-returning type guard.", expectedOutput: "For cfg = { apiKey: \"xyz\" }: `assertHasApiKey(cfg); console.log(cfg.apiKey);` prints: xyz", check: "Calling assertHasApiKey with { apiKey: 123 } (wrong type) must throw at runtime." },
  { id: 12, level: 3, title: "The Extract-Narrowed Message Handler", scenario: "A chat application receives WebSocket messages of several types and needs a type guard that narrows to a specific variant using Extract for precision.", objective: "Declare a Message union with \"text\", \"image\", and \"system\" variants (each with a type field and unique data). Write `function isTextMessage(m: Message): m is Extract<Message, { type: \"text\" }>` and use it to safely log text content.", constraints: "The predicate's target type must use Extract<Message, { type: \"text\" }>, not a hand-written duplicate interface.", expectedOutput: "For { type: \"text\", body: \"hello\" }: prints: Text: hello", check: "Calling the function on an \"image\" variant message must return false, and accessing .body outside the narrowed branch must be a compile-time type error." },
  { id: 13, level: 3, title: "The Filter-Compacted List", scenario: "A search results array may contain null entries for failed lookups, and downstream code needs a fully non-null array.", objective: "Given `const results: (string | null)[] = [\"a\", null, \"b\", null, \"c\"]`, write a type guard `isNotNull` and use `results.filter(isNotNull)` to produce a `string[]`.", constraints: "isNotNull must be typed as `(x: string | null): x is string => x !== null`, used directly as the filter predicate.", expectedOutput: "`console.log(results.filter(isNotNull))` prints: [\"a\",\"b\",\"c\"]", check: "The filtered result's inferred type must be string[], not (string | null)[]." },
  { id: 14, level: 3, title: "The Switch-on-Discriminant Reducer", scenario: "A shopping cart reducer processes actions to add items, remove items, and clear the cart, needing precise per-action payload access.", objective: "Declare a CartAction union with \"add\" (item, qty), \"remove\" (itemId), and \"clear\" (no payload) variants. Write `function reduce(cart: CartItem[], action: CartAction): CartItem[]` using a switch on action.type.", constraints: "Must switch directly on action.type, not on a destructured copy, to preserve narrowing for each case's unique fields.", expectedOutput: "For an empty cart and action { type: \"add\", item: \"Pen\", qty: 2 }: the resulting cart contains one entry for Pen with qty 2", check: "Accessing action.item inside the \"remove\" case must be a compile-time type error." },
  { id: 15, level: 3, title: "The Robust Plain-Object Guard", scenario: "A deep-clone utility needs to distinguish genuine plain objects from arrays and null, both of which also report typeof \"object\".", objective: "Write `function isPlainObject(x: unknown): x is Record<string, unknown>` checking typeof x === \"object\", x !== null, and !Array.isArray(x) together.", constraints: "Must combine all three checks with && in the correct order (typeof, then null, then Array.isArray).", expectedOutput: "`console.log(isPlainObject({}), isPlainObject([]), isPlainObject(null))` prints: true false false", check: "Removing the `x !== null` check must cause isPlainObject(null) to incorrectly return true." },
  { id: 16, level: 4, title: "The Generic Defined-Value Filter", scenario: "A data pipeline processes arrays of optional values from multiple sources and needs a fully generic, reusable filter to drop undefined entries with correct typing.", objective: "Write `function isDefined<T>(x: T | undefined): x is T { return x !== undefined; }`. Apply it via `.filter(isDefined)` to `const vals: (number | undefined)[] = [1, undefined, 2, undefined, 3]`.", constraints: "isDefined must be fully generic over T, usable with any element type, not hardcoded to number.", expectedOutput: "`console.log(vals.filter(isDefined))` prints: [1,2,3]", check: "The filtered array's inferred type must be number[], not (number | undefined)[]." },
  { id: 17, level: 4, title: "The Never-Based Exhaustive Dispatcher", scenario: "A five-variant notification union (email, sms, push, inApp, webhook) needs a fully exhaustive send function that the compiler will flag if a sixth variant is ever added without a handler.", objective: "Declare a Notification union with 5 variants, each with a type field and its own data. Write `function send(n: Notification): void` with a switch covering all 5, plus an `assertNever` helper for the default case.", constraints: "Must implement a reusable `function assertNever(x: never): never { throw new Error(...) }` and call it in the default branch.", expectedOutput: "For an \"sms\" variant { type: \"sms\", phone: \"555-1234\" }: prints a message confirming an SMS was sent to 555-1234", check: "Adding a sixth Notification variant without a matching case must cause a compile-time error inside assertNever's call." },
  { id: 18, level: 4, title: "The Type Predicate Partition Utility", scenario: "A validation pipeline needs a generic `partition` function that splits an array into two properly-typed arrays (matching and non-matching) based on a type-guard predicate.", objective: "Write `function partition<T, S extends T>(arr: T[], pred: (x: T) => x is S): [S[], Exclude<T, S>[]]` implementing the split logic with two accumulator arrays.", constraints: "Must use a generic S extends T type parameter and the Exclude utility type in the return type.", expectedOutput: "For partition([1, \"a\", 2, \"b\"], (x): x is number => typeof x === \"number\"): the first array is [1,2] and the second is [\"a\",\"b\"]", check: "The first returned array's inferred element type must be number, and the second must be string, not the original union." },
  { id: 19, level: 4, title: "The Assertion-Chained Form Validator", scenario: "A multi-step form validator wants to run several assertion functions in sequence, each narrowing the data further, culminating in a fully-typed, guaranteed-valid submission object.", objective: "Write two assertion functions: `assertHasEmail(x: unknown): asserts x is { email: string }` and `assertHasAge(x: { email: string }): asserts x is { email: string; age: number }`. Chain them on an unknown input and log the final typed object.", constraints: "Each assertion function must use the `asserts x is Type` syntax and build on the previously narrowed type.", expectedOutput: "For input { email: \"a@b.com\", age: 25 }: after both assertions run, `console.log(input.email, input.age)` prints: a@b.com 25", check: "Calling assertHasAge on a value not yet narrowed by assertHasEmail (missing the email constraint) must be a compile-time type error." },
  { id: 20, level: 4, title: "The Keyof-Based Safe Property Reader", scenario: "A generic config reader needs to safely check whether a runtime string key actually exists on a given config object before indexing into it, preserving full type safety.", objective: "Write `function isKeyOf<T extends object>(obj: T, key: PropertyKey): key is keyof T { return key in obj; }`. Use it to safely read a dynamic key from a config object typed `{ debug: boolean; level: number }`.", constraints: "Must use the `key is keyof T` predicate syntax with a generic T extends object constraint.", expectedOutput: "For config = { debug: true, level: 3 } and key = \"level\": `console.log(isKeyOf(config, key) ? config[key] : undefined)` prints: 3", check: "Indexing config[key] without first calling isKeyOf to narrow key must be a compile-time type error." },
  { id: 21, level: 5, title: "The Type-Safe State Machine Transition", scenario: "A traffic light or order-processing state machine needs compile-time enforcement that transitions only occur between explicitly allowed states, using a discriminated union of states each listing its own valid next states.", objective: "Declare a State union of at least 3 states (e.g. \"idle\", \"running\", \"done\"), each with a literal `allowedNext` mapped type or lookup describing valid transitions. Write `function transition(current: State[\"type\"], next: State[\"type\"]): boolean` validating against the lookup.", constraints: "Must use a mapped/lookup type (e.g. a Record keyed by state type) built from the State union to determine allowed transitions, not a giant if/else chain.", expectedOutput: "For transition(\"idle\", \"running\"): prints true. For transition(\"done\", \"running\"): prints false (assuming done has no valid next states).", check: "The lookup type must be derived from the State union's literal type values, so adding a new state without updating the lookup causes a compile-time error." },
  { id: 22, level: 5, title: "The Recursive JSON Value Narrower", scenario: "A JSON-processing utility receives deeply nested unknown data and needs a recursive type guard that safely narrows it to a proper JsonValue type at any depth.", objective: "Declare `type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue }`. Write `function isJsonValue(x: unknown): x is JsonValue` that recursively validates arrays and objects.", constraints: "The function must recurse into array elements and object property values, checking each with itself.", expectedOutput: "For isJsonValue({ a: [1, \"b\", { c: true }] }): prints true. For isJsonValue({ a: () => {} }): prints false.", check: "A function value nested anywhere inside the input must cause isJsonValue to return false, even if surrounding structure is valid JSON." },
  { id: 23, level: 5, title: "The Contravariant Handler Merge", scenario: "A generic event system wants to combine several specific event handler function types into a single object using the union-to-intersection type trick, so a dispatcher can call the correct one per event with full type safety.", objective: "Given a union of function types `((e: { type: \"a\" }) => void) | ((e: { type: \"b\" }) => void)`, apply a `UnionToIntersection<U>` type (provided by you) to obtain a type combining both handler signatures, and implement an object satisfying it.", constraints: "Must implement UnionToIntersection using the contravariant function-parameter inference trick, and produce a real object with overloaded-like behavior.", expectedOutput: "Calling the combined handler with { type: \"a\" } and { type: \"b\" } both execute without a type error and can each log their event type", check: "The merged type must require handling logic for both \"a\" and \"b\" shaped inputs, not just one." },
  { id: 24, level: 5, title: "The Generic Exhaustive Command Bus", scenario: "A large command-processing system wants a fully generic dispatch mechanism so every command type's registered handler receives ONLY its own precisely-narrowed payload, and the compiler enforces that every command type has a registered handler.", objective: "Declare a Command union with at least 4 variants sharing a \"type\" field. Declare `type Handlers = { [K in Command[\"type\"]]: (cmd: Extract<Command, { type: K }>) => void }`. Implement `function dispatch(handlers: Handlers, cmd: Command): void` that looks up and calls the right handler.", constraints: "Handlers must be built with a mapped type using Extract as shown; dispatch must not use `any` except where unavoidable for the internal lookup call.", expectedOutput: "For a command { type: \"delete\", id: 5 } dispatched with a handlers.delete that logs \"Deleting 5\": prints Deleting 5", check: "A handlers object literal missing an entry for any one of the Command variants must be a compile-time type error." },
  { id: 25, level: 5, title: "The Runtime-Validated Trust Boundary", scenario: "An API client receives JSON responses from an external service and, despite having TypeScript interfaces describing the expected shape, needs genuine runtime validation before trusting the data as narrowed, since TypeScript types are erased at runtime.", objective: "Declare an interface `ApiUser { id: number; name: string; email: string }`. Write `function isApiUser(x: unknown): x is ApiUser` performing a full structural runtime check (typeof for each field, not just presence). Use it to safely process a raw unknown response, rejecting malformed ones.", constraints: "Must check every field's actual runtime type (not just key presence) before returning true. Must NOT use an unchecked `as ApiUser` assertion anywhere.", expectedOutput: "For a valid raw object with correct field types: isApiUser returns true and the function safely logs the user's name. For one with id as a string: isApiUser returns false and a rejection message is logged instead.", check: "A raw object with a numeric id represented as the string \"5\" must be rejected by isApiUser (return false), proving the guard checks actual types, not just key existence." },
],
classes: [
  { id: 1, level: 1, title: "The Employee Record Card", scenario: "You are building an HR tool that needs a simple record for each employee, created from their name and department.", objective: "Create a class `Employee` with a constructor accepting `name: string` and `department: string`, storing both as public fields. Instantiate one and log its fields.", constraints: "Use a regular constructor body (not parameter properties yet). Both fields must be public.", expectedOutput: "`console.log(emp.name, emp.department)` prints: Priya Engineering", check: "Verify `emp instanceof Employee` is true, and `typeof emp.name === \"string\"`." },
  { id: 2, level: 1, title: "The Shortcut Constructor", scenario: "A teammate points out your Product class constructor is full of repetitive `this.x = x` lines and asks you to shorten it.", objective: "Rewrite `class Product { constructor(public id: number, public title: string, public price: number) {} }` using constructor parameter properties only — no manual field declarations or assignments.", constraints: "Do not declare id, title, or price as separate class fields above the constructor. All three must be public parameter properties.", expectedOutput: "`console.log(new Product(1, \"Mug\", 9.99).price)` prints: 9.99", check: "Confirm the class body contains no `this.id = id;`-style lines, only the constructor parameter list." },
  { id: 3, level: 1, title: "The Read-Only Invoice Number", scenario: "An invoicing system assigns each Invoice a number at creation time that must never change afterward.", objective: "Create `class Invoice` with a `readonly invoiceNumber: string` set via the constructor, plus a mutable `amount: number` field. Attempt to reassign invoiceNumber afterward inside a comment showing it would fail to compile.", constraints: "invoiceNumber must use the readonly modifier. amount must remain reassignable.", expectedOutput: "`console.log(inv.invoiceNumber, inv.amount)` prints: INV-001 250", check: "Verify that `inv.invoiceNumber = \"INV-002\"` would be a TypeScript compile error (readonly), while `inv.amount = 300` succeeds." },
  { id: 4, level: 1, title: "The Hidden Account Balance", scenario: "A simple BankAccount class should keep its balance hidden from direct outside access, only exposing deposit and withdraw actions.", objective: "Create `class BankAccount` with a `private balance: number` initialized to 0 in the constructor, plus public methods `deposit(amount: number)` and `getBalance(): number`.", constraints: "balance must be private. There must be no public setter for balance — only deposit() may increase it.", expectedOutput: "After `acc.deposit(100); acc.deposit(50);`, `console.log(acc.getBalance())` prints: 150", check: "Confirm `acc.balance` is inaccessible from outside the class (compile error) and getBalance() is the only way to read it." },
  { id: 5, level: 1, title: "The Greeting Method", scenario: "You are building a simple onboarding widget that greets a new user by name using a class method.", objective: "Create `class Greeter` with a constructor storing a public `name: string`, and a method `greet(): string` returning a template literal like \"Welcome, NAME!\".", constraints: "greet() must use a template literal, not string concatenation with +.", expectedOutput: "`console.log(new Greeter(\"Mia\").greet())` prints: Welcome, Mia!", check: "Verify greet() returns a string (not void) and that it correctly reflects whatever name was passed to the constructor." },
  { id: 6, level: 2, title: "The Vehicle Hierarchy", scenario: "A fleet management system models vehicles generically, with cars adding their own extra detail.", objective: "Create `class Vehicle` with a constructor parameter property `public brand: string` and a method `describe(): string` returning \"Brand: X\". Create `class Car extends Vehicle` adding `public doors: number` via its own constructor, calling `super(brand)`, and overriding `describe()` to also include the door count.", constraints: "Car's constructor must call super(brand) before setting its own field. describe() in Car must call `super.describe()` and append to it.", expectedOutput: "`console.log(new Car(\"Toyota\", 4).describe())` prints something like: Brand: Toyota, Doors: 4", check: "Verify Car's describe() output contains both the inherited brand info (via super.describe()) and the doors count." },
  { id: 7, level: 2, title: "The Shielded Internal Counter", scenario: "A base Widget class tracks an internal render count that subclasses are allowed to inspect and bump, but external code should never touch directly.", objective: "Create `class Widget` with a `protected renderCount: number = 0` and a method `render(): void` that increments it. Create `class Button extends Widget` with a method `getRenderCount(): number` that returns the inherited renderCount.", constraints: "renderCount must be protected, not private or public. Button must access it via `this.renderCount`, not a getter defined in Widget.", expectedOutput: "After calling `render()` three times on a Button instance, `getRenderCount()` returns: 3", check: "Confirm `renderCount` cannot be accessed as `button.renderCount` from outside the class hierarchy (compile error), but Button's own method can read it." },
  { id: 8, level: 2, title: "The Notification Override", scenario: "A notification system has a base Notifier that logs a generic message; an EmailNotifier should override it to log something email-specific while still reusing the base behavior for its common prefix.", objective: "Create `class Notifier` with a method `notify(message: string): string` returning `\"[Notify] \" + message`. Create `class EmailNotifier extends Notifier` overriding `notify` to call `super.notify(message)` and wrap the result with \"(via email): \".", constraints: "EmailNotifier's notify must call super.notify(message) rather than duplicating the \"[Notify] \" prefix logic.", expectedOutput: "`console.log(new EmailNotifier().notify(\"Server down\"))` prints: (via email): [Notify] Server down", check: "Verify removing the super.notify() call and hardcoding the prefix would violate the DRY constraint; the override must delegate to the parent." },
  { id: 9, level: 2, title: "The Polymorphic Shape List", scenario: "A drawing app stores many different shapes in one list and needs to compute their total area regardless of specific shape type.", objective: "Create `class Shape` with a method `area(): number` returning 0. Create `class Circle extends Shape` and `class Rectangle extends Shape`, each overriding area() correctly (radius-based and width*height-based respectively). Store instances of both in a `Shape[]` array and sum their areas with reduce.", constraints: "The array must be typed as Shape[] (not a union or any[]). Use polymorphic dispatch (calling `.area()` on the Shape-typed reference) rather than type-checking each element.", expectedOutput: "For a Circle(radius=2) and Rectangle(width=3,height=4), the summed area (rounded) logs approximately: 25", check: "Verify that calling area() on each Shape[] element invokes the correct overridden implementation, not the base Shape.area() returning 0." },
  { id: 10, level: 2, title: "The Interface-Backed Logger", scenario: "Your team wants any class that logs messages to guarantee it has a `log(message: string): void` method, checked at compile time.", objective: "Define `interface Loggable { log(message: string): void; }`. Create `class ConsoleLogger implements Loggable` with a log() method that prints `\"[LOG] \" + message`.", constraints: "ConsoleLogger must use the `implements` keyword, not `extends`. The interface must not provide any implementation.", expectedOutput: "`new ConsoleLogger().log(\"Started\")` prints: [LOG] Started", check: "Verify that removing the log() method from ConsoleLogger would cause a compile error due to the unfulfilled Loggable contract." },
  { id: 11, level: 3, title: "The Abstract Payment Method", scenario: "An e-commerce checkout supports multiple payment types, all of which must implement their own charge logic but share a common receipt-printing method.", objective: "Create `abstract class PaymentMethod` with an `abstract charge(amount: number): string` method and a concrete `printReceipt(amount: number): string` method that calls `this.charge(amount)` and wraps it with \"Receipt: \". Create `class CreditCard extends PaymentMethod` implementing charge() to return \"Charged $X to credit card\".", constraints: "PaymentMethod must not be instantiable directly (attempting `new PaymentMethod()` must be a compile error). CreditCard must implement charge().", expectedOutput: "`console.log(new CreditCard().printReceipt(50))` prints: Receipt: Charged $50 to credit card", check: "Verify `new PaymentMethod()` is a compile error, and that printReceipt correctly calls the CreditCard-specific charge() via dynamic dispatch." },
  { id: 12, level: 3, title: "The Instance Counter", scenario: "A monitoring tool wants to know how many User objects have been created across the app's lifetime, without tracking each instance manually.", objective: "Create `class User` with a `static count: number = 0` and increment it inside the constructor. Add a `static getCount(): number` method returning the current count.", constraints: "count must be static, not an instance field. Do not use a module-level (outside-the-class) variable to track the count.", expectedOutput: "After creating 3 User instances, `console.log(User.getCount())` prints: 3", check: "Verify count is accessed as User.count (or via the static method), not on any individual instance, and that each `new User()` call increments it by exactly 1." },
  { id: 13, level: 3, title: "The Temperature Converter Property", scenario: "A weather widget internally stores temperature in Celsius but should let callers read and write in Fahrenheit through natural property syntax.", objective: "Create `class Temperature` with a `private celsius: number = 0` and a getter/setter pair named `fahrenheit` that converts on read (`celsius * 9/5 + 32`) and on write (`(value - 32) * 5/9`).", constraints: "Callers must use `temp.fahrenheit = 212` and `temp.fahrenheit` (property syntax), not method calls like `.setFahrenheit()`.", expectedOutput: "After `temp.fahrenheit = 212;`, `console.log(temp.fahrenheit)` prints: 212 (and internally celsius is 100)", check: "Verify the setter correctly converts Fahrenheit to Celsius for storage, and the getter converts back, round-tripping the original value." },
  { id: 14, level: 3, title: "The Lazy Singleton Configuration", scenario: "An app-wide configuration object should be created only once, the first time it is needed, and reused everywhere afterward.", objective: "Create `class AppConfig` with a `private static instance: AppConfig | undefined`, a `private constructor()`, and a `static getInstance(): AppConfig` that lazily creates and caches the instance using `??=`.", constraints: "The constructor must be private, preventing `new AppConfig()` from outside the class. getInstance() must return the SAME instance on every call.", expectedOutput: "`console.log(AppConfig.getInstance() === AppConfig.getInstance())` prints: true", check: "Verify `new AppConfig()` outside the class is a compile error, and that two separate getInstance() calls return reference-equal objects." },
  { id: 15, level: 3, title: "The Multi-Interface Media Player", scenario: "A media player component needs to satisfy two separate capability contracts used elsewhere in the codebase: one for playback controls, one for volume controls.", objective: "Define `interface Playable { play(): void; pause(): void; }` and `interface VolumeControllable { setVolume(level: number): void; }`. Create `class MediaPlayer implements Playable, VolumeControllable` fulfilling all three methods (each can just log a message).", constraints: "MediaPlayer must implement both interfaces in one `implements Playable, VolumeControllable` clause, not two separate class declarations.", expectedOutput: "Calling `player.play(); player.setVolume(80);` logs two messages without any compile errors.", check: "Verify removing any one of the three required methods (play, pause, setVolume) causes a compile error due to an unfulfilled interface." },
  { id: 16, level: 4, title: "The Truly Hidden PIN", scenario: "A security-sensitive Card class must store a PIN so that it is inaccessible even via casting tricks like `as any`, unlike a TypeScript `private` field.", objective: "Create `class Card` using a true JavaScript private field `#pin: string` set in the constructor, and a method `verify(attempt: string): boolean` comparing it. Do NOT use the `private` keyword for this field.", constraints: "Must use the `#pin` syntax, not `private pin`. verify() must be the only way to check the PIN.", expectedOutput: "`console.log(new Card(\"1234\").verify(\"1234\"), new Card(\"1234\").verify(\"0000\"))` prints: true false", check: "Verify that `(card as any).#pin` is not a valid way to bypass the field — # fields are enforced by the JS runtime itself, not just the compiler." },
  { id: 17, level: 4, title: "The Safely Overridden Discount", scenario: "A base Order class computes a default discount; a SeasonalOrder subclass needs to override it, and the team wants compile-time protection against typos breaking the override relationship.", objective: "Create `class Order` with a method `getDiscount(): number` returning 0. Create `class SeasonalOrder extends Order` with `override getDiscount(): number` returning 0.1. Enable the mental model of `noImplicitOverride` by ensuring the override keyword is used correctly.", constraints: "SeasonalOrder's getDiscount must use the `override` keyword. Renaming the base method (breaking the override) should be understood to cause a compile error.", expectedOutput: "`console.log(new SeasonalOrder().getDiscount())` prints: 0.1", check: "Verify that if Order's getDiscount were renamed without updating SeasonalOrder, TypeScript (with noImplicitOverride) would flag the mismatched override." },
  { id: 18, level: 4, title: "The Fluent Query Builder", scenario: "A lightweight query-builder utility should let callers chain multiple filter calls fluently before building the final query string.", objective: "Create `class QueryBuilder` with a private `parts: string[] = []`, a method `where(condition: string): this` that pushes to parts and returns `this`, and a `build(): string` that joins parts with \" AND \".", constraints: "where() must return `this` (the polymorphic this type), not `QueryBuilder`, to support chaining and future subclassing.", expectedOutput: "`new QueryBuilder().where(\"age > 18\").where(\"active = true\").build()` returns: age > 18 AND active = true", check: "Verify that chaining three or more .where() calls works correctly and that where() returning `this` (not void) is what enables the chain." },
  { id: 19, level: 4, title: "The Precomputed Static Lookup", scenario: "A class representing days of the week wants a static lookup table built once when the class is first defined, rather than recomputed on every use.", objective: "Create `class DayInfo` with a `static abbreviations: Record<string, string>` populated inside a `static { ... }` initialization block, mapping full day names to 3-letter abbreviations for at least 3 days.", constraints: "The lookup table must be populated inside a `static { }` block, not via a simple one-line field initializer.", expectedOutput: "`console.log(DayInfo.abbreviations[\"Monday\"])` prints: Mon", check: "Verify the static block runs exactly once (at class definition time) and DayInfo.abbreviations is accessible as a static property, not per-instance." },
  { id: 20, level: 4, title: "The Equatable Money Value", scenario: "A Money class stores cents privately using true private fields, but still needs an equals() method that can compare two DIFFERENT Money instances' hidden values.", objective: "Create `class Money` with a `#cents: number` set via the constructor, and a method `equals(other: Money): boolean` that compares `this.#cents === other.#cents`.", constraints: "cents must be a true `#` private field. equals() must directly access `other.#cents` (not a public getter) to prove same-class private access works.", expectedOutput: "`console.log(new Money(500).equals(new Money(500)), new Money(500).equals(new Money(300)))` prints: true false", check: "Verify that #cents remains completely inaccessible from outside the class, while equals() can still read it on another Money instance." },
  { id: 21, level: 5, title: "The Timestamped Entity Mixin", scenario: "Several unrelated classes (Post, Comment) need a `createdAt` timestamp added automatically without duplicating that field and its initialization in each class, and without disturbing their existing single-inheritance chain.", objective: "Write a mixin function `function Timestamped<TBase extends new (...args: any[]) => {}>(Base: TBase)` that returns a new class extending Base with a `createdAt: number = Date.now()` field. Apply it to a plain `class Post { constructor(public title: string) {} }` to create `TimestampedPost`.", constraints: "Must use the \"function returning a class expression extending Base\" mixin pattern, not manual property copying.", expectedOutput: "`const p = new (Timestamped(Post))(\"Hello\"); console.log(p.title, typeof p.createdAt);` prints: Hello number", check: "Verify the resulting TimestampedPost instance has both the original Post fields/methods AND the new createdAt field." },
  { id: 22, level: 5, title: "The Branded Currency Guard", scenario: "A finance app represents both USD and EUR amounts as plain numbers internally, but wants the type system to prevent accidentally passing a EUR value where a USD value is expected.", objective: "Define a branded type pattern `type Brand<T, B extends string> = T & { readonly __brand: B }`, then `type USD = Brand<number, \"USD\">` and `type EUR = Brand<number, \"EUR\">`. Write `function spendUSD(amount: USD): void` and helper functions `toUSD`/`toEUR` using `as` assertions.", constraints: "Attempting to call spendUSD with a raw number or an EUR-branded value (without a valid conversion) must be a compile error.", expectedOutput: "`spendUSD(toUSD(100))` compiles and runs; `spendUSD(toEUR(100) as any)` demonstrates the bypass is only possible by defeating the type system.", check: "Verify that `spendUSD(50)` (a raw unbranded number) and `spendUSD(toEUR(50))` are both compile errors without an explicit unsafe cast." },
  { id: 23, level: 5, title: "The Generic Repository Contract", scenario: "You are standardizing how the app accesses in-memory collections of different entity types (users, products) behind one consistent, generic class contract.", objective: "Define `interface Repository<T> { getAll(): T[]; getById(id: number): T | undefined; }`. Create `class InMemoryRepository<T extends { id: number }> implements Repository<T>` storing an internal `private items: T[]` passed via constructor, implementing both methods.", constraints: "The class must be generic and constrained with `T extends { id: number }` since getById relies on comparing by id.", expectedOutput: "For a repo of `{id:1,name:\"A\"}` and `{id:2,name:\"B\"}`, `repo.getById(2)?.name` returns: B", check: "Verify the class correctly implements the generic Repository<T> interface and that getById returns undefined for a non-existent id." },
  { id: 24, level: 5, title: "The Type-Safe Observable Store", scenario: "A small state-management utility needs a class that lets multiple subscribers react to state changes, with each subscriber able to cleanly unsubscribe later.", objective: "Create `class Store<T>` with a private `state: T`, a private `#subscribers: Array<(state: T) => void>`, a `subscribe(fn: (state: T) => void): () => void` method that returns an unsubscribe closure, and a `setState(next: T): void` method that updates state and notifies subscribers.", constraints: "subscribe() must return a function (the unsubscribe closure), not an id or index. Unsubscribing must remove exactly that one subscriber.", expectedOutput: "After subscribing, calling setState once notifies the subscriber; after calling the returned unsubscribe function, a second setState call does not notify it.", check: "Verify the closure-based unsubscribe correctly filters out only the specific subscriber function that was passed to subscribe(), leaving others intact." },
  { id: 25, level: 5, title: "The Polymorphic Factory Method", scenario: "A base Shape class wants a static factory method that, when called on a subclass, correctly constructs an instance of THAT subclass rather than always the base class.", objective: "Create `abstract class Shape` with a `static create<T extends Shape>(this: new () => T): T { return new this(); }`-style factory (or equivalent using `new this()` inside a static method), plus an abstract `describe(): string`. Create `class Square extends Shape` implementing describe().", constraints: "The factory method must use `new this()` (polymorphic static this) rather than hardcoding a specific class name, so calling it on any subclass produces the right type.", expectedOutput: "`console.log(Square.create().describe())` returns the Square-specific description, not an error about an abstract Shape.", check: "Verify that calling the static factory on Square (not Shape directly) produces a real, fully usable Square instance via `new this()` dispatch." },
],
generics: [
  { id: 1, level: 1, title: "The Identity Utility", scenario: "You are building a small utility library and want a function that simply returns whatever value it is given, but with full type preservation for every possible caller.", objective: "Write a generic function `function identity<T>(value: T): T` that returns its argument unchanged. Call it with a number and with a string, logging both results.", constraints: "Do not use `any` anywhere in the signature. T must be inferred from the call site, not hardcoded.", expectedOutput: "`console.log(identity(42), identity(\"hello\"))` prints: 42 hello", check: "Verify that `identity(42)` has inferred type number (not any) and `identity(\"hello\")` has inferred type string." },
  { id: 2, level: 1, title: "The Array Wrapper", scenario: "A helper library needs a function that takes any single value and wraps it into a one-element array, preserving the exact element type.", objective: "Write `function wrapInArray<T>(item: T): T[]` that returns `[item]`. Test it with a number and a string.", constraints: "The return type must be T[], not any[] or unknown[].", expectedOutput: "`console.log(wrapInArray(5), wrapInArray(\"go\"))` prints: [5] [go]", check: "Verify wrapInArray(5) has type number[] and wrapInArray(\"go\") has type string[]." },
  { id: 3, level: 1, title: "The Constrained Length Logger", scenario: "You want a utility that logs the length of anything that has a length property — strings, arrays, or custom objects — but should reject values that have no length at all.", objective: "Write `function logLength<T extends { length: number }>(item: T): number` returning `item.length`. Call it with an array and a string.", constraints: "T must be constrained with `extends { length: number }`. Calling logLength(42) (a plain number) must be a compile error.", expectedOutput: "`console.log(logLength([1,2,3]), logLength(\"hello\"))` prints: 3 5", check: "Verify that logLength(42) fails to compile since number has no length property, confirming the constraint is enforced." },
  { id: 4, level: 1, title: "The Generic Box Interface", scenario: "You need a reusable container shape that can hold exactly one value of any single type, used across several parts of the app.", objective: "Define `interface Box<T> { value: T; }`. Create a `Box<string>` and a `Box<number>`, each holding an appropriate value, and log both.", constraints: "Both Box instances must be declared with explicit type arguments (Box<string>, Box<number>).", expectedOutput: "`console.log(stringBox.value, numberBox.value)` prints: hello 42", check: "Verify assigning a number to the string Box's value (or vice versa) is a compile error." },
  { id: 5, level: 1, title: "The Two-Type Pair Maker", scenario: "A utility function needs to combine two independently-typed values (like a name and an age) into a single tuple for easy destructuring elsewhere.", objective: "Write `function pair<T, U>(a: T, b: U): [T, U]` returning `[a, b]`. Call it with a string and a number, then destructure the result.", constraints: "Must use two independent type parameters T and U, not a single shared one.", expectedOutput: "`const [name, age] = pair(\"Kai\", 4); console.log(name, age);` prints: Kai 4", check: "Verify calling pair(\"Kai\", 4) with two DIFFERENT types compiles cleanly (proving T and U are independent)." },
  { id: 6, level: 2, title: "The Safe Property Getter", scenario: "You are writing a utility to safely read any property off any object, with the compiler catching typos in property names at compile time.", objective: "Write `function getProperty<T, K extends keyof T>(obj: T, key: K): T[K]` returning `obj[key]`. Call it on a user object to read \"name\" and \"age\".", constraints: "K must be constrained with `extends keyof T`. Calling getProperty(user, \"email\") on an object without an email field must be a compile error.", expectedOutput: "For `{name: \"Kai\", age: 4}`, `getProperty(user, \"name\")` returns: Kai", check: "Verify passing a key not present on T (like \"email\") is a compile error, and the return type matches the specific property's type (string for name, number for age)." },
  { id: 7, level: 2, title: "The Generic Stack Class", scenario: "You need a reusable Stack data structure that can hold any single type of item consistently (all numbers, or all strings, but not mixed).", objective: "Create `class Stack<T>` with a private `items: T[] = []`, and methods `push(item: T): void`, `pop(): T | undefined`, and `peek(): T | undefined`.", constraints: "The class must be generic. Do not use `any` for items.", expectedOutput: "For a `Stack<number>` pushed with 1, 2, 3: `stack.pop()` returns 3, then `stack.peek()` returns 2.", check: "Verify that pushing a string onto a Stack<number> is a compile error." },
  { id: 8, level: 2, title: "The Typed Lookup Table", scenario: "You are building a color theme system where a fixed set of theme names (\"light\", \"dark\") must each map to a full color configuration object.", objective: "Define `type Theme = \"light\" | \"dark\";` and `type ThemeColors = Record<Theme, { background: string; text: string }>`. Create a ThemeColors object with both themes filled in.", constraints: "Must use Record<Theme, {...}>. Omitting either \"light\" or \"dark\" from the object must be a compile error.", expectedOutput: "`console.log(colors.dark.background)` prints the dark theme's configured background color, e.g.: #000", check: "Verify that omitting the \"dark\" key entirely from the colors object causes a compile error (Record requires all keys)." },
  { id: 9, level: 2, title: "The Grouping Utility", scenario: "A reporting tool needs to group a flat list of items into buckets based on a computed key, such as grouping numbers by even/odd.", objective: "Write `function groupBy<T, K extends string | number>(items: T[], keyFn: (item: T) => K): Record<K, T[]>` that buckets items by the key returned from keyFn.", constraints: "K must be constrained to `string | number` (valid object key types). Use `??=` or an equivalent to initialize each bucket.", expectedOutput: "For `groupBy([1,2,3,4], n => n % 2 === 0 ? \"even\" : \"odd\")`, the result's `.even` is [2,4] and `.odd` is [1,3].", check: "Verify the function works generically for a different element type (e.g. grouping strings by their first letter) without modification." },
  { id: 10, level: 2, title: "The Fallback Value Resolver", scenario: "A settings loader needs a generic helper that returns a stored value if present, or a fallback of the exact same type if the value is missing.", objective: "Write `function withDefault<T>(value: T | undefined, fallback: T): T` returning the fallback only when value is undefined.", constraints: "Both value and fallback must share the same inferred T — the function must reject mismatched types between them.", expectedOutput: "`console.log(withDefault(undefined, \"dark\"), withDefault(\"light\", \"dark\"))` prints: dark light", check: "Verify calling withDefault(\"x\", 5) (mismatched types for value and fallback) is a compile error." },
  { id: 11, level: 3, title: "The Pluck Field Extractor", scenario: "You are writing a reporting utility that extracts a single named field from a list of objects, and needs the result array to keep the exact field type.", objective: "Write `function pluck<T, K extends keyof T>(items: T[], key: K): T[K][]` returning an array of the extracted values.", constraints: "Must use K extends keyof T. The return type must be T[K][], not any[].", expectedOutput: "For `pluck([{name:\"A\",age:1},{name:\"B\",age:2}], \"age\")`, the result is: [1, 2]", check: "Verify the inferred return type is number[] when plucking \"age\" and string[] when plucking \"name\" from the same array." },
  { id: 12, level: 3, title: "The Chainable Box", scenario: "A functional-style Box<T> wrapper needs a map() method that can transform its contents into a DIFFERENT type, similar to Array.prototype.map.", objective: "Create `class Box<T>` with a constructor storing a `private value: T`, an `unwrap(): T` method, and a `map<U>(fn: (value: T) => U): Box<U>` method returning a new Box.", constraints: "map must introduce its own type parameter U, separate from the class-level T.", expectedOutput: "`new Box(3).map(n => n.toString()).map(s => s + \"!\").unwrap()` returns: 3!", check: "Verify chaining multiple .map() calls with different transformation types (number -> string -> string) all type-check correctly." },
  { id: 13, level: 3, title: "The Merge Two Objects Utility", scenario: "A configuration system needs to merge a base config object with an override object, producing a combined object typed with both sets of properties.", objective: "Write `function merge<T extends object, U extends object>(a: T, b: U): T & U` that returns `{ ...a, ...b }`.", constraints: "Both T and U must be constrained to `object`. The return type must be the intersection T & U.", expectedOutput: "`console.log(merge({name:\"Kai\"}, {age:4}))` prints: { name: \"Kai\", age: 4 }", check: "Verify the merged result's type has BOTH name and age accessible, and that passing a primitive (like a number) for either argument is a compile error." },
  { id: 14, level: 3, title: "The Type-Safe Event Emitter", scenario: "A small in-app event system needs full type checking so that emitting an event with the wrong argument types is caught at compile time.", objective: "Define `type Events = { login: [userId: number]; logout: [] };`. Create `class Emitter<T extends Record<string, unknown[]>>` with `on<K extends keyof T>(event: K, handler: (...args: T[K]) => void)` and `emit<K extends keyof T>(event: K, ...args: T[K])`.", constraints: "Emitting \"login\" without a numeric userId argument (or with a wrong-typed argument) must be a compile error.", expectedOutput: "After `emitter.on(\"login\", id => console.log(\"in:\", id)); emitter.emit(\"login\", 7);`, logs: in: 7", check: "Verify calling `emitter.emit(\"login\", \"not-a-number\")` is a compile error, proving the per-event argument types are enforced." },
  { id: 15, level: 3, title: "The Overloaded Formatter", scenario: "A formatting utility needs to behave differently depending on whether it receives a string or a number, with callers seeing the precise return type for each case.", objective: "Write function overloads: `function format(x: string): string; function format(x: number): string; function format(x: string | number): string { ... }` where strings are uppercased and numbers are formatted with 2 decimal places.", constraints: "Must declare the two specific overload signatures before the general implementation signature.", expectedOutput: "`console.log(format(\"hi\"), format(3))` prints: HI 3.00", check: "Verify callers see format(string) and format(number) as the only two callable overloads, not the broader union signature." },
  { id: 16, level: 4, title: "The Array Element Extractor", scenario: "You need a type-level utility that, given any array type, extracts the type of a single element from it — useful for deriving item types from existing array type definitions.", objective: "Define `type ElementType<T> = T extends (infer U)[] ? U : never;`. Use it to derive the element type of `string[]` and confirm a variable of that derived type accepts a string.", constraints: "Must use the `infer` keyword inside a conditional type, not a manual/hardcoded type.", expectedOutput: "`type Elem = ElementType<string[]>; const x: Elem = \"hi\"; console.log(x);` prints: hi", check: "Verify that ElementType<number[]> resolves to number, and ElementType applied to a non-array type resolves to never." },
  { id: 17, level: 4, title: "The Recursive Deep Partial", scenario: "A configuration-patching function needs to accept a partial update to a deeply nested settings object, where ANY level of nesting can be partially provided.", objective: "Define `type DeepPartial<T> = T extends object ? { [K in keyof T]?: DeepPartial<T[K]> } : T;`. Apply it to a nested Config interface and pass in an object that only sets one deeply nested field.", constraints: "The built-in Partial<T> (shallow) must NOT be sufficient for this task — DeepPartial must recurse into nested objects.", expectedOutput: "For `interface Config { server: { port: number; host: string } }`, `const patch: DeepPartial<Config> = { server: { port: 9090 } };` compiles successfully.", check: "Verify that using the built-in shallow Partial<Config> instead would still require providing the full nested server object, while DeepPartial does not." },
  { id: 18, level: 4, title: "The Memoized Function Wrapper", scenario: "An expensive computation is called repeatedly with the same arguments; you want a generic wrapper that caches results while preserving the original function's exact type signature.", objective: "Write `function memoize<T extends (...args: any[]) => any>(fn: T): T` using `Parameters<T>` and `ReturnType<T>` internally, caching results in a Map keyed by JSON.stringify(args).", constraints: "The wrapped function's type must remain exactly T (same parameters and return type), not a loosened `(...args: any[]) => any`.", expectedOutput: "For a memoized `(n: number) => n * n` called twice with 4, the underlying computation runs only once, and both calls return: 16", check: "Verify the memoized function is still callable with the exact same parameter types as the original, and that repeated identical calls hit the cache." },
  { id: 19, level: 4, title: "The Tuple Head and Tail", scenario: "A type-level utility library needs to split a tuple type into its first element and the remaining elements, mirroring array destructuring at the type level.", objective: "Define `type Head<T extends unknown[]> = T extends [infer H, ...unknown[]] ? H : never;` and `type Tail<T extends unknown[]> = T extends [unknown, ...infer R] ? R : [];`. Apply both to `[string, number, boolean]`.", constraints: "Must use tuple-shaped infer patterns, not array indexing.", expectedOutput: "`type H = Head<[string, number, boolean]>; type T = Tail<[string, number, boolean]>; const h: H = \"x\"; const t: T = [1, true]; console.log(h, t);` prints: x [1, true]", check: "Verify Head correctly extracts just the first element type and Tail correctly extracts a tuple of the remaining element types." },
  { id: 20, level: 4, title: "The Discriminated Result Handler", scenario: "An API-calling utility needs a generic Result type that clearly separates a successful response (with typed data) from a failure (with an error message), and a handler function that safely processes either.", objective: "Define `type ApiResult<T> = { success: true; data: T } | { success: false; error: string };`. Write `function handleResult<T>(result: ApiResult<T>): T | null` that returns data on success or logs the error and returns null on failure.", constraints: "Must use the `success` field as a discriminant to narrow the union inside handleResult, not a type assertion.", expectedOutput: "For `handleResult<number>({ success: false, error: \"not found\" })`, the function logs \"Error: not found\" and returns: null", check: "Verify accessing `.data` or `.error` without first checking `.success` would be a compile error, confirming proper discriminated union narrowing is required." },
  { id: 21, level: 5, title: "The Tuple Concatenator", scenario: "A utility library needs a fully type-safe way to concatenate two tuples of potentially different lengths and element types into one combined tuple, preserving every position's exact type.", objective: "Write `function concat<T extends unknown[], U extends unknown[]>(a: [...T], b: [...U]): [...T, ...U]` that returns `[...a, ...b]`.", constraints: "Must use variadic tuple types (the `[...T, ...U]` syntax), not a generic T[] return type.", expectedOutput: "`console.log(concat([1, 2] as const, [\"a\", \"b\"] as const))` prints: [1, 2, \"a\", \"b\"]", check: "Verify the inferred return type preserves each specific position's type (e.g. [number, number, string, string]) rather than widening to (number|string)[]." },
  { id: 22, level: 5, title: "The Type-Safe Fluent Config Builder", scenario: "A configuration builder should let callers chain `.option(key, value)` calls, with the FINAL accumulated shape of all provided options tracked precisely by the type system across the whole chain.", objective: "Define a recursive `type Chainable<T = {}> = { option<K extends string, V>(key: K, value: V): Chainable<T & Record<K, V>>; get(): T; };` and implement a `config(): Chainable` factory. Chain two .option() calls and call .get().", constraints: "Each .option() call must return a NEW Chainable type with the accumulated intersection, not lose previously set keys.", expectedOutput: "`config().option(\"port\", 8080).option(\"host\", \"localhost\").get()` has a statically known shape with both `port: number` and `host: string`.", check: "Verify that accessing `.port` and `.host` on the final .get() result both type-check, proving both chained options were accumulated into the tracked type." },
  { id: 23, level: 5, title: "The Branded ID Guard", scenario: "A codebase has both UserId and ProductId represented as plain numbers, and a recent bug involved accidentally passing a ProductId where a UserId was expected. You need to prevent this class of bug at compile time.", objective: "Define `type Brand<T, B extends string> = T & { readonly __brand: B };`, `type UserId = Brand<number, \"UserId\">`, `type ProductId = Brand<number, \"ProductId\">`, and `function getUser(id: UserId): void`. Create helper functions to safely produce each branded type.", constraints: "Passing a raw number, or a ProductId, directly to getUser must be a compile error without an explicit unsafe cast.", expectedOutput: "Calling `getUser(toUserId(5))` compiles and runs; calling `getUser(toProductId(5))` must fail to compile.", check: "Verify that even though UserId and ProductId are both structurally \"number & {brand}\", their different brand literals make them mutually incompatible." },
  { id: 24, level: 5, title: "The Union-To-Intersection Merge Type", scenario: "A plugin system collects several independently-typed plugin option objects into a union, but the final merged options object passed to the app needs to be the INTERSECTION of all of them (having every plugin's options simultaneously).", objective: "Define `type UnionToIntersection<U> = (U extends any ? (k: U) => void : never) extends (k: infer I) => void ? I : never;`. Apply it to a union of two plugin option interfaces and construct an object satisfying the resulting intersection.", constraints: "Must use the function-parameter-contravariance trick shown above, not a hand-written intersection.", expectedOutput: "For `UnionToIntersection<{a: number} | {b: string}>`, an object `{ a: 1, b: \"x\" }` satisfies the resulting type, and logs: 1 x", check: "Verify that an object missing either the `a` or `b` field would fail to satisfy the derived intersection type." },
  { id: 25, level: 5, title: "The Generic Mixin-Based Serializable Entity", scenario: "Several domain classes (Point, User) need a `serialize()` method added without rewriting each one individually, and without breaking their own independent constructors and fields.", objective: "Write `function Serializable<TBase extends new (...args: any[]) => {}>(Base: TBase)` returning `class extends Base { serialize() { return JSON.stringify(this); } }`. Apply it to a plain `class Point { constructor(public x = 1, public y = 2) {} }`.", constraints: "Must use the generic constructor-type mixin pattern (`new (...args: any[]) => T`), not manual property copying onto Point.prototype.", expectedOutput: "`const SerializablePoint = Serializable(Point); console.log(new SerializablePoint().serialize());` prints: {\"x\":1,\"y\":2}", check: "Verify the resulting class still has Point's original constructor behavior (x and y defaults) AND the newly mixed-in serialize() method." },
],
advancedtypes: [
  { id: 1, level: 1, title: "The Flexible ID Parameter", scenario: "A lookup function needs to accept an identifier that might be given as either a numeric database id or a string UUID.", objective: "Write `function findById(id: string | number): string` that returns a template literal like \"Looking up: ID\". Call it once with a string and once with a number.", constraints: "The parameter must use a union type (string | number), not `any`.", expectedOutput: "`console.log(findById(42), findById(\"abc-123\"))` prints: Looking up: 42 Looking up: abc-123", check: "Verify calling findById(true) (a boolean) is a compile error, since boolean is not part of the union." },
  { id: 2, level: 1, title: "The Combined Contact Shape", scenario: "A contact form combines a person's basic name info with their separately-defined contact info into one required shape.", objective: "Define `interface HasName { name: string; }` and `interface HasContact { email: string; }`. Create a variable typed `HasName & HasContact` and populate both fields.", constraints: "Must use the `&` intersection operator, not manually merging into a single interface.", expectedOutput: "`console.log(person.name, person.email)` prints: Kai kai@example.com", check: "Verify that omitting either name or email from the object literal is a compile error, since the intersection requires both." },
  { id: 3, level: 1, title: "The Direction Restrictor", scenario: "A game character movement function should only accept one of four valid direction strings, rejecting typos like \"diagonal\" at compile time.", objective: "Define `type Direction = \"up\" | \"down\" | \"left\" | \"right\";` and write `function move(direction: Direction): string` returning \"Moving DIRECTION\".", constraints: "The parameter type must be the Direction literal union, not plain `string`.", expectedOutput: "`console.log(move(\"up\"))` prints: Moving up", check: "Verify calling move(\"diagonal\") is a compile error since \"diagonal\" is not one of the four allowed literal values." },
  { id: 4, level: 1, title: "The Safe String Checker", scenario: "A form validator receives a value of unknown type and must confirm it is actually a string before applying string-specific formatting.", objective: "Write `function formatIfString(value: unknown): string` that uses a `typeof value === \"string\"` check to safely call `.trim().toUpperCase()` on it, or returns \"N/A\" otherwise.", constraints: "The parameter must be typed `unknown`, not `any`. Do not call any string methods before narrowing.", expectedOutput: "`console.log(formatIfString(\"  hi  \"), formatIfString(42))` prints: HI N/A", check: "Verify that calling .trim() on `value` before the typeof check is a compile error due to unknown's restrictions." },
  { id: 5, level: 1, title: "The Frozen Feature Flags", scenario: "A small config object listing enabled feature flags should have its exact literal values (not just \"string\"/\"boolean\") preserved for later precise type checks.", objective: "Create `const flags = { darkMode: true, betaFeatures: false } as const;` and log `flags.darkMode`.", constraints: "Must use `as const`. Do not add an explicit type annotation that would widen the inferred types.", expectedOutput: "`console.log(flags.darkMode)` prints: true", check: "Verify that without as const, TypeScript would infer flags.darkMode as the general type boolean rather than the literal type true — and that with as const, the property is also readonly." },
  { id: 6, level: 2, title: "The Shape Area Calculator", scenario: "A drawing app needs to compute the area of different shape descriptions, each tagged with a `kind` field identifying which specific shape it is.", objective: "Define `interface Circle { kind: \"circle\"; radius: number; }` and `interface Square { kind: \"square\"; side: number; }`, plus `type Shape = Circle | Square;`. Write `function area(shape: Shape): number` using shape.kind to narrow and compute the correct formula.", constraints: "Must narrow using the `kind` discriminant (an if/switch on shape.kind), not a type assertion.", expectedOutput: "`console.log(area({kind:\"square\", side:4}))` prints: 16", check: "Verify accessing shape.radius without first checking kind === \"circle\" is a compile error." },
  { id: 7, level: 2, title: "The Public User Profile", scenario: "A User record has sensitive fields (password) that must never be sent to the client; you need a type describing only the safe, public subset.", objective: "Define `interface User { id: number; name: string; email: string; password: string; }` and `type PublicUser = Omit<User, \"password\">`. Create a function `toPublicUser(user: User): PublicUser` that strips password.", constraints: "Must use the Omit utility type, not manually rewriting the interface.", expectedOutput: "For a User with password \"secret123\", `toPublicUser(user)` returns an object without a password field, e.g.: { id: 1, name: \"Kai\", email: \"k@x.com\" }", check: "Verify that PublicUser has no password property (accessing .password on it is a compile error)." },
  { id: 8, level: 2, title: "The Editable Draft Fields", scenario: "An article editor lets users update only the title and body of a Post, while id and author should never be editable through this form.", objective: "Define `interface Post { id: number; title: string; body: string; author: string; }` and `type EditableFields = Pick<Post, \"title\" | \"body\">`. Write `function updateDraft(current: Post, edits: EditableFields): Post`.", constraints: "edits must be typed as Pick<Post, \"title\" | \"body\">, accepting only those two fields.", expectedOutput: "For a post with id 1 and updates `{title: \"New Title\", body: \"New Body\"}`, updateDraft returns a Post with the id/author preserved and title/body replaced.", check: "Verify that passing an `id` field inside the edits object is a compile error (excess property), since EditableFields does not include id." },
  { id: 9, level: 2, title: "The Valid Key Extractor", scenario: "A form-rendering utility needs to know, at compile time, exactly which field names are valid to reference on a given settings object.", objective: "Define `interface Settings { theme: string; fontSize: number; notifications: boolean; }` and `type SettingsKey = keyof Settings;`. Write a function `getSetting(settings: Settings, key: SettingsKey)` returning the value at that key.", constraints: "SettingsKey must be derived via `keyof Settings`, not manually listed as a string union.", expectedOutput: "`console.log(getSetting(settings, \"fontSize\"))` returns the numeric font size, e.g.: 14", check: "Verify calling getSetting(settings, \"language\") (a non-existent key) is a compile error." },
  { id: 10, level: 2, title: "The Non-Null Cart Total", scenario: "A shopping cart's discount field might be null when no discount applies, but a total-calculating function needs a guaranteed non-null number to work with after resolving a default.", objective: "Write `function resolveDiscount(discount: number | null): NonNullable<number | null>` that returns `discount ?? 0`.", constraints: "The return type must be expressed using NonNullable, not manually rewritten as `number`.", expectedOutput: "`console.log(resolveDiscount(null), resolveDiscount(15))` prints: 0 15", check: "Verify NonNullable<number | null> resolves to exactly number, matching what ?? 0 actually produces." },
  { id: 11, level: 3, title: "The Fully Optional Draft", scenario: "A form auto-save feature needs to persist a partially-filled-out version of a Profile object, where any field might be missing at any point while the user is still typing.", objective: "Define `interface Profile { name: string; bio: string; avatarUrl: string; }` and write a mapped type `type Draft = { [K in keyof Profile]?: Profile[K] };` (equivalent to Partial<Profile>). Save an object with only one field set.", constraints: "Must write the mapped type manually using `[K in keyof Profile]?:`, not just referencing the built-in Partial.", expectedOutput: "`const draft: Draft = { name: \"Kai\" }; console.log(draft.name, draft.bio);` prints: Kai undefined", check: "Verify that a Draft object may legally omit bio and avatarUrl entirely, while still type-checking name as a string when present." },
  { id: 12, level: 3, title: "The Compile-Time Type Checker", scenario: "A validation utility needs a type-level helper that resolves to \"yes\" or \"no\" depending on whether a given type is specifically a string, for use in downstream conditional logic.", objective: "Define `type IsString<T> = T extends string ? \"yes\" : \"no\";`. Create typed constants proving `IsString<\"hello\">` is \"yes\" and `IsString<42>` is \"no\".", constraints: "Must use a conditional type (T extends string ? ... : ...), not a runtime typeof check.", expectedOutput: "`const a: IsString<\"hello\"> = \"yes\"; const b: IsString<42> = \"no\"; console.log(a, b);` prints: yes no", check: "Verify that `const wrong: IsString<42> = \"yes\";` is a compile error, since IsString<42> resolves specifically to the literal type \"no\"." },
  { id: 13, level: 3, title: "The Exhaustive Status Handler", scenario: "An order-tracking system has a fixed set of status values, and you want the compiler to force an update to the handler function whenever a new status is added to the type.", objective: "Define `type OrderStatus = \"pending\" | \"shipped\" | \"delivered\";`. Write `function describeStatus(status: OrderStatus): string` using a switch statement with a `default` branch that assigns status to a `const exhaustive: never = status;` to enforce exhaustiveness.", constraints: "Must include the `never`-typed exhaustiveness check in the default case, not just a plain default returning a generic string.", expectedOutput: "`console.log(describeStatus(\"shipped\"))` prints a description like: Your order has shipped", check: "Verify that if a new status like \"cancelled\" were added to OrderStatus without updating the switch, the never assignment would cause a compile error, catching the missing case." },
  { id: 14, level: 3, title: "The Validated Route Config", scenario: "A router configuration object should be checked against a Route shape for correctness, but its precise literal types (like exact path strings) need to be preserved for later precise route matching.", objective: "Define `interface Route { path: string; exact: boolean; }`. Create `const routes = { home: { path: \"/\", exact: true }, about: { path: \"/about\", exact: false } } satisfies Record<string, Route>;`.", constraints: "Must use `satisfies Record<string, Route>`, not a direct type annotation (`: Record<string, Route>`), so that literal keys \"home\"/\"about\" remain accessible via keyof typeof routes.", expectedOutput: "`console.log(routes.home.path)` prints: /", check: "Verify that `type RouteName = keyof typeof routes;` correctly resolves to \"home\" | \"about\" — which would NOT be preserved with a plain type annotation instead of satisfies." },
  { id: 15, level: 3, title: "The Fixed-Length Coordinate Tuple", scenario: "A geometry utility needs a 2D coordinate type that is guaranteed to always have exactly two numeric elements, unlike a general array which could have any length.", objective: "Define `type Coordinate = [number, number];` and write `function distance(a: Coordinate, b: Coordinate): number` computing the Euclidean distance.", constraints: "Coordinate must be a tuple type, not `number[]`. Passing a 3-element array must be a compile error.", expectedOutput: "`console.log(distance([0,0], [3,4]))` prints: 5", check: "Verify that calling distance([0,0,0], [3,4]) (a 3-element array for the first argument) is a compile error." },
  { id: 16, level: 4, title: "The Promise Unwrapper", scenario: "A utility function needs a type-level helper that extracts the resolved value type out of any Promise type, for use in typing async wrapper functions.", objective: "Define `type UnwrapPromise<T> = T extends Promise<infer U> ? U : T;`. Use it to type a variable holding the resolved value of a `Promise<number>` returning function.", constraints: "Must use `infer` inside a conditional type. UnwrapPromise applied to a non-Promise type should return that type unchanged.", expectedOutput: "`type Result = UnwrapPromise<Promise<number>>; const r: Result = 5; console.log(r);` prints: 5", check: "Verify UnwrapPromise<string> (a non-Promise type) resolves to plain string, not never." },
  { id: 17, level: 4, title: "The Deeply Frozen Settings", scenario: "An application-wide settings object, including all of its nested sub-objects, must be fully immutable at the type level so that no code anywhere can reassign even a deeply nested property.", objective: "Define a recursive `type DeepReadonly<T> = T extends object ? { readonly [K in keyof T]: DeepReadonly<T[K]> } : T;`. Apply it to a Settings interface with at least one nested object and verify a deeply nested property cannot be reassigned.", constraints: "The built-in shallow Readonly<T> must NOT be sufficient — DeepReadonly needs to recurse into nested objects.", expectedOutput: "For `interface Settings { server: { port: number } }`, a `DeepReadonly<Settings>` value logs its nested port normally, e.g.: 8080", check: "Verify that `settings.server.port = 9090` on a DeepReadonly<Settings>-typed variable is a compile error, while it would NOT be an error with the shallow built-in Readonly<Settings>." },
  { id: 18, level: 4, title: "The Handler Naming Generator", scenario: "A UI component library wants to programmatically derive consistent event-handler prop names (like \"onClick\") directly from a list of event names (like \"click\"), enforced at the type level.", objective: "Define `type EventName<T extends string> = `on${Capitalize<T>}`;`. Create a typed constant proving `EventName<\"click\">` equals the literal type \"onClick\".", constraints: "Must use a template literal type combined with the intrinsic `Capitalize<T>` type.", expectedOutput: "`const handlerName: EventName<\"click\"> = \"onClick\"; console.log(handlerName);` prints: onClick", check: "Verify that assigning the plain string \"onclick\" (lowercase c) to a variable typed EventName<\"click\"> is a compile error, since it does not match the exact expected literal." },
  { id: 19, level: 4, title: "The Runtime-Checked Assertion", scenario: "A function receives a value that should always be a non-null User by the time execution reaches a certain point, and you want the rest of the function to treat it as definitely non-null without repeated if-checks.", objective: "Write `function assertIsUser(value: unknown): asserts value is User` (for a simple `interface User { name: string }`) that throws if the value does not have a string `name` property. Use it in a function that then safely accesses `.name`.", constraints: "Must use the `asserts value is User` return type syntax, not a plain `value is User` type predicate used inside an if-statement.", expectedOutput: "For `const maybeUser: unknown = { name: \"Kai\" }; assertIsUser(maybeUser); console.log(maybeUser.name);` prints: Kai", check: "Verify that accessing maybeUser.name BEFORE calling assertIsUser would be a compile error, and that after the assertion call, maybeUser is narrowed to User for the rest of the scope." },
  { id: 20, level: 4, title: "The Filtered Function Properties", scenario: "A serialization utility needs to identify, at the type level, which properties of an API object are callable methods (which should be excluded from serialization) versus plain data fields.", objective: "Define `type FunctionPropertyNames<T> = { [K in keyof T]: T[K] extends (...args: any[]) => any ? K : never }[keyof T];`. Apply it to an interface with both data fields and methods.", constraints: "Must use the \"map to key or never, then index by keyof T\" filtering technique, not a manually written union of method names.", expectedOutput: "For `interface Api { fetch(): void; url: string; }`, `type Methods = FunctionPropertyNames<Api>;` resolves to exactly: \"fetch\"", check: "Verify that `const m: Methods = \"url\";` (a non-function property name) is a compile error, since url is filtered out." },
  { id: 21, level: 5, title: "The Route Parameter Extractor", scenario: "A type-safe router library needs to statically derive the set of dynamic parameter names (like \"id\" and \"postId\") directly from a route pattern string containing multiple `:param` segments.", objective: "Define a recursive `type ExtractRouteParams<T extends string> = T extends `${string}:${infer Param}/${infer Rest}` ? Param | ExtractRouteParams<`/${Rest}`> : T extends `${string}:${infer Param}` ? Param : never;`. Apply it to `\"/users/:id/posts/:postId\"`.", constraints: "Must use recursive template literal type matching with `infer`, not a hardcoded union of the two known parameter names.", expectedOutput: "`type Params = ExtractRouteParams<\"/users/:id/posts/:postId\">; const p: Params = \"postId\"; console.log(p);` prints: postId", check: "Verify that changing the route pattern to include a third `:param` segment automatically updates the derived Params union without any other code changes." },
  { id: 22, level: 5, title: "The Nominal Currency Types", scenario: "A finance module represents both USD and EUR as plain numbers but has had bugs from mixing them up; you need the type system to treat them as fully incompatible despite identical runtime representation.", objective: "Define `type Brand<T, B extends string> = T & { readonly __brand: B };`, `type USD = Brand<number, \"USD\">`, `type EUR = Brand<number, \"EUR\">`, helper functions `toUSD`/`toEUR`, and `function convert(amount: USD, rate: number): EUR`.", constraints: "convert must only accept a properly branded USD value, not a raw number or an EUR value, without an explicit unsafe cast.", expectedOutput: "`console.log(convert(toUSD(100), 0.9))` returns a EUR-branded value that logs as: 90", check: "Verify that calling `convert(50, 0.9)` (a raw unbranded number) is a compile error, proving the brand is required." },
  { id: 23, level: 5, title: "The Merged Plugin Options", scenario: "A plugin system collects a union of independently defined plugin option shapes, but the final application config object needs to satisfy ALL of them simultaneously (the intersection), not just one.", objective: "Define `type UnionToIntersection<U> = (U extends any ? (k: U) => void : never) extends (k: infer I) => void ? I : never;`. Apply it to a union of two plugin option interfaces (e.g. `{ retries: number } | { timeout: number }`) and construct a config object satisfying the merged type.", constraints: "Must use the function-parameter-contravariance UnionToIntersection trick, not manually intersecting the two interfaces by hand.", expectedOutput: "For the union `{retries: number} | {timeout: number}`, a config object `{ retries: 3, timeout: 5000 }` satisfies UnionToIntersection of that union, logging: 3 5000", check: "Verify that a config object missing either retries or timeout would fail to satisfy the derived intersection type." },
  { id: 24, level: 5, title: "The Recursive Config Merger", scenario: "Two configuration objects (defaults and overrides) need to be deeply merged, where nested objects on both sides combine field-by-field rather than one side wholesale replacing the other.", objective: "Define a recursive `type DeepMerge<T, U>` that, for each key in T or U, recursively merges the value if both sides have an object at that key, otherwise takes U's value (or T's if only T has it). Apply it to two configs with an overlapping nested object.", constraints: "Must handle the case where a key exists only in T, only in U, or in both (recursing when both values are objects).", expectedOutput: "For `type A = {a:{x:number}, b:string}` and `type B = {a:{y:number}, c:boolean}`, a `DeepMerge<A,B>`-typed object `{a:{x:1,y:2}, b:\"hi\", c:true}` type-checks and logs: 1 2", check: "Verify that the merged type requires BOTH x and y under the nested `a` key, proving the nested objects were recursively combined rather than one replacing the other." },
  { id: 25, level: 5, title: "The Exhaustive Discriminated Action Reducer", scenario: "A state-management reducer needs to handle a fixed, growing set of action types, with the compiler forcing every new action type to be handled and preventing you from ever forgetting a case.", objective: "Define `type CounterAction = { type: \"increment\"; amount: number } | { type: \"decrement\"; amount: number } | { type: \"reset\" };`. Write `function reducer(state: number, action: CounterAction): number` using a switch statement with a `default: { const exhaustive: never = action; throw new Error(\"Unhandled\"); }` exhaustiveness guard.", constraints: "Every member of CounterAction must be explicitly handled in its own case; the never-typed default must be present.", expectedOutput: "`console.log(reducer(5, {type:\"increment\", amount:3}), reducer(5, {type:\"reset\"}))` prints: 8 0", check: "Verify that adding a new action type (e.g. {type: \"double\"}) to CounterAction without adding a corresponding case would cause the never assignment to fail compilation." },
],
inference: [
  { id: 1, level: 1, title: "The Widened Status Flag", scenario: "You are building a small order-tracking script and need a status variable that starts as \"pending\" but will later be reassigned to other status strings.", objective: "Declare `let status = \"pending\";` with no type annotation. Log `status` and `typeof status`. Then reassign `status = \"shipped\";` and log it again.", constraints: "Do not add an explicit type annotation. Must use `let`, not `const`.", expectedOutput: "First log: pending string. Second log: shipped.", check: "Confirm TypeScript infers status as the widened type string (not the literal \"pending\"), which is exactly why reassigning to \"shipped\" compiles without error." },
  { id: 2, level: 1, title: "The Narrow Constant Label", scenario: "A UI component needs a constant label that should never change, and you want TypeScript to know its exact value, not just its general type.", objective: "Declare `const label = \"Confirm\";`. Log `label` and `typeof label`. In a comment, note what LITERAL type TypeScript infers for label.", constraints: "Must use `const`. Do not add an explicit type annotation.", expectedOutput: "`console.log(label, typeof label)` prints: Confirm string", check: "Verify (e.g. by hovering in an editor or attempting `const x: \"Confirm\" = label;`) that TypeScript infers the literal type \"Confirm\" for label, not the general string type." },
  { id: 3, level: 1, title: "The Inferred Price List", scenario: "An e-commerce cart needs a simple array of item prices with no explicit type written anywhere.", objective: "Declare `const prices = [19.99, 5.5, 12.0];` with no annotation. Log `prices` and use `prices.push(9.99)` to confirm it still works.", constraints: "Do not annotate the array type explicitly. Must use `const`.", expectedOutput: "`console.log(prices)` prints the four numbers after the push, ending in ...9.99.", check: "Confirm TypeScript infers prices as number[] (not a tuple, and not any[]) — attempting `prices.push(\"free\")` should be a type error." },
  { id: 4, level: 1, title: "The Self-Documenting Return Type", scenario: "You are writing a small helper function and want to rely on inference instead of manually typing the return value.", objective: "Write `function isEven(n: number) { return n % 2 === 0; }` with no explicit return type annotation. Log `isEven(4)` and `isEven(7)`.", constraints: "Do not add a `: boolean` return annotation. The parameter n must stay typed as number.", expectedOutput: "`console.log(isEven(4), isEven(7))` prints: true false", check: "Confirm the inferred return type of isEven is boolean by attempting `const check: boolean = isEven(2);` — it should compile with no annotation on isEven itself." },
  { id: 5, level: 1, title: "The Frozen Config Shape", scenario: "A small app config object should have every property locked to its exact literal value at the type level, not just widened primitives.", objective: "Declare `const config = { mode: \"production\", retries: 3 } as const;`. Log `config.mode` and `config.retries`. Attempt (in a comment) what would happen if you tried `config.mode = \"dev\";`.", constraints: "Must use `as const`. Do not write an explicit interface or type annotation.", expectedOutput: "`console.log(config.mode, config.retries)` prints: production 3", check: "Confirm that with `as const`, config.mode is inferred as the literal type \"production\" (not string) and is readonly — attempting to reassign it should be a compile error." },
  { id: 6, level: 2, title: "The Validated Settings Object", scenario: "You have a Settings interface and want to check a settings object against it for typos, without losing the object's precise literal types for later use in a switch statement.", objective: "Given `interface Settings { theme: \"light\" | \"dark\"; fontSize: number; }`, declare `const settings = { theme: \"dark\", fontSize: 14 } satisfies Settings;`. Log `settings.theme`.", constraints: "Must use `satisfies`, not `as` or a `: Settings` annotation. Do not change the interface.", expectedOutput: "`console.log(settings.theme)` prints: dark", check: "Confirm that after using satisfies, settings.theme is still inferred as the literal type \"dark\" (not the wider \"light\" | \"dark\"), while an invalid theme value like \"blue\" would still be caught as an error." },
  { id: 7, level: 2, title: "The Verified Non-Null Lookup", scenario: "You are reading from a Map that you know (by program logic) will always contain a given key, but TypeScript still types `.get()` as possibly undefined.", objective: "Given `const scores = new Map([[\"alice\", 90], [\"bob\", 85]]);`, write `const aliceScore = scores.get(\"alice\")!;` using the non-null assertion, then log `aliceScore.toFixed(1)`.", constraints: "Must use the `!` non-null assertion operator. Do not use an `if` check or optional chaining for this line.", expectedOutput: "`console.log(aliceScore.toFixed(1))` prints: 90.0", check: "Confirm that without the `!`, `aliceScore.toFixed(1)` would be a compile error since scores.get() returns number | undefined; with `!`, it compiles because the type is narrowed to number." },
  { id: 8, level: 2, title: "The Generic Pair Picker", scenario: "You are writing a small reusable utility that returns the first of two values of the same type, relying entirely on generic inference.", objective: "Write `function pickFirst<T>(a: T, b: T): T { return a; }`. Call it once with two numbers and once with two strings, logging both results and their `typeof`.", constraints: "Do not supply explicit type arguments (e.g. `pickFirst<number>`) at any call site — rely on inference alone.", expectedOutput: "Logs: 1 \"number\" then \"hi\" \"string\" (approximately, depending on your chosen values).", check: "Confirm T is inferred differently at each call site (e.g. number for pickFirst(1, 2), string for pickFirst(\"hi\", \"bye\")) purely from the argument types." },
  { id: 9, level: 2, title: "The Branching Return Type", scenario: "A parsing helper returns either a parsed number or undefined when parsing fails, and you want TypeScript to infer this automatically.", objective: "Write `function parseAge(input: string) { const n = Number(input); if (Number.isNaN(n)) return undefined; return n; }` with no explicit return type. Log the result for `parseAge(\"25\")` and `parseAge(\"abc\")`.", constraints: "Do not add an explicit return type annotation to parseAge.", expectedOutput: "`console.log(parseAge(\"25\"), parseAge(\"abc\"))` prints: 25 undefined", check: "Confirm the inferred return type of parseAge is `number | undefined` by verifying `const x: number | undefined = parseAge(\"1\");` compiles with no annotation needed on parseAge." },
  { id: 10, level: 2, title: "The Type-Predicate Filter", scenario: "You have an array that may contain nulls mixed with real values, and want the filtered result to be properly typed as having no nulls, not just filtered at runtime.", objective: "Given `const raw: (string | null)[] = [\"a\", null, \"b\", null, \"c\"];`, write a `.filter()` call using a type predicate `(x): x is string => x !== null` and store the result in `clean`. Log `clean`.", constraints: "The filter callback must be written as a type predicate (`(x): x is string => ...`), not a plain boolean-returning arrow function.", expectedOutput: "`console.log(clean)` prints: [ 'a', 'b', 'c' ]", check: "Confirm clean is inferred as string[] (not (string | null)[]) by verifying `clean.forEach(s => s.toUpperCase())` compiles with no additional narrowing needed." },
  { id: 11, level: 3, title: "The Runtime-Checked Assertion Helper", scenario: "Several functions across your codebase receive `unknown` values from an API and need a reusable way to confirm (and have TypeScript narrow) that a value is a non-null string.", objective: "Write `function assertIsString(x: unknown): asserts x is string { if (typeof x !== \"string\") throw new Error(\"Expected a string\"); }`. Use it inside a function that receives `data: unknown`, calls `assertIsString(data)`, then logs `data.toUpperCase()`.", constraints: "The assertion function must use the `asserts x is string` signature — do not use a type predicate (`x is string`) or a non-null assertion (`!`) instead.", expectedOutput: "For input \"hello\", logs: HELLO. For a non-string input, the Error is thrown before any log happens.", check: "Confirm that after calling assertIsString(data), TypeScript narrows data to string for the rest of the enclosing scope, allowing data.toUpperCase() to compile without a cast." },
  { id: 12, level: 3, title: "The Extracted Key Union", scenario: "You have a constant settings object and want a reusable union type of its exact property names, kept in sync automatically as the object changes.", objective: "Given `const settings = { theme: \"dark\", volume: 10, muted: false } as const;`, declare `type SettingsKey = keyof typeof settings;`. Write a function `getSetting(key: SettingsKey)` that returns `settings[key]`, and call it with `\"theme\"`.", constraints: "Do not manually write out the union of key names — SettingsKey must be derived using `keyof typeof settings`.", expectedOutput: "`console.log(getSetting(\"theme\"))` prints: dark", check: "Confirm SettingsKey is exactly \"theme\" | \"volume\" | \"muted\", and that calling getSetting(\"invalidKey\") produces a compile-time error." },
  { id: 13, level: 3, title: "The Narrowed Shape Calculator", scenario: "You are computing the area of different shapes represented as a discriminated union, and want TypeScript to narrow each branch automatically.", objective: "Define `type Shape = { kind: \"circle\"; radius: number } | { kind: \"rectangle\"; width: number; height: number };`. Write `function area(shape: Shape): number` using an `if`/`else` (or switch) on `shape.kind` to compute the correct area for each variant.", constraints: "Do not use type assertions (`as`) anywhere inside area — rely entirely on discriminant narrowing.", expectedOutput: "For a circle with radius 2, logs approximately 12.57. For a rectangle 3x4, logs 12.", check: "Confirm that inside the circle branch, TypeScript narrows shape to only have a radius property (accessing shape.width there should be a compile error), and vice versa for the rectangle branch." },
  { id: 14, level: 3, title: "The Reflected Return Type", scenario: "You want a type alias that always matches the exact return type of an existing function, so future edits to that function automatically keep the type in sync.", objective: "Write `function createUser() { return { id: 1, name: \"Kai\", active: true }; }`. Declare `type User = ReturnType<typeof createUser>;`. Write a second function `printUser(user: User)` that logs the user's id and name, and call it with the result of createUser().", constraints: "Do not manually write out the User type's properties — it must be derived using `ReturnType<typeof createUser>`.", expectedOutput: "`printUser(createUser())` logs: 1 Kai", check: "Confirm that if createUser's returned object shape changes (e.g. adding a new field), User automatically reflects the change with no manual edits needed." },
  { id: 15, level: 3, title: "The Best-Common-Type Merger", scenario: "You are writing a generic helper that merges two values into a tuple, and want to confirm how TypeScript infers a shared type parameter when the two arguments have different types.", objective: "Write `function pair<T>(a: T, b: T): [T, T] { return [a, b]; }`. Call it once with `pair(1, 2)` and once with `pair(1, \"two\")`, logging both results.", constraints: "Do not supply explicit type arguments to pair at either call site.", expectedOutput: "`console.log(pair(1, 2))` prints: [ 1, 2 ]. `console.log(pair(1, \"two\"))` prints: [ 1, 'two' ].", check: "Confirm that pair(1, 2) infers T as number, while pair(1, \"two\") infers T as the union number | string, by checking that the second call's result type allows both element positions to individually hold either a number or a string." },
  { id: 16, level: 4, title: "The Array Element Extractor", scenario: "You are building a small type-utility library and need a reusable conditional type that extracts the element type out of any array type.", objective: "Write `type ElementOf<T> = T extends (infer U)[] ? U : never;`. Declare `type NumEl = ElementOf<number[]>;` and `type StrEl = ElementOf<string[]>;`. Write a function `firstElement<T>(arr: T[]): ElementOf<T[]>` (or equivalent) and call it on a string array, logging the result.", constraints: "Must use the `infer` keyword inside a conditional type — do not hardcode the element type manually.", expectedOutput: "For `firstElement([\"a\", \"b\", \"c\"])`, logs: a", check: "Confirm NumEl resolves to number and StrEl resolves to string by verifying `const x: NumEl = 5;` and `const y: StrEl = \"hi\";` both compile, while `const z: NumEl = \"hi\";` does not." },
  { id: 17, level: 4, title: "The Deeply Flattened Array Type", scenario: "You have arrays of varying nesting depth and want a single conditional type that recursively unwraps them to find the innermost element type.", objective: "Write `type Flatten<T> = T extends Array<infer U> ? Flatten<U> : T;`. Declare `type Deep = Flatten<number[][][]>;` and log a value typed as Deep (e.g. `const n: Deep = 42; console.log(n);`).", constraints: "Flatten must be recursive (calling itself in the true branch) rather than only unwrapping one level.", expectedOutput: "`console.log(n)` prints: 42", check: "Confirm Deep resolves all the way down to number (not number[] or number[][]) regardless of how many array levels are nested, by testing with a few different nesting depths." },
  { id: 18, level: 4, title: "The Overloaded Formatter", scenario: "You are writing a formatting function that behaves differently for strings versus numbers, and want each call site to see the precise, non-union return type.", objective: "Write overload signatures `function format(value: string): string; function format(value: number, digits: number): string;` plus a compatible implementation signature, and two example calls (one with a string, one with a number and digits) each logged.", constraints: "Must declare exactly two overload signatures plus one implementation signature that is compatible with both.", expectedOutput: "For `format(\"hi\")`, logs a string. For `format(3.14159, 2)`, logs \"3.14\".", check: "Confirm that calling format with a string and a stray second argument is a compile error (does not match the string overload), and calling format with just a number (no digits) is also a compile error (does not match the number overload)." },
  { id: 19, level: 4, title: "The Extracted Route Parameter Names", scenario: "You are building type-safe routing and want a utility type that extracts parameter names from a template literal route pattern.", objective: "Write `type ExtractParam<T extends string> = T extends `${string}:${infer Param}/${infer Rest}` ? Param | ExtractParam<Rest> : T extends `${string}:${infer Param}` ? Param : never;`. Declare `type Params = ExtractParam<\"users/:id/posts/:postId\">;` and log a value typed to match Params (e.g. `const p: Params = \"id\"; console.log(p);`).", constraints: "Must use template literal type pattern matching with `infer` — do not hardcode the parameter names.", expectedOutput: "`console.log(p)` prints: id", check: "Confirm Params resolves to the union \"id\" | \"postId\" by verifying both `const a: Params = \"id\";` and `const b: Params = \"postId\";` compile, while `const c: Params = \"userId\";` does not." },
  { id: 20, level: 4, title: "The Deferred-Assignment Service Field", scenario: "A class field is guaranteed to be assigned by an external setup method immediately after construction, but never inside the constructor itself, and you want to avoid unsafe non-null assertions everywhere the field is used.", objective: "Write a class `Service` with `config!: { url: string };` using the definite assignment assertion, a method `init(config: { url: string })` that assigns `this.config = config;`, and a method `getUrl()` that returns `this.config.url`. Demonstrate calling init() before getUrl().", constraints: "Must use the definite assignment assertion (`!`) on the field declaration, and must NOT initialize config directly in the constructor.", expectedOutput: "After `const s = new Service(); s.init({ url: \"https://api.example.com\" }); console.log(s.getUrl());`, logs: https://api.example.com", check: "Confirm that without the `!`, TypeScript would report \"Property config has no initializer\" on the field declaration, and that calling getUrl() before init() would compile but produce undefined at runtime — note this risk in a comment." },
  { id: 21, level: 5, title: "The Distributive Wrapper Type", scenario: "You are building a type utility that wraps each member of a union type individually in an array, rather than producing one array of the whole union.", objective: "Write `type ToArray<T> = T extends unknown ? T[] : never;`. Declare `type Result = ToArray<string | number>;`. Write a function that accepts a value of type Result and logs it, calling it once with a string array and once with a number array.", constraints: "The conditional type must be written so it DISTRIBUTES over the union (a naked type parameter check), producing `string[] | number[]`, not `(string | number)[]`.", expectedOutput: "Logging `[\"a\", \"b\"]` and `[1, 2]` both succeed as valid Result values.", check: "Confirm Result is exactly `string[] | number[]` (not `(string | number)[]`) by verifying that a mixed array like `[\"a\", 1]` is NOT assignable to Result, while a homogeneous string[] or number[] is." },
  { id: 22, level: 5, title: "The Function Parameter Tuple Extractor", scenario: "You are writing a generic `bind`-like helper and need a utility type that captures a function's full parameter list as a tuple, for later reuse.", objective: "Write `type ParamsOf<Fn> = Fn extends (...args: infer P) => unknown ? P : never;`. Given `function greet(name: string, times: number): void {}`, declare `type GreetParams = ParamsOf<typeof greet>;`. Write a function `callGreet(...args: GreetParams)` that spreads args into a call to greet, and invoke it.", constraints: "Must use `infer` to capture the parameter tuple — do not hardcode `[string, number]` directly.", expectedOutput: "`callGreet(\"Kai\", 3)` behaves identically to calling `greet(\"Kai\", 3)` directly, with no compile errors.", check: "Confirm GreetParams resolves to exactly [string, number] by verifying `callGreet(\"Kai\")` (missing the second argument) is a compile error, and `callGreet(1, 2)` (wrong types) is also a compile error." },
  { id: 23, level: 5, title: "The Type-Safe Event Emitter", scenario: "You are building a small strongly-typed event emitter where each event name maps to a specific payload type, and listener callbacks must be checked against the correct payload automatically.", objective: "Given `interface EventMap { login: { userId: number }; logout: undefined; }`, write a generic class `TypedEmitter<T extends Record<string, unknown>>` with an `on<K extends keyof T>(event: K, handler: (payload: T[K]) => void): void` method (implementation can be a simple stored-handler map). Instantiate `new TypedEmitter<EventMap>()` and register a \"login\" handler that logs `payload.userId`.", constraints: "The on method's handler parameter type must be inferred from the specific event key K via `T[K]`, not typed as `any` or `unknown`.", expectedOutput: "Registering and manually invoking the \"login\" handler with `{ userId: 42 }` logs: 42", check: "Confirm that registering a handler for \"login\" gives the handler parameter the inferred type `{ userId: number }` (accessing payload.userId compiles), while registering for \"logout\" gives the handler parameter type undefined, and registering for a non-existent event key is a compile error." },
  { id: 24, level: 5, title: "The Recursive Deep-Readonly Config", scenario: "You are finalizing an application configuration object and want a reusable mapped type that makes every property readonly at every nesting level, not just the top level.", objective: "Write `type DeepReadonly<T> = T extends object ? { readonly [K in keyof T]: DeepReadonly<T[K]> } : T;`. Given a nested config object with at least two levels of nesting, declare its type using `DeepReadonly<typeof rawConfig>` and log a deeply nested property.", constraints: "DeepReadonly must recurse into nested object properties, not just mark the top-level properties readonly.", expectedOutput: "Logging a nested property (e.g. `config.server.port`) succeeds and prints its value.", check: "Confirm that attempting to reassign a NESTED property (e.g. `config.server.port = 9999;`), not just a top-level one, is a compile-time error thanks to the recursive readonly modifiers." },
  { id: 25, level: 5, title: "The Signature-Preserving Memoizer", scenario: "You are writing a generic `memoize` higher-order function that must preserve the exact parameter and return types of whatever function is passed into it, with no loss of type information.", objective: "Write `function memoize<Fn extends (...args: any[]) => any>(fn: Fn): Fn` that internally caches results in a Map keyed by `JSON.stringify(args)` and returns a wrapped function with the SAME signature as fn (a type assertion inside the implementation is acceptable, but the public signature must be exact). Apply it to a `square(n: number): number` function and call the memoized version twice with the same argument.", constraints: "The memoized function returned to callers must have exactly the same parameter and return types as the original — callers should get full type-checking and autocomplete as if calling the original function directly.", expectedOutput: "Calling `memoizedSquare(4)` twice logs a \"computing\" message only once, followed by 16 both times.", check: "Confirm that `memoizedSquare` has the inferred type `(n: number) => number` (not `(...args: any[]) => any`), so that calling it with a string argument or using its result as a string is a compile-time error." },
],
modules: [
  { id: 1, level: 1, title: "The Math Helper Module", scenario: "You are splitting a growing script into smaller files, starting with a couple of pure math helper functions.", objective: "In a file `mathHelpers.ts`, declare and export two named functions: `export function add(a: number, b: number) { return a + b; }` and `export function multiply(a: number, b: number) { return a * b; }`. In `main.ts`, import both by name and log the results of `add(2, 3)` and `multiply(2, 3)`.", constraints: "Both functions must be named exports (no default export). The import in main.ts must use curly braces.", expectedOutput: "`console.log(add(2, 3), multiply(2, 3))` prints: 5 6", check: "Verify that importing a third, non-existent function name (e.g. subtract) from mathHelpers produces a compile-time \"has no exported member\" error." },
  { id: 2, level: 1, title: "The Single Logger Export", scenario: "A small app needs one primary logging utility that other files will import under whatever local name they prefer.", objective: "In `logger.ts`, define a function `function log(message: string) { console.log(`[LOG] ${message}`); }` and export it as the module's default export. In `main.ts`, import it (naming it anything you like, e.g. `log`) and call it with \"App started\".", constraints: "logger.ts must have exactly one export, using `export default`. Do not use named export syntax for it.", expectedOutput: "`log(\"App started\")` prints: [LOG] App started", check: "Verify that the import in main.ts does not use curly braces, and that renaming the imported binding to a different local name (e.g. `import print from \"./logger\"`) still works correctly." },
  { id: 3, level: 1, title: "The Renamed Currency Formatter", scenario: "A shared formatting module exports a function whose internal name clashes with a name you already use in main.ts.", objective: "In `format.ts`, export `export function format(n: number) { return `$${n.toFixed(2)}`; }`. In `main.ts`, import it while renaming it to `formatPrice` using the `as` keyword, and log `formatPrice(9.5)`.", constraints: "The import statement must use `import { format as formatPrice } from \"./format\";` — do not rename the original export in format.ts itself.", expectedOutput: "`console.log(formatPrice(9.5))` prints: $9.50", check: "Verify that using the original name `format` directly in main.ts (without importing it separately) produces a \"Cannot find name\" error, confirming the rename fully replaced the local binding name." },
  { id: 4, level: 1, title: "The Side-Effect Polyfill Import", scenario: "Your project relies on a small setup file that patches a global object but exports no values that any other file needs to use directly.", objective: "In `setup.ts`, write `console.log(\"Setup ran\");` with NO import or export statements related to any binding (add just `export {};` if needed to make it a module). In `main.ts`, import setup.ts purely for its side effect using `import \"./setup\";`, then log \"Main running\".", constraints: "The import in main.ts must not bind any name (no `import x from` or `import { x } from`).", expectedOutput: "Running main.ts logs: Setup ran, then Main running (in that order).", check: "Confirm that \"Setup ran\" appears before \"Main running\" in the output, since the imported module executes fully before the rest of main.ts continues." },
  { id: 5, level: 1, title: "The Combined Default and Named Export", scenario: "A validation module has one primary validator function plus a couple of smaller named helper exports used less often.", objective: "In `validate.ts`, export a default function `function isValidEmail(s: string) { return s.includes(\"@\"); }` AND a named export `export const MIN_PASSWORD_LENGTH = 8;`. In `main.ts`, import both in a single import statement and log both `isValidEmail(\"a@b.com\")` and `MIN_PASSWORD_LENGTH`.", constraints: "Must use one combined import statement of the form `import Default, { Named } from \"./module\"`, not two separate import statements.", expectedOutput: "`console.log(isValidEmail(\"a@b.com\"), MIN_PASSWORD_LENGTH)` prints: true 8", check: "Verify validate.ts compiles with exactly one default export and one named export, and that the combined import syntax in main.ts correctly resolves both." },
  { id: 6, level: 2, title: "The Namespace Import Aggregator", scenario: "A shapes module exports several standalone area functions, and a consumer wants to access all of them through one grouped object rather than several separate imports.", objective: "In `shapes.ts`, export named functions `circleArea(r: number)` and `squareArea(s: number)`. In `main.ts`, import everything as a single namespace using `import * as Shapes from \"./shapes\";`, then log `Shapes.circleArea(2)` and `Shapes.squareArea(3)`.", constraints: "main.ts must use exactly one `import * as Shapes` statement — no separate named imports.", expectedOutput: "Logs approximately: 12.57 9", check: "Verify that Shapes.circleArea and Shapes.squareArea are both accessible as properties of the single Shapes object, and that a typo like Shapes.circelArea produces a compile-time error." },
  { id: 7, level: 2, title: "The Barrel File Entry Point", scenario: "You have three small related modules (colors, shapes, sizes) and want consumers to import everything from a single, short entry-point path.", objective: "Create `colors.ts`, `shapes.ts`, and `sizes.ts`, each exporting at least one named constant or function. Create `index.ts` that re-exports everything from all three using `export * from \"./colors\";` (and similarly for the others). In `main.ts`, import several of the re-exported names directly from `./index`.", constraints: "main.ts must import from `./index` only — it must not import directly from colors.ts, shapes.ts, or sizes.ts.", expectedOutput: "Logging any of the re-exported values from main.ts succeeds using only the barrel import path.", check: "Verify that all three source modules' exports are accessible via `./index`, and that none of their export NAMES collide with each other (which would cause an ambiguity error)." },
  { id: 8, level: 2, title: "The Lazy-Loaded Report Generator", scenario: "A reporting feature uses a large formatting library that should only be loaded when the user actually requests a report, to keep the initial page load light.", objective: "In `reportFormatter.ts`, export a function `formatReport(data: string[]) { return data.join(\", \"); }`. In `main.ts`, write an async function `generateReport(data: string[])` that uses `const { formatReport } = await import(\"./reportFormatter\");` and logs the result, calling it only when a simulated \"user requested report\" condition is true.", constraints: "Must use dynamic `import()` inside the async function, not a static top-level import.", expectedOutput: "Calling `await generateReport([\"a\", \"b\", \"c\"])` logs: a, b, c", check: "Verify that reportFormatter.ts is never imported at the top of main.ts, and that the dynamic import expression's type resolves to a Promise that must be awaited before formatReport is accessible." },
  { id: 9, level: 2, title: "The Type-Only Interface Import", scenario: "A types file defines a shared User interface, and a consuming file only ever uses it for type annotations, never as a runtime value.", objective: "In `types.ts`, define and export `export interface User { id: number; name: string; }`. In `main.ts`, import it using `import type { User } from \"./types\";` and write a function `printUser(user: User)` that logs `user.name`.", constraints: "Must use `import type`, not a plain `import { User }`.", expectedOutput: "`printUser({ id: 1, name: \"Kai\" })` logs: Kai", check: "Verify that the User import produces zero runtime code in the compiled JavaScript output (inspect the compiled .js if possible) — only the import type line and its usages should have no runtime trace." },
  { id: 10, level: 2, title: "The Config JSON Loader", scenario: "An app reads a small configuration file written in JSON and wants full compile-time typing for its structure rather than treating it as untyped data.", objective: "Create `config.json` with content like `{ \"appName\": \"MyApp\", \"maxRetries\": 3 }`. Enable `resolveJsonModule` (note this in a comment since you cannot edit the actual tsconfig here). In `main.ts`, write `import config from \"./config.json\";` and log `config.appName` and `config.maxRetries`.", constraints: "Must import the JSON file directly (no manual `fs.readFileSync` + `JSON.parse`).", expectedOutput: "`console.log(config.appName, config.maxRetries)` prints: MyApp 3", check: "Verify that TypeScript infers config's shape directly from the JSON file's structure, so `config.appName` is typed as string and `config.maxRetries` as number, with no manual type annotation needed." },
  { id: 11, level: 3, title: "The Merged Namespace Helper", scenario: "You are modeling a Color type that also needs a few well-known preset values attached to it, similar to static members on a class.", objective: "Declare `interface Color { r: number; g: number; b: number; }` and a `namespace Color { export const RED: Color = { r: 255, g: 0, b: 0 }; export const BLACK: Color = { r: 0, g: 0, b: 0 }; }` merged together. Write a function `describe(c: Color)` that logs its r/g/b values, and call it with `Color.RED`.", constraints: "Must use declaration merging between an interface and a namespace sharing the exact same name, Color.", expectedOutput: "`describe(Color.RED)` logs: 255 0 0", check: "Verify that Color can be used BOTH as a type annotation (function describe(c: Color)) and as a value container (Color.RED, Color.BLACK) thanks to the merge." },
  { id: 12, level: 3, title: "The Augmented Express Request", scenario: "You are adding authentication middleware to an Express-style app and need a custom `user` property recognized on the framework's Request type throughout your codebase.", objective: "In a file `express-augment.d.ts`, write `import \"express\"; declare module \"express\" { interface Request { user?: { id: number }; } }` (adjust the import if using a different mock module name). In a regular .ts file, write a function `getUserId(req: { user?: { id: number } })` that safely reads `req.user?.id`, simulating the augmented shape.", constraints: "The augmentation file must import the target module before the `declare module` block. Do not modify any real node_modules files.", expectedOutput: "Calling getUserId with `{ user: { id: 7 } }` logs: 7. Calling it with `{}` logs: undefined.", check: "Verify the .d.ts file is included in your compilation and correctly demonstrates augmenting an existing module's interface rather than creating a brand-new, disconnected one." },
  { id: 13, level: 3, title: "The Ambient SVG Module", scenario: "A frontend project imports .svg files as URL strings (as most bundlers do), but TypeScript has no idea what shape those imports should have.", objective: "In `svg.d.ts`, write `declare module \"*.svg\" { const src: string; export default src; }`. In a regular .ts file, simulate `import logo from \"./logo.svg\";` (the actual file need not exist for this exercise) and write a function that logs the imported value's type by annotating a variable `const url: string = logo;`.", constraints: "Must use a wildcard pattern (`*.svg`) in the ambient module declaration, not a specific filename.", expectedOutput: "The code compiles cleanly, confirming logo is typed as string thanks to the wildcard declaration.", check: "Verify the wildcard declaration file is included in your tsconfig's compiled file set, and that importing any file ending in .svg resolves to a default export typed as string." },
  { id: 14, level: 3, title: "The CommonJS-Compatible Export", scenario: "You are writing a small utility module intended to closely mirror a CommonJS package's single-exports-object style, for consumers still using require().", objective: "In `mathUtils.ts`, write `namespace MathUtils { export function add(a: number, b: number) { return a + b; } } export = MathUtils;`. In a consuming file, import it using `import MathUtils = require(\"./mathUtils\");` and log `MathUtils.add(2, 3)`.", constraints: "Must use `export =` in mathUtils.ts and the matching `import ... = require(...)` syntax in the consumer — not standard ES import/export.", expectedOutput: "`console.log(MathUtils.add(2, 3))` prints: 5", check: "Verify that attempting to also add a regular `export const version = \"1.0\";` alongside `export =` in the same file produces a compile error, since the two export styles cannot be mixed." },
  { id: 15, level: 3, title: "The Exhaustive Action Dispatcher", scenario: "You are writing a small reducer-style dispatcher for a discriminated union of action types, spread appropriately across a couple of files for organization.", objective: "In `actions.ts`, export `export type Action = { type: \"increment\"; amount: number } | { type: \"reset\" };`. In `reducer.ts`, import the type with `import type { Action } from \"./actions\";` and write `function reduce(state: number, action: Action): number` using a switch statement covering both variants, with a `default` case assigning to a `never`-typed variable for exhaustiveness.", constraints: "Must import Action using `import type`. The switch must include the never-based exhaustiveness check in its default case.", expectedOutput: "For `reduce(5, { type: \"increment\", amount: 3 })`, returns 8. For `reduce(5, { type: \"reset\" })`, returns 0.", check: "Verify that adding a new Action variant (e.g. `{ type: \"decrement\"; amount: number }`) to actions.ts without updating the switch in reducer.ts causes a compile error at the never-typed exhaustiveness check." },
  { id: 16, level: 4, title: "The Isolated-Modules-Safe Re-export", scenario: "Your build pipeline transpiles files independently (simulating isolatedModules/verbatimModuleSyntax), and a barrel file needs to re-export both a type and a value from the same source module without ambiguity.", objective: "In `api.ts`, export `export interface ApiResponse { ok: boolean; }` and `export function fetchData(): ApiResponse { return { ok: true }; }`. In `index.ts`, re-export both using `export type { ApiResponse } from \"./api\"; export { fetchData } from \"./api\";` as two separate statements.", constraints: "The type-only member must be re-exported using `export type { ... } from`, kept separate from the value re-export.", expectedOutput: "A consumer importing both `ApiResponse` (as a type) and `fetchData` (as a value) from `./index` compiles and runs correctly, with `fetchData()` returning `{ ok: true }`.", check: "Verify that combining both into a single ambiguous `export { ApiResponse, fetchData } from \"./api\";` without the type marker would be flagged as unsafe or ambiguous under isolatedModules-style settings." },
  { id: 17, level: 4, title: "The Global Window Augmentation", scenario: "Your app needs to read a custom global variable, `window.appBuildVersion`, that is injected by your build process, and you want it fully type-checked wherever it is accessed.", objective: "In `global.d.ts`, write `declare global { interface Window { appBuildVersion: string; } } export {};`. In a regular .ts file, write a function `logBuildVersion()` that logs `window.appBuildVersion` (simulate the global by casting or mocking `window` if running outside a browser environment).", constraints: "The declaration file must include the trailing `export {};` to be treated as a module, and must use `declare global` rather than a bare top-level interface.", expectedOutput: "Setting `(globalThis as any).window = { appBuildVersion: \"1.2.3\" };` then calling logBuildVersion() logs: 1.2.3", check: "Verify that removing the `export {};` line (making the file a global script) still technically works for a script-mode file, but confirm that in module-mode files elsewhere in the project, only `declare global` correctly reaches actual global augmentation rather than creating a shadowing local interface." },
  { id: 18, level: 4, title: "The Dual-Format Package Entry", scenario: "You are preparing a small internal package to be consumed by both modern ESM projects and older CommonJS projects.", objective: "Write two small parallel build outputs conceptually: `dist/esm/index.js` (using `export` syntax) and `dist/cjs/index.js` (using `module.exports`), both exporting a function `greet()`. In a `package.json`, add `\"exports\": { \"import\": \"./dist/esm/index.js\", \"require\": \"./dist/cjs/index.js\" }`. Document (in a comment) which file Node.js would resolve to for `import` versus `require`.", constraints: "The package.json conditional exports field must include both an \"import\" and a \"require\" condition pointing to the respective builds.", expectedOutput: "An ESM consumer resolves to dist/esm/index.js; a CommonJS consumer resolves to dist/cjs/index.js — both ultimately expose an equivalent greet() function.", check: "Verify (via documentation/comment) that you understand the \"dual package hazard\" risk if both builds are simultaneously loaded in the same dependency graph, especially for any shared module-level state." },
  { id: 19, level: 4, title: "The Composite Project Reference Setup", scenario: "A small monorepo has a `shared` package used by an `app` package, and full rebuilds have become slow as the shared package grows.", objective: "Create `shared/tsconfig.json` with `{ \"compilerOptions\": { \"composite\": true, \"declaration\": true, \"outDir\": \"./dist\" } }`, and a small exported function in `shared/src/index.ts`. Create `app/tsconfig.json` with `{ \"references\": [{ \"path\": \"../shared\" }] }`, and have app/src/index.ts import from the shared package.", constraints: "shared's tsconfig must have both `composite: true` and `declaration: true` (composite requires declaration output).", expectedOutput: "Running the TypeScript compiler with project references (`tsc -b`) builds shared once and lets app consume its emitted declaration files.", check: "Verify that setting shared's `declaration` to false while keeping `composite: true` produces a configuration error, since composite projects require declaration output." },
  { id: 20, level: 4, title: "The Extensible Route Meta", scenario: "You are adding a `requiresAuth` flag to a routing library's route metadata type, without modifying the library's own source files.", objective: "Simulate a small \"router\" module exporting `export interface RouteMeta { title?: string; }`. In a separate augmentation file, write `import \"./router\"; declare module \"./router\" { interface RouteMeta { requiresAuth?: boolean; } }`. In a consuming file, create an object typed as `RouteMeta` that includes both `title` and `requiresAuth`.", constraints: "Must use module augmentation (declare module) targeting the router module's existing RouteMeta interface, not a brand-new type.", expectedOutput: "A RouteMeta value like `{ title: \"Home\", requiresAuth: true }` type-checks successfully and both properties are accessible.", check: "Verify that omitting the `import \"./router\";` line before the declare module block risks TypeScript treating it as an unrelated, disconnected module declaration rather than a true augmentation." },
  { id: 21, level: 5, title: "The Node16-Ready Relative Imports", scenario: "You are preparing a small library to be compiled with `\"moduleResolution\": \"node16\"` and published as a native ESM package for Node.js.", objective: "Create at least two files, `utils.ts` and `main.ts`, where main.ts imports from utils.ts. Update the relative import in main.ts to include the `.js` extension (matching the eventual compiled output), e.g. `import { helper } from \"./utils.js\";`, even though the source file is `utils.ts`.", constraints: "The import specifier must include the `.js` extension, not `.ts` and not no extension at all.", expectedOutput: "The project compiles cleanly under node16/nodenext module resolution, and the compiled output resolves correctly at runtime under Node.js.", check: "Verify that omitting the extension (or using `.ts`) produces a resolution error specifically under node16/nodenext settings, even though the same import would work fine under classic/bundler resolution." },
  { id: 22, level: 5, title: "The Metadata-Free Serialization Registry", scenario: "You want a lightweight way to register which module provides which named export, without relying on runtime reflection, purely to help enforce clean module boundaries during a refactor.", objective: "Build a small barrel structure with three feature modules (`userFeature.ts`, `orderFeature.ts`, `paymentFeature.ts`), each exporting a distinctly named function. Create `features/index.ts` re-exporting all three with explicit renaming to avoid any possible naming collisions (e.g. `export { run as runUserFeature } from \"./userFeature\";`).", constraints: "Every re-export must be explicitly renamed via `as` in the barrel file, even if the original names do not currently collide, to future-proof against later collisions.", expectedOutput: "Importing runUserFeature, runOrderFeature, and runPaymentFeature all from `./features/index` and calling each logs their respective feature's output with no ambiguity errors.", check: "Verify that if two of the underlying feature modules were later given the same export name, the explicit renaming in the barrel file would prevent an export-star ambiguity error that a bare `export * from` would trigger." },
  { id: 23, level: 5, title: "The UMD-Compatible Utility Library", scenario: "You are writing type declarations for a small utility library that can be used either via a `<script>` tag (as a global variable) or via `import` in a bundler-based project.", objective: "Write a `.d.ts` file declaring `declare function miniUtil(value: unknown): string; export = miniUtil; export as namespace MiniUtil;`. In one comment, show how a script-tag consumer would use `MiniUtil(someValue)`, and in another, how a module consumer would use `import miniUtil = require(\"mini-util\"); miniUtil(someValue);`.", constraints: "Must use `export =` combined with `export as namespace` in the same declaration file.", expectedOutput: "Both usage styles (global script-tag access via MiniUtil, and module-based access via import ... = require) are documented and correctly typed by the single declaration file.", check: "Verify that `export as namespace` is only used alongside `export =` (not with standard named/default exports), matching the UMD declaration pattern." },
  { id: 24, level: 5, title: "The Verbatim-Safe Mixed Re-export", scenario: "Under a strict `verbatimModuleSyntax` setting, a shared module exports both a type and a value under related names, and a barrel file needs to re-export both without triggering an ambiguity error.", objective: "In `models.ts`, export `export interface Product { id: number; price: number; }` and `export function createProduct(id: number, price: number): Product { return { id, price }; }`. In `index.ts`, write two explicit re-export statements: one marked `export type { Product } from \"./models\";` and one plain `export { createProduct } from \"./models\";`.", constraints: "Do NOT combine the type and value in a single unmarked `export { Product, createProduct } from \"./models\";` statement — they must be split as shown.", expectedOutput: "A consumer importing both Product (as a type annotation) and createProduct (as a runtime function) from `./index` compiles and runs correctly.", check: "Verify that under verbatimModuleSyntax, combining Product and createProduct into one unmarked re-export statement would be rejected since the compiler can no longer silently infer which parts are type-only." },
  { id: 25, level: 5, title: "The Independently-Rebuildable Monorepo Slice", scenario: "You are restructuring a slow-building monorepo so that a `core` package, a `features` package (depending on core), and an `app` package (depending on features) each build independently and incrementally.", objective: "Set up three composite TypeScript projects (`core`, `features`, `app`), each with its own `tsconfig.json` using `composite: true` and `declaration: true`. Wire up `references` so `features` references `core`, and `app` references `features`. Add one small exported function per package that the next package up imports and uses.", constraints: "Each package must be independently composite (not one giant shared tsconfig), and dependencies must be expressed via `references`, not just relative imports alone.", expectedOutput: "Running `tsc -b` on the app package builds core and features first (if changed), reusing their declaration output, and the app compiles and runs correctly using values imported from features (which in turn uses core).", check: "Verify that after an unrelated change to only the app package's source, an incremental `tsc -b` build does NOT recompile core or features, confirming the project references setup is correctly skipping unchanged dependencies." },
],
decorators: [
  { id: 1, level: 1, title: "The Class Definition Announcer", scenario: "You want every important class in a small app to announce itself in the console as soon as it is defined, for basic startup diagnostics.", objective: "Write a class decorator `function announce(value: Function, context: ClassDecoratorContext) { console.log(`Defining class: ${String(context.name)}`); }`. Apply it with `@announce` to a class `Widget {}` and log a message right after the class declaration.", constraints: "Do not call `new Widget()` anywhere — the announcement must come purely from the decorator itself.", expectedOutput: "Logs: Defining class: Widget, followed by your own message, in that order.", check: "Verify the announcement appears even though no instance of Widget is ever created, confirming the decorator runs at class-definition time." },
  { id: 2, level: 1, title: "The Method Call Logger", scenario: "You want to see a console message every time a specific method is called, without adding a console.log line inside the method itself.", objective: "Write a method decorator `function logCall(value: Function, context: ClassMethodDecoratorContext) { return function (this: unknown, ...args: unknown[]) { console.log(`Calling ${String(context.name)}`); return value.apply(this, args); }; }`. Apply it to a `greet(name: string)` method on a class `Greeter`, and call `new Greeter().greet(\"Kai\")`.", constraints: "The greet method's own body must not contain any console.log calls — only the decorator should log.", expectedOutput: "Logs: Calling greet, followed by whatever greet itself returns/logs (e.g. via a separate console.log of the call result).", check: "Verify that removing the @logCall decorator (as a quick test) stops the \"Calling greet\" message from appearing, confirming the logging comes from the decorator, not the method." },
  { id: 3, level: 1, title: "The Configurable Prefix Logger", scenario: "You want a reusable logging decorator where the log prefix can be customized per method, rather than being hardcoded.", objective: "Write a decorator FACTORY `function withPrefix(prefix: string) { return function (value: Function, context: ClassMethodDecoratorContext) { return function (this: unknown, ...args: unknown[]) { console.log(prefix); return value.apply(this, args); }; }; }`. Apply it as `@withPrefix(\"[INFO]\")` to one method and `@withPrefix(\"[DEBUG]\")` to a different method in the same class.", constraints: "Must call the factory with parentheses and a string argument at each usage site — do not apply it as a bare `@withPrefix` without arguments.", expectedOutput: "Calling the first method logs \"[INFO]\" before its own behavior; calling the second logs \"[DEBUG]\" before its own behavior.", check: "Verify that each decorated method logs its own distinct configured prefix, confirming the factory correctly captures a different `prefix` value per application." },
  { id: 4, level: 1, title: "The Sealed Configuration Class", scenario: "You want a configuration class to be locked down against accidental new properties being added at runtime, immediately upon definition.", objective: "Write a class decorator `function sealed(value: Function, context: ClassDecoratorContext) { Object.seal(value); Object.seal(value.prototype); }`. Apply it to a class `AppConfig { ready = true; }` with `@sealed`. Attempt (in a comment or try/catch) to add a new property like `(AppConfig.prototype as any).extra = 1;` and observe the result.", constraints: "Must use `Object.seal` on both the class itself and its prototype inside the decorator.", expectedOutput: "Attempting to add a new property to the sealed prototype silently fails (or throws in strict mode) rather than succeeding.", check: "Verify that existing properties (like `ready`) can still be read/modified after sealing, while genuinely NEW properties cannot be added — confirming seal restricts additions, not existing property mutation." },
  { id: 5, level: 1, title: "The No-Op Decorator Placeholder", scenario: "You are scaffolding a new class and want to confirm you understand exactly what a decorator that changes nothing looks like, before writing more complex ones.", objective: "Write a method decorator `function noop(value: Function, context: ClassMethodDecoratorContext) { console.log(\"decorator applied, no changes\"); }` that returns nothing (no return statement). Apply it to a method `greet()` on a class, and confirm calling `greet()` behaves exactly as if undecorated.", constraints: "The decorator must not return any value — it should rely on returning undefined to leave the method unchanged.", expectedOutput: "Logs \"decorator applied, no changes\" once at class definition, then greet() behaves completely normally when called.", check: "Verify that greet's behavior (its return value and any side effects) is identical to what it would be with no decorator at all, confirming that returning undefined means \"keep the original.\"" },
  { id: 6, level: 2, title: "The Auto-Bound Event Handler", scenario: "A class method will be passed around as a bare callback (e.g. attached to an event), and you need it to always use the correct `this`, even when detached from the instance.", objective: "Write a method decorator `function bind(value: Function, context: ClassMethodDecoratorContext) { context.addInitializer(function (this: any) { this[context.name] = this[context.name].bind(this); }); }`. Apply it to a `handleClick()` method on a class `Button` that references `this` internally, and demonstrate calling it both attached (`btn.handleClick()`) and detached (`const fn = btn.handleClick; fn();`).", constraints: "Must use `context.addInitializer` — do not manually call `.bind(this)` in the constructor instead.", expectedOutput: "Both the attached call and the detached call produce identical, correct output referencing the same instance.", check: "Verify that WITHOUT the @bind decorator, the detached call (`fn()`) would either throw or behave incorrectly due to a lost `this`, confirming the decorator is what fixes it." },
  { id: 7, level: 2, title: "The Per-Argument Result Cache", scenario: "An expensive computation method is being called repeatedly with the same arguments, and you want to avoid recomputing when the inputs have not changed.", objective: "Write a method decorator `memoize` that caches results in a `Map<string, unknown>` keyed by `JSON.stringify(args)`, logging \"computing\" only on a cache miss. Apply it to a `square(n: number)` method on a class `Calculator`, and call `square(4)` twice in a row.", constraints: "The cache must be created once, at decoration time (inside the decorator function, not inside the returned wrapper), as a basic first version.", expectedOutput: "The first `square(4)` call logs \"computing\" then returns 16; the second call returns 16 with no \"computing\" log.", check: "In a follow-up comment, note the caveat that this basic cache is SHARED across all instances of Calculator (since it lives in the decorator's closure) — describe what would need to change for a true per-instance cache." },
  { id: 8, level: 2, title: "The Validated Deposit Method", scenario: "A banking class's deposit method should reject negative amounts before ever running its real logic, and you want this validation as a reusable decorator rather than duplicated in every similar method.", objective: "Write a method decorator `withValidation` that wraps the original method to throw an Error (\"Amount must be non-negative\") if the first argument is a negative number, otherwise delegating to the original. Apply it to a `deposit(amount: number)` method on a class `Account`, and demonstrate both a valid and an invalid call using try/catch.", constraints: "The validation logic must live entirely inside the decorator's wrapper function, not inside deposit itself.", expectedOutput: "`deposit(50)` succeeds and logs a success message; `deposit(-10)` throws, and the catch block logs the error message.", check: "Verify that removing @withValidation from deposit would allow a negative amount through unchecked, confirming the validation is entirely decorator-provided." },
  { id: 9, level: 2, title: "The Doubling Field Transformer", scenario: "A class field representing a quantity should always be stored as double whatever value is initially provided, to account for a \"buy one get one\" promotion baked into the data model.", objective: "Write a field decorator `function double(value: undefined, context: ClassFieldDecoratorContext) { return function (initialValue: number) { return initialValue * 2; }; }`. Apply it to a field `quantity = 3;` on a class `PromoItem`, and log a new instance's `quantity`.", constraints: "The decorator must return an initializer FUNCTION, not attempt to transform `value` directly (which is always undefined for field decorators).", expectedOutput: "`console.log(new PromoItem().quantity)` prints: 6", check: "Verify that changing the field's initial value (e.g. to `quantity = 5;`) automatically produces a doubled result (10) with no changes needed to the decorator itself." },
  { id: 10, level: 2, title: "The Static Member Detector", scenario: "You are writing a diagnostic decorator that behaves differently depending on whether it is applied to a static or an instance method, and need to correctly detect which one it is.", objective: "Write a method decorator `function describe(value: Function, context: ClassMethodDecoratorContext) { console.log(context.static ? \"static member\" : \"instance member\"); return value; }`. Apply it to both a static method and an instance method on the same class, `Utils`.", constraints: "Must use `context.static` (not a manual workaround) to distinguish the two cases.", expectedOutput: "Logs \"static member\" for the static method's decoration and \"instance member\" for the instance method's decoration, both at class-definition time.", check: "Verify both log messages appear once, at class definition, regardless of whether the static or instance method is ever actually called afterward." },
  { id: 11, level: 3, title: "The Range-Clamping Accessor", scenario: "A volume control class needs its `level` property to always stay within 0–100, no matter what value is assigned to it, including the very first default value.", objective: "Write an accessor decorator factory `function clamp(min: number, max: number)` returning a decorator that provides both a `set` (clamping subsequent assignments) and an `init` (clamping the initial value) function. Apply it as `@clamp(0, 100)` to `accessor level = 150;` on a class `Volume`, and demonstrate both the clamped initial value and a clamped later assignment.", constraints: "Must use the `accessor` keyword (not a plain field) and cover BOTH `init` and `set` in the decorator's returned object.", expectedOutput: "A new Volume instance starts with level 100 (clamped from 150); assigning `v.level = -20;` afterward results in `v.level` reading 0.", check: "Verify that removing the `init` function (leaving only `set`) would let the out-of-range initial value 150 slip through uncorrected, demonstrating why both hooks are needed." },
  { id: 12, level: 3, title: "The Shared Class Metadata Tracker", scenario: "You are building a lightweight tagging system where several field decorators on the same class need to contribute to one shared list of \"tracked\" field names, readable afterward from outside any decorator.", objective: "Write a field decorator `function tracked(value: undefined, context: ClassFieldDecoratorContext) { (context.metadata.fields ??= []); (context.metadata.fields as string[]).push(String(context.name)); return (v: unknown) => v; }`. Apply it to two or more fields on a class `Model`, and afterward log `(Model[Symbol.metadata] as any).fields`.", constraints: "Must write to `context.metadata` directly (a shared object), not a private local variable inside the decorator.", expectedOutput: "Logs an array containing the names of every field the decorator was applied to, in declaration order.", check: "Verify that if you instead wrote to a fresh local object inside each decorator call, `Model[Symbol.metadata]` would NOT show the accumulated field names — confirming the importance of using the shared context.metadata object." },
  { id: 13, level: 3, title: "The Extending Class Decorator", scenario: "You want to add an auto-generated unique `id` field to several otherwise-unrelated classes, without duplicating the field declaration in each one.", objective: "Write a class decorator `function withId<T extends new (...args: any[]) => any>(value: T, context: ClassDecoratorContext) { return class extends value { id = crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36); }; }`. Apply `@withId` to two different classes and log each instance's `id` (cast as needed for TypeScript, e.g. `as any`).", constraints: "Must return a new class extending the original from inside the decorator, rather than mutating `value.prototype` directly.", expectedOutput: "Each new instance from either decorated class has a distinct, auto-generated id property, alongside all of its own original fields.", check: "Verify that the original fields of each decorated class remain fully intact and functional alongside the newly added id field." },
  { id: 14, level: 3, title: "The Getter/Setter Pair with Independent Decoration", scenario: "A Temperature class exposes a celsius getter and setter, and you want the setter (but not the getter) to enforce a minimum value of absolute zero.", objective: "Write a class `Temperature` with a private `#c` field, a plain `get celsius()` (no decorator), and a `set celsius(v: number)` decorated with a `minValue(-273.15)` decorator factory that throws if the value is below that threshold before delegating to the original setter.", constraints: "Only the setter should be decorated — the getter must remain undecorated and unaffected by the validation logic.", expectedOutput: "Setting `temp.celsius = 20` succeeds; setting `temp.celsius = -300` throws an Error, caught and logged.", check: "Verify that reading `temp.celsius` (via the undecorated getter) works normally regardless of the setter's decoration, confirming getters and setters are decorated independently even when sharing a property name." },
  { id: 15, level: 3, title: "The Structural Validation Decorator", scenario: "You want a class decorator that fails fast (at definition time) if a class does not implement a required method, rather than letting a missing-method bug surface later at an unpredictable call site.", objective: "Write a class decorator factory `function requireMethod(methodName: string)` that throws an Error naming the missing method if `typeof value.prototype[methodName] !== \"function\"`. Apply `@requireMethod(\"save\")` to one class that DOES implement save() (should succeed) and, separately, demonstrate (in a comment or try/catch around a dynamic class definition) what happens when applied to a class that does NOT implement save().", constraints: "The check and thrown error must happen inside the class decorator itself, evaluated at class-definition time.", expectedOutput: "The class implementing save() defines successfully with no error; the one missing save() throws immediately when its class declaration is evaluated, before any instance is ever created.", check: "Verify the error is thrown immediately upon class definition (e.g. by placing a console.log right after the class declaration and observing it never runs for the failing case)." },
  { id: 16, level: 4, title: "The Per-Instance Throttle Guard", scenario: "A button-click handler method should be rate-limited so it cannot run again within a cooldown window, tracked independently for every instance, not shared globally across all instances.", objective: "Write a method decorator factory `function throttle(ms: number)` that uses `context.addInitializer` to attach a per-instance \"last called\" timestamp (e.g. keyed by a unique Symbol on `this`), and have the wrapper skip (logging \"throttled\") if called again too soon. Apply `@throttle(1000)` to an `onClick()` method on a class `Button`, and demonstrate two rapid calls on the SAME instance, plus one call on a DIFFERENT instance.", constraints: "Must use `context.addInitializer` for per-instance state — must NOT use a single shared variable in the decorator's outer closure for the timestamp.", expectedOutput: "The first rapid call on an instance runs normally; the second (too-soon) call on the SAME instance logs \"throttled\"; a call on a DIFFERENT instance runs normally regardless of the first instance's throttle state.", check: "Verify that two different Button instances have completely independent throttle timers, confirming true per-instance (not shared) state." },
  { id: 17, level: 4, title: "The Metadata-Driven Field Serializer", scenario: "You want a generic `toJSON`-style serializer that reads which fields to include and under what external names from decorator metadata, without hardcoding field names anywhere in the serializer itself.", objective: "Write a field decorator factory `function jsonProperty(externalName: string)` that records a mapping (internal field name → externalName) onto `context.metadata`. Apply it to two or more fields on a class `User` with different external names (e.g. `id` mapped to \"user_id\"). Write a generic `serialize(instance: object): Record<string, unknown>` function that reads the mapping from `(instance.constructor as any)[Symbol.metadata]` and builds the renamed output object.", constraints: "The serialize function must be completely generic — it must not reference User, id, or \"user_id\" by name anywhere in its own implementation.", expectedOutput: "Calling `serialize(new User())` produces an object with keys like `user_id` instead of `id`, based purely on the decorator-provided metadata.", check: "Verify that adding a THIRD decorated field to User (with no changes to serialize itself) automatically appears correctly renamed in the serialized output." },
  { id: 18, level: 4, title: "The Fail-Fast Error Wrapper", scenario: "Several parsing methods across your codebase should catch their own errors and return a configurable fallback value instead of throwing, without repeating try/catch boilerplate in every method.", objective: "Write a method decorator factory `function catchErrors(fallback: unknown)` that wraps the original method in a try/catch, logging the caught error's message and returning fallback on failure. Apply `@catchErrors(null)` to a `parse(input: string)` method that throws on empty input, and demonstrate both a successful and a failing call.", constraints: "The try/catch logic must live entirely in the decorator's wrapper — parse itself should just throw normally without any try/catch of its own.", expectedOutput: "Calling parse with valid input returns the parsed result normally; calling it with empty input logs the caught error message and returns null instead of throwing.", check: "Verify that calling the method directly bypassing the decorator (e.g. by testing an undecorated copy of the same logic) DOES throw, confirming the decorator alone provides the error-swallowing behavior." },
  { id: 19, level: 4, title: "The Auto-Registering Instance Tracker", scenario: "For a debugging panel, you want every instance ever created from a particular class to automatically register itself into a shared array, without modifying that class's constructor by hand.", objective: "Write a class decorator `function tracked(value: Function, context: ClassDecoratorContext) { context.addInitializer(function (this: any) { allInstances.push(this); }); }` (with `allInstances` declared as a shared array elsewhere). Apply `@tracked` to a class `Widget`, create three instances, and log `allInstances.length`.", constraints: "Must use the class decorator's `context.addInitializer` — do not manually push to allInstances inside Widget's own constructor.", expectedOutput: "`console.log(allInstances.length)` prints: 3, after creating exactly three Widget instances.", check: "Verify (in a comment) that this differs from code placed directly in the decorator's own body (outside addInitializer), which would run only once, at class-definition time, not once per instance." },
  { id: 20, level: 4, title: "The Generic Type-Constrained Decorator", scenario: "You want a decorator that can only be legally applied to methods whose return type is a string, catching any misuse (like applying it to a number-returning method) at compile time rather than at runtime.", objective: "Write a generic method decorator `function upper<T extends (...args: any[]) => string>(value: T, context: ClassMethodDecoratorContext) { return function (this: unknown, ...args: Parameters<T>): string { return (value.apply(this, args) as string).toUpperCase(); }; }`. Apply it successfully to a method returning a string, and (in a comment) show what compile error would occur if applied to a method returning a number.", constraints: "The generic constraint `T extends (...args: any[]) => string` must be present and doing real work — do not loosen it to `Function` or `any`.", expectedOutput: "Applying @upper to `getName(): string { return \"kai\"; }` and calling it logs: KAI", check: "Verify (by actually trying it, then reverting) that applying @upper to a method with a non-string return type (e.g. `getId(): number { return 1; }`) produces a compile-time type error, not just a runtime surprise." },
  { id: 21, level: 5, title: "The WeakMap-Isolated Memoizer", scenario: "Your earlier shared-cache memoize decorator (Level 2) had a bug: all instances of the decorated class shared one cache. Now you need a corrected version giving each instance its own truly independent cache.", objective: "Rewrite `memoize` to use a `WeakMap<object, Map<string, unknown>>` keyed by the calling instance (`this`), lazily creating each instance's inner Map on first use. Apply it to a `square(n: number)` method on two separate instances of a class `Calculator`, and demonstrate that caching one instance's result does not affect the other's.", constraints: "Must use a `WeakMap` keyed by instance, not a single shared `Map` keyed only by arguments.", expectedOutput: "Calling `a.square(2)` and `b.square(2)` on two different Calculator instances each independently logs \"computing\" once, with their own separate cache entries.", check: "Verify that repeated calls to `a.square(2)` after the first no longer log \"computing\" (cache hit), while the very first `b.square(2)` call still logs \"computing\" despite a already having cached that same argument — proving true per-instance isolation." },
  { id: 22, level: 5, title: "The Subclass-Blocking Final Decorator", scenario: "You are publishing a library class that must never be subclassed by consumers, to preserve certain invariants, but TypeScript/JavaScript has no built-in \"final class\" keyword.", objective: "Write a class decorator `final` that returns `new Proxy(value, { construct(target, args, newTarget) { if (newTarget !== target) throw new Error(`Cannot subclass ${String(context.name)}`); return Reflect.construct(target, args, newTarget); } })`. Apply `@final` to a class `Base {}`, then define `class Sub extends Base {}` and demonstrate (via try/catch) that `new Sub()` throws while `new Base()` succeeds.", constraints: "Must use a Proxy's `construct` trap comparing `newTarget` against the original `target` — do not use `Object.freeze` or a runtime instanceof check instead.", expectedOutput: "`new Base()` succeeds silently; `new Sub()` throws \"Cannot subclass Base\", caught and logged.", check: "Verify that constructing Base directly still works completely normally after decoration, and that only attempts to instantiate a SUBCLASS of it are blocked." },
  { id: 23, level: 5, title: "The Read-Only-After-Init Accessor", scenario: "A configuration property should be freely assignable exactly once (its initial value), but permanently locked against any reassignment afterward.", objective: "Write an accessor decorator `readonlyAfterInit` that tracks a per-instance \"initialized\" flag (e.g. via a WeakSet), allows the FIRST assignment (via `init`) to proceed and mark the flag, but throws on any `set` call once the flag is already set. Apply it to `accessor apiKey = \"initial-key\";` on a class `Config`, and demonstrate that changing apiKey once after construction throws.", constraints: "The decorator must distinguish the initializer-driven first assignment from later reassignments — an unconditionally throwing `set` is not sufficient and will incorrectly break construction itself.", expectedOutput: "A new Config instance reads `apiKey` as \"initial-key\" successfully; attempting `config.apiKey = \"new-key\";` afterward throws, caught and logged.", check: "Verify that construction itself (the very first, implicit assignment of \"initial-key\") does NOT throw, confirming the decorator correctly distinguishes initialization from later mutation." },
  { id: 24, level: 5, title: "The Dependency-Declaring Injectable", scenario: "You are building a minimal dependency-injection container using MODERN decorators, and since parameter decorators and automatic type reflection do not exist in the new model, dependencies must be declared explicitly.", objective: "Write a class decorator factory `function Injectable(...dependencyKeys: string[])` that stores the dependency keys onto `context.metadata.dependencies`. Apply it as `@Injectable(\"logger\", \"repository\")` to a class `UserService`. Write a small container function `resolve(ctor: any, registry: Record<string, unknown>)` that reads `ctor[Symbol.metadata].dependencies`, looks each one up in registry, and constructs the class by spreading the resolved dependencies into its constructor.", constraints: "Must NOT rely on any automatic constructor-parameter type reflection — dependencies must come entirely from the explicit factory arguments stored in metadata.", expectedOutput: "Calling `resolve(UserService, { logger: myLogger, repository: myRepo })` successfully constructs a UserService instance with both dependencies correctly injected.", check: "Verify that changing the ORDER of arguments to @Injectable changes the order dependencies are looked up and passed to the constructor, confirming the container relies entirely on the explicit declared list, not any type inference." },
  { id: 25, level: 5, title: "The Proxy-Traced Property Access Logger", scenario: "You are debugging a hard-to-track state bug and want EVERY property read on instances of a specific class logged automatically, without manually decorating each individual property.", objective: "Write a class decorator `traced` that returns `new Proxy(value, { construct(target, args) { const instance = Reflect.construct(target, args); return new Proxy(instance, { get(obj, prop) { console.log(`accessing ${String(prop)}`); return Reflect.get(obj, prop); } }); } })`. Apply `@traced` to a class `Account { balance = 100; owner = \"Kai\"; }`, create an instance, and read both `balance` and `owner`.", constraints: "Must use nested Proxies (one for construction, one for property access) inside a single class decorator — do not decorate balance and owner individually.", expectedOutput: "Reading `account.balance` logs \"accessing balance\" before returning 100; reading `account.owner` logs \"accessing owner\" before returning \"Kai\".", check: "Verify that a THIRD property added later to Account (with no changes to the decorator) is automatically traced too, confirming the blanket, property-name-agnostic nature of the Proxy-based approach." },
],
asynctypes: [
  { id: 1, level: 1, title: "The Typed Greeting Fetcher", scenario: "You are building a small onboarding screen that needs to asynchronously produce a personalized greeting for a new user.", objective: "Write an async function `getGreeting(name: string): Promise<string>` that returns `Hello, ${name}!` after awaiting `Promise.resolve()` (simulating a delay). Call it and log the resolved value.", constraints: "The function must be declared with the `async` keyword and an explicit `Promise<string>` return type annotation. Do not use `.then()` to consume the result — use `await` inside another async function.", expectedOutput: "Calling `await getGreeting(\"Maria\")` and logging the result prints: Hello, Maria!", check: "Verify `typeof getGreeting(\"X\")` is \"object\" (a Promise) before awaiting, and that the awaited value has `typeof` \"string\"." },
  { id: 2, level: 1, title: "The Delayed Counter", scenario: "A loading spinner component needs a helper that waits a fixed number of milliseconds before continuing.", objective: "Write a function `delay(ms: number): Promise<void>` using `new Promise` and `setTimeout`. In an async `main()` function, log \"start\", `await delay(0)`, then log \"end\".", constraints: "delay must be typed to return `Promise<void>`. Do not use async/await inside delay itself — only the Promise executor.", expectedOutput: "Console output in order: start, end.", check: "Confirm `delay(10) instanceof Promise` is true. Confirm awaiting `delay(0)` resolves with `undefined`." },
  { id: 3, level: 1, title: "The Safe Division Result", scenario: "A basic calculator API endpoint needs an async handler that can fail on divide-by-zero.", objective: "Write `async function safeDivide(a: number, b: number): Promise<number>` that throws `new Error(\"Cannot divide by zero\")` when b is 0, otherwise returns `a / b`. Call it inside a try/catch inside an async `main()`.", constraints: "Must use `throw` (not return an error value). The catch block must narrow the caught value with `instanceof Error` before logging `.message`.", expectedOutput: "`safeDivide(10, 2)` resolves to 5. `safeDivide(10, 0)` is caught and logs \"Cannot divide by zero\".", check: "Confirm the catch variable's type is `unknown` before narrowing (strict mode default). Confirm no unhandled promise rejection occurs." },
  { id: 4, level: 1, title: "The Typed Fetch Wrapper", scenario: "You are integrating with a mock API and want a typed helper around a fake `fetch`-like function.", objective: "Given `function mockFetch(): Promise<{ id: number; name: string }>`, write an async `main()` that awaits `mockFetch()`, destructures `id` and `name`, and logs them.", constraints: "Do not use `.then()`. The destructured variables must retain their inferred types (number and string) without explicit annotation.", expectedOutput: "Logs the numeric id and string name from the resolved object, e.g. \"1 Widget\".", check: "`typeof id` is \"number\" and `typeof name` is \"string\" after destructuring the awaited result." },
  { id: 5, level: 1, title: "The Optional Async Result", scenario: "A user lookup function may or may not find a matching record and needs to honestly reflect that in its type.", objective: "Write `async function findUserName(id: number): Promise<string | undefined>` that returns `\"Ann\"` if id === 1, and `undefined` otherwise. Await it for id 1 and id 2, logging both results with `?? \"not found\"` as a fallback.", constraints: "The return type must explicitly include `| undefined`. Use the nullish coalescing operator (`??`), not `||`, when providing the fallback.", expectedOutput: "`findUserName(1)` logs \"Ann\". `findUserName(2)` logs \"not found\".", check: "Confirm using `||` instead of `??` would behave identically here (since undefined is falsy) but explain in a comment why `??` is still the more correct choice for potential future falsy-but-valid names." },
  { id: 6, level: 2, title: "The Parallel Dashboard Loader", scenario: "A dashboard page needs to load a user profile and their notification count at the same time to minimize load time.", objective: "Given `getProfile(): Promise<{ name: string }>` and `getNotificationCount(): Promise<number>`, use `Promise.all` to fetch both concurrently and destructure the tuple result into `profile` and `count`.", constraints: "Must use `Promise.all`, not sequential `await` calls. TypeScript should infer the destructured tuple types automatically (no manual annotation).", expectedOutput: "Logs something like: \"Loaded profile for <name> with <count> notifications\".", check: "Confirm the type of the Promise.all result is a tuple `[{ name: string }, number]`, not a union array." },
  { id: 7, level: 2, title: "The Resilient Settings Loader", scenario: "An app loads several independent settings sources, and one failing should not prevent the others from being read.", objective: "Given three functions each returning `Promise<string>` (one of which rejects), use `Promise.allSettled` to gather all outcomes. Log each result's status, and its value or reason depending on which branch it is.", constraints: "Must use `Promise.allSettled`, not `Promise.all`. Narrow each result using its `status` field (a discriminated union check) before accessing `value` or `reason`.", expectedOutput: "Logs a \"fulfilled\" status with its string value for the two successful sources, and a \"rejected\" status with its reason for the failing one.", check: "Confirm accessing `.value` on a result typed as `PromiseSettledResult<string>` without first checking `status === \"fulfilled\"` is a type error." },
  { id: 8, level: 2, title: "The Type-Safe Retry Helper", scenario: "A flaky network call occasionally fails and should be retried a fixed number of times before giving up.", objective: "Write a generic `async function retry<T>(fn: () => Promise<T>, attempts: number): Promise<T>` that calls fn, and on rejection recursively retries with `attempts - 1`, rethrowing once attempts reach 0.", constraints: "Must be generic over T. Must rethrow the original error (not a new one) once attempts are exhausted. No `any` types anywhere in the signature.", expectedOutput: "Given a function that fails twice then succeeds on the third call, `retry(fn, 3)` resolves with the successful value.", check: "Confirm `retry` preserves the resolved type T (test with both a function returning Promise<number> and one returning Promise<string>)." },
  { id: 9, level: 2, title: "The Sequential Order Pipeline", scenario: "An order processing pipeline must validate, then charge, then ship — each step depending on the previous step's result.", objective: "Write three async functions: `validateOrder(order: Order): Promise<Order>`, `chargeOrder(order: Order): Promise<Receipt>`, `shipOrder(receipt: Receipt): Promise<void>`. Chain them with sequential `await` calls inside one async function.", constraints: "Must use sequential await (not Promise.all), since each step genuinely depends on the prior result. Explain in a comment why Promise.all would be incorrect here.", expectedOutput: "Calling the pipeline function with a valid order resolves after all three steps run in order, logging progress at each step.", check: "Confirm the function's overall return type is `Promise<void>` and that reordering the awaits would break the logical dependency." },
  { id: 10, level: 2, title: "The Cached Async Getter", scenario: "A configuration value is expensive to compute asynchronously and should only be computed once, then cached for subsequent calls.", objective: "Write a class `ConfigLoader` with a private `cached: Config | undefined` field and an async method `load(): Promise<Config>` that computes and caches the value on first call, returning the cached value on subsequent calls without recomputing.", constraints: "The cached field must be properly typed (not `any`). Must only call the expensive computation function once across multiple `load()` calls.", expectedOutput: "Calling `load()` twice in a row only triggers the underlying expensive computation once; both calls resolve to the same Config object.", check: "Add a counter in the expensive computation to confirm it is invoked exactly once across two `await loader.load()` calls." },
  { id: 11, level: 3, title: "The Discriminated Fetch State", scenario: "A React-style data-loading component needs a single, type-safe way to represent idle, loading, success, and error states for an async fetch.", objective: "Define a discriminated union type `FetchState<T> = { status: \"idle\" } | { status: \"loading\" } | { status: \"success\"; data: T } | { status: \"error\"; error: string }`. Write a function `render(state: FetchState<string>): string` using a switch on `status` that returns an appropriate message for each variant.", constraints: "Must use a discriminated union (not separate boolean flags). The switch must be exhaustive — add a never-typed default branch to prove it.", expectedOutput: "`render({ status: \"success\", data: \"Report\" })` returns something like \"Data: Report\". `render({ status: \"error\", error: \"timeout\" })` returns \"Error: timeout\".", check: "Adding a new FetchState variant without updating the switch must produce a compile error via the never-typed exhaustiveness check." },
  { id: 12, level: 3, title: "The Timeout-Guarded Request", scenario: "An API call to a slow, unreliable service needs to be automatically aborted if it takes longer than a set time limit.", objective: "Write a generic `function withTimeout<T>(promise: Promise<T>, ms: number): Promise<T>` that races the given promise against a timer promise which rejects with `new Error(\"Timed out\")` after ms milliseconds, using `Promise.race`.", constraints: "The timer promise must be typed `Promise<never>` since it never resolves successfully. Must preserve the generic type T of the original promise in the return type.", expectedOutput: "A fast-resolving promise passed through withTimeout resolves normally; a slow one rejects with \"Timed out\" before it would have resolved.", check: "Confirm withTimeout(Promise.resolve(5), 100) resolves to 5, and withTimeout(neverResolvingPromise, 10) rejects with the timeout error." },
  { id: 13, level: 3, title: "The Concurrent Batch Uploader", scenario: "A file upload feature needs to upload many files but must limit concurrency to avoid overwhelming the server with too many simultaneous requests.", objective: "Write an async function `uploadInBatches(files: File[], batchSize: number, uploadOne: (f: File) => Promise<void>): Promise<void>` that processes files in chunks of batchSize, awaiting `Promise.all` for each chunk before starting the next.", constraints: "Must not start more than batchSize uploads concurrently at any point. Use array slicing to build chunks; do not use a third-party concurrency library.", expectedOutput: "Given 10 files and a batchSize of 3, uploads happen in 4 sequential waves (3, 3, 3, 1) rather than all 10 at once.", check: "Track a running \"concurrent uploads\" counter inside uploadOne and assert it never exceeds batchSize at any point during execution." },
  { id: 14, level: 3, title: "The Typed Event Debouncer", scenario: "A live search input triggers an async search API call on every keystroke, but you only want the latest search to actually run.", objective: "Write a generic `function debounceAsync<A extends unknown[], T>(fn: (...args: A) => Promise<T>, ms: number): (...args: A) => Promise<T>` that delays invoking fn until ms have passed since the last call, cancelling any pending invocation.", constraints: "Must preserve fn's parameter types (A) and resolved type (T) in the returned function's signature. Use a single `let` variable to track the pending timer.", expectedOutput: "Calling the debounced function three times in rapid succession with different arguments only actually invokes fn once, with the last call's arguments, after the delay.", check: "Confirm the returned function's type signature exactly matches `(...args: A) => Promise<T>` and that TypeScript correctly infers A and T from a real fn passed to debounceAsync." },
  { id: 15, level: 3, title: "The Async Data Normalizer", scenario: "An API returns loosely-typed JSON that needs to be safely parsed and normalized into a strongly-typed shape before use elsewhere in the app.", objective: "Write `async function fetchAndNormalize<T>(url: string, normalize: (raw: unknown) => T): Promise<T>` that awaits a fetch, parses the JSON as `unknown`, and passes it through the provided normalize function before returning the result.", constraints: "The raw parsed JSON must be typed `unknown`, never `any`. normalize is responsible for all type narrowing/validation — fetchAndNormalize itself must remain fully generic.", expectedOutput: "Given a normalize function that validates and returns a `User` object, fetchAndNormalize resolves to a properly-typed `User`.", check: "Confirm that omitting the normalize step (returning the raw unknown value directly) would be a type error against the declared Promise<T> return type." },
  { id: 16, level: 4, title: "The Generic Result-Wrapped Fetcher", scenario: "Your team wants every async API call in the app to return an explicit success/failure value instead of relying on thrown exceptions, for more predictable error handling.", objective: "Define `type Result<T, E> = { ok: true; value: T } | { ok: false; error: E }`. Write `async function safeFetch<T>(fn: () => Promise<T>): Promise<Result<T, string>>` that calls fn, catching any rejection and converting it into a Result failure with a string error message.", constraints: "Must never let a rejection escape safeFetch — every possible outcome must be represented as a resolved Result. Narrow the caught unknown value into a string message safely (do not assume it is an Error).", expectedOutput: "A successful fn call resolves to `{ ok: true, value: ... }`; a throwing fn resolves to `{ ok: false, error: \"...\" }` instead of rejecting.", check: "Confirm calling `.catch()` on the returned promise from safeFetch is never actually needed, since it always resolves." },
  { id: 17, level: 4, title: "The Async Iterator Paginator", scenario: "An API paginates results across multiple pages, and you want to consume all pages as a single, lazy async stream rather than loading everything into memory at once.", objective: "Given `fetchPage(page: number): Promise<{ items: string[]; hasMore: boolean }>`, write an `async function* paginate(): AsyncGenerator<string>` that yields each item across all pages, stopping once hasMore is false. Consume it with `for await...of` and log every item.", constraints: "Must be an async generator function (`async function*`). Must not fetch all pages up front — only fetch the next page once the current page's items are exhausted.", expectedOutput: "Logs every item across all pages in order, fetching each page lazily as needed.", check: "Add a page-fetch counter and confirm it increments exactly once per page consumed, not once per item." },
  { id: 18, level: 4, title: "The Typed Middleware Pipeline", scenario: "A request-handling framework needs a composable middleware chain where each middleware can perform async work before calling the next one.", objective: "Define `type Middleware<Ctx> = (ctx: Ctx, next: () => Promise<void>) => Promise<void>`. Write `function compose<Ctx>(middlewares: Middleware<Ctx>[]): Middleware<Ctx>` that chains them so each middleware's next() invokes the following middleware in the array.", constraints: "Must be generic over Ctx. The composed middleware must correctly await the full chain before resolving, including cases where a middleware never calls next().", expectedOutput: "Given three logging middlewares that each log \"before\"/\"after\" around calling next(), running the composed pipeline logs them in properly nested order.", check: "Confirm that a middleware which does not call next() correctly short-circuits the rest of the chain (later middlewares never run)." },
  { id: 19, level: 4, title: "The Awaited Type Unwrapper", scenario: "A utility library needs to expose the \"eventual resolved type\" of any async function for use in other generic type definitions, without manually re-declaring it everywhere.", objective: "Given an existing async function `fetchOrder(): Promise<{ id: number; total: number }>`, define a type alias `OrderType` using `Awaited<ReturnType<typeof fetchOrder>>` that extracts the resolved Order shape without calling the function.", constraints: "Must use both `ReturnType` and `Awaited` together (not a duplicated manual interface). Verify OrderType structurally matches `{ id: number; total: number }`.", expectedOutput: "A function `function useOrder(order: OrderType) { ... }` accepts the exact resolved shape of fetchOrder's Promise without any duplicated type definition.", check: "Confirm that changing fetchOrder's resolved shape automatically updates OrderType with no other code changes needed." },
  { id: 20, level: 4, title: "The Cancellable Fetch Wrapper", scenario: "A search-as-you-type feature must be able to cancel an in-flight request when the user types again before the previous request finishes.", objective: "Write `function createCancellableFetch(): { run: (url: string) => Promise<Response>; cancel: () => void }` using an `AbortController` internally, where calling run() while a previous request is pending first cancels it before starting the new one.", constraints: "Must use AbortController/AbortSignal with fetch's signal option. Must correctly distinguish a genuine AbortError from other fetch failures when reporting results.", expectedOutput: "Calling run() twice in quick succession results in the first request being aborted and only the second one's response being used.", check: "Confirm catching the aborted first request's rejection identifies it via `err instanceof DOMException && err.name === \"AbortError\"` (or an equivalent check) rather than treating it as a generic failure." },
  { id: 21, level: 5, title: "The Bounded Concurrency Task Pool", scenario: "A batch job needs to process thousands of async tasks but must never run more than N tasks concurrently, to respect a downstream rate limit.", objective: "Write a generic `async function runPool<T>(tasks: Array<() => Promise<T>>, concurrency: number): Promise<T[]>` that runs at most `concurrency` tasks at a time, starting a new one as soon as any slot frees up, and returns all results in their original order.", constraints: "Results must preserve the original task order regardless of completion order. Must not use Promise.all on the full task list at once (that would defeat the concurrency limit).", expectedOutput: "Given 20 tasks and a concurrency of 4, at most 4 are ever in flight simultaneously, and the returned array matches the original task order.", check: "Instrument each task with a concurrent-count tracker to prove the limit is never exceeded, and verify results[i] corresponds to tasks[i], not completion order." },
  { id: 22, level: 5, title: "The Typed Async Event Emitter", scenario: "A real-time collaboration feature needs a strongly-typed publish/subscribe system where each event name has its own specific, statically-known payload shape, and subscribers are awaited before the emit resolves.", objective: "Define an events map interface, e.g. `interface Events { userJoined: { id: number }; message: { text: string } }`. Write a generic class `AsyncEmitter<E extends Record<string, unknown>>` with `on<K extends keyof E>(event: K, handler: (payload: E[K]) => Promise<void>): void` and `emit<K extends keyof E>(event: K, payload: E[K]): Promise<void>` that awaits all matching handlers.", constraints: "emit must reject an invalid event name or a payload shape mismatch at compile time. emit must await all registered handlers via Promise.all before resolving.", expectedOutput: "Registering a handler for \"userJoined\" and emitting `emit(\"userJoined\", { id: 5 })` awaits the handler before emit resolves; emitting with a wrong payload shape is a compile error.", check: "Confirm `emitter.emit(\"userJoined\", { text: \"oops\" })` fails to compile, while `emitter.emit(\"userJoined\", { id: 5 })` compiles and correctly awaits the handler." },
  { id: 23, level: 5, title: "The Distributed Lock Simulator", scenario: "A background job scheduler must ensure only one async task can hold a named \"lock\" at a time, queueing others until it is released.", objective: "Write a class `AsyncLock` with `async acquire(key: string): Promise<() => void>` that resolves with a release function once the named lock is free, queueing concurrent acquire() calls for the same key using chained promises.", constraints: "Two acquire() calls for the same key must never both be \"active\" at once — the second must only resolve after the first's release function is called. Different keys must not block each other.", expectedOutput: "Two concurrent acquire(\"orders\") calls resolve their release functions in sequence, one after the other, only once the previous holder calls release(); a concurrent acquire(\"shipping\") resolves independently.", check: "Instrument a shared counter to prove no two \"orders\" critical sections ever overlap in time, while \"shipping\" and \"orders\" sections can overlap freely." },
  { id: 24, level: 5, title: "The Streaming Aggregation Pipeline", scenario: "A large dataset arrives as an async stream of chunks and must be aggregated into summary statistics without ever holding the entire dataset in memory at once.", objective: "Given `function streamChunks(): AsyncGenerator<number[]>` yielding batches of numbers, write `async function aggregate(stream: AsyncGenerator<number[]>): Promise<{ count: number; sum: number; avg: number }>` that consumes the stream with `for await...of`, accumulating a running count and sum, computing avg only at the end.", constraints: "Must not collect all chunks into one array before processing — each chunk must be folded into the running totals as it arrives. Must handle an empty stream (avg should be 0, not NaN).", expectedOutput: "Given chunks [[1,2,3],[4,5]], resolves to `{ count: 5, sum: 15, avg: 3 }`.", check: "Confirm memory usage stays proportional to one chunk at a time (verify by reasoning/comment, since actual memory profiling is out of scope) and that an empty stream input resolves to `{ count: 0, sum: 0, avg: 0 }`." },
  { id: 25, level: 5, title: "The Self-Healing Circuit Breaker", scenario: "A service client needs to stop hammering a downstream dependency that is currently failing, automatically \"opening\" the circuit after repeated failures and periodically testing if it has recovered.", objective: "Write a generic class `CircuitBreaker<T>` wrapping an async operation `() => Promise<T>`, with states \"closed\" (normal), \"open\" (fast-failing without calling the operation), and \"half-open\" (allowing one test call after a cooldown). Expose `async execute(): Promise<T>` that respects the current state and transitions between states based on success/failure and elapsed time.", constraints: "Must model the three states as a discriminated union or literal type, not booleans. While open, execute() must reject immediately with a distinct CircuitOpenError without calling the wrapped operation. A successful half-open call must close the circuit; a failed one must reopen it.", expectedOutput: "After 3 consecutive failures, the breaker opens and subsequent execute() calls reject instantly with CircuitOpenError until the cooldown elapses; after cooldown, one test call is allowed through.", check: "Simulate a failing operation to trigger the open state, confirm execute() short-circuits without invoking the operation while open, then simulate cooldown elapsing and a successful test call closing the circuit again." },
],
errorhandling: [
  { id: 1, level: 1, title: "The Narrowed Catch Block", scenario: "A settings page calls a function that might throw, and you need to safely display the error message to the user.", objective: "Write `function parseSettings(json: string): object` that calls `JSON.parse(json)` inside the function body (letting it throw naturally on bad input). In a try/catch, call it with invalid JSON, and inside catch, narrow the caught value with `instanceof Error` before logging `err.message`.", constraints: "Do not annotate the catch variable's type manually — rely on the default `unknown` type from strict mode. Must use `instanceof Error`, not a type assertion (`as Error`).", expectedOutput: "Calling with `\"{bad json\"` logs the SyntaxError's message (e.g. something mentioning unexpected token).", check: "Confirm that removing the `instanceof Error` check and directly accessing `err.message` produces a compile error under strict mode." },
  { id: 2, level: 1, title: "The Custom Validation Error", scenario: "A signup form validator needs to throw a specific, identifiable error type when the entered age is invalid.", objective: "Create `class ValidationError extends Error` with a constructor taking `message: string` and calling `super(message)`. Write `function validateAge(age: number): void` that throws a `new ValidationError(\"Age must be positive\")` when age <= 0.", constraints: "ValidationError must properly call super(message). Do not use a plain Error for this — must define and throw the custom subclass.", expectedOutput: "Calling `validateAge(-1)` inside a try/catch is caught, and `err instanceof ValidationError` is true, with `err.message` equal to \"Age must be positive\".", check: "Confirm `err instanceof Error` is also true (since ValidationError extends Error), and that `validateAge(25)` does not throw." },
  { id: 3, level: 1, title: "The Safe JSON Parser", scenario: "A configuration loader receives a string that might not be valid JSON, and the app should not crash if parsing fails.", objective: "Write `function safeParseJson(text: string): unknown | null` that returns the parsed value on success, or `null` if `JSON.parse` throws, using try/catch internally.", constraints: "The success type must be `unknown` (not `any`). Must catch the error inside the function itself — callers should never see a thrown exception from this function.", expectedOutput: "`safeParseJson('{\"a\":1}')` returns `{ a: 1 }`. `safeParseJson(\"bad\")` returns `null`.", check: "Confirm calling safeParseJson with malformed input never throws — wrap a test call in a try/catch that should never actually enter the catch block." },
  { id: 4, level: 1, title: "The Non-Empty Array Guard", scenario: "A reporting function needs to guarantee it received at least one data point before computing an average, and should fail loudly with a clear message otherwise.", objective: "Write `function average(numbers: number[]): number` that throws `new RangeError(\"Cannot average an empty array\")` if the array is empty, otherwise returns the arithmetic mean.", constraints: "Must use `RangeError` specifically (not a plain Error) since this is a value-range violation. Must check the empty case before doing any division.", expectedOutput: "`average([2, 4, 6])` returns 4. `average([])` throws a RangeError with the given message.", check: "Confirm `err instanceof RangeError` is true when catching the thrown error, and also confirm `err instanceof Error` is true." },
  { id: 5, level: 1, title: "The Error Message Normalizer", scenario: "Various parts of a codebase throw different kinds of values (Errors, strings, even numbers), and you need one helper to safely extract a displayable message from any of them.", objective: "Write `function toMessage(err: unknown): string` that returns `err.message` if err is an Error instance, `err` itself if it is already a string, and `\"Unknown error\"` for anything else.", constraints: "The parameter must be typed `unknown`. Use `instanceof Error` and `typeof err === \"string\"` checks in that order — do not use `any`.", expectedOutput: "`toMessage(new Error(\"boom\"))` returns \"boom\". `toMessage(\"oops\")` returns \"oops\". `toMessage(404)` returns \"Unknown error\".", check: "Confirm the function compiles with no `any` types anywhere and correctly narrows err in each branch before accessing type-specific members." },
  { id: 6, level: 2, title: "The Result-Returning Parser", scenario: "A form library wants to avoid throwing exceptions for expected validation failures, instead returning an explicit success/failure value.", objective: "Define `type Result<T, E> = { ok: true; value: T } | { ok: false; error: E }`. Write `function parsePositiveInt(input: string): Result<number, string>` that returns a failure Result with a descriptive message if input is not a positive integer, or a success Result with the parsed number otherwise.", constraints: "Must not throw under any input — every outcome must be represented as a Result. Use `Number.isInteger` in the validation.", expectedOutput: "`parsePositiveInt(\"42\")` returns `{ ok: true, value: 42 }`. `parsePositiveInt(\"-3\")` returns `{ ok: false, error: \"must be a positive integer\" }`.", check: "Confirm that accessing `.value` on the Result without first checking `.ok` is a type error, proving the discriminated union narrows correctly." },
  { id: 7, level: 2, title: "The HTTP Error Hierarchy", scenario: "An API client needs distinct, catchable error types for different HTTP failure categories so calling code can react differently to each.", objective: "Create a base `class HttpError extends Error` with a `readonly status: number` constructor parameter property, then two subclasses `NotFoundError extends HttpError` (fixed status 404) and `UnauthorizedError extends HttpError` (fixed status 401). Write `function describe(err: HttpError): string` that uses instanceof checks to return a specific message per subclass, falling back to a generic message for HttpError itself.", constraints: "status must be declared with a `public readonly` (or similar) parameter property. Subclass constructors must call super with the fixed status.", expectedOutput: "`describe(new NotFoundError(\"missing\"))` returns something distinguishing \"not found\"; `describe(new UnauthorizedError(\"no access\"))` returns something distinguishing \"unauthorized\".", check: "Confirm `new NotFoundError(\"x\").status === 404` and `new UnauthorizedError(\"x\").status === 401`, and that both are `instanceof HttpError` and `instanceof Error`." },
  { id: 8, level: 2, title: "The Assertion-Guarded Config Loader", scenario: "A startup routine reads a config value that must be a non-empty string, and later code should be able to rely on that guarantee without repeated checks.", objective: "Write an assertion function `function assertNonEmptyString(value: unknown, name: string): asserts value is string` that throws a `TypeError` (including name in the message) if value is not a string or is an empty string. Use it to validate a config value, then use the value as a plain string afterward with no further checks.", constraints: "Must use the `asserts value is string` assertion signature syntax (not a boolean-returning type predicate). Must throw TypeError specifically, not a plain Error.", expectedOutput: "After `assertNonEmptyString(apiUrl, \"apiUrl\")` passes without throwing, `apiUrl.toUpperCase()` compiles and runs without any additional type narrowing.", check: "Confirm calling assertNonEmptyString(42, \"port\") throws a TypeError mentioning \"port\" in its message, and that TypeScript actually narrows the checked variable's type after a non-throwing call." },
  { id: 9, level: 2, title: "The Exhaustive Shape Calculator", scenario: "A geometry library computes areas for different shape types and must be guaranteed to handle every shape variant, even as new ones are added later.", objective: "Define `type Shape = { kind: \"circle\"; radius: number } | { kind: \"rectangle\"; width: number; height: number }`. Write `function area(shape: Shape): number` using a switch on `kind`, with a `default` branch that assigns the remaining value to a `never`-typed variable to guarantee exhaustiveness.", constraints: "Must use the never-typed default branch pattern (not just an ordinary default that returns 0 or throws generically). Do not use `if/else` — must use `switch`.", expectedOutput: "`area({ kind: \"circle\", radius: 2 })` returns approximately 12.57. `area({ kind: \"rectangle\", width: 3, height: 4 })` returns 12.", check: "Add a third Shape variant (e.g. \"triangle\") without updating the switch and confirm it produces a compile error at the never assignment." },
  { id: 10, level: 2, title: "The Error-Cause Chain Logger", scenario: "A data-import job wraps low-level parsing failures in a higher-level, more descriptive error while preserving the original failure for debugging.", objective: "Write `function importRow(raw: string): Record<string, unknown>` that calls `JSON.parse(raw)` and, if it throws, catches the original error and re-throws `new Error(\"Failed to import row\", { cause: originalErr })`. In a caller, catch the outer error and log both its message and `(err.cause as Error).message`.", constraints: "Must use the standard `cause` option on the Error constructor (ES2022), not a custom property. Must preserve the exact original error object as cause, not a stringified version.", expectedOutput: "Importing an invalid row logs the outer message (\"Failed to import row\") and the inner cause's message (the original SyntaxError text).", check: "Confirm `err.cause instanceof SyntaxError` (or Error, depending on how it was thrown) is true, proving the original error was preserved rather than discarded." },
  { id: 11, level: 3, title: "The Field-Level Validation Collector", scenario: "A registration form needs to show the user every invalid field at once, not just the first one encountered.", objective: "Write `class FormValidationError extends Error` with a `readonly issues: Record<string, string>` property. Write `function validateForm(data: { email: string; age: number }): void` that collects all field issues into an object and throws one FormValidationError with all of them, only if at least one issue exists.", constraints: "Must not throw on the first invalid field — all fields must be checked and collected before any throw. issues must be typed `Record<string, string>`, not `any`.", expectedOutput: "Given `{ email: \"\", age: -1 }`, the thrown error's `issues` object has entries for both \"email\" and \"age\".", check: "Confirm valid input `{ email: \"a@b.com\", age: 20 }` does not throw at all, and that the issues object always has exactly the invalid fields as keys." },
  { id: 12, level: 3, title: "The Type-Safe Error Catalog", scenario: "A backend service wants every possible error code it can produce to map to a consistent HTTP status, in a way the compiler can verify is complete.", objective: "Define `type ErrorCode = \"NOT_FOUND\" | \"UNAUTHORIZED\" | \"CONFLICT\"`. Create a `const STATUS_MAP: Record<ErrorCode, number>` mapping each code to its status (404, 401, 409). Write `function statusFor(code: ErrorCode): number` that looks it up in STATUS_MAP.", constraints: "STATUS_MAP must be typed `Record<ErrorCode, number>` so that omitting any ErrorCode key is a compile error. Do not use a switch statement for this task — use the Record lookup instead.", expectedOutput: "`statusFor(\"CONFLICT\")` returns 409.", check: "Remove one entry from STATUS_MAP and confirm it produces a compile error (missing property), demonstrating the Record type enforces completeness." },
  { id: 13, level: 3, title: "The Custom Type Guard for API Errors", scenario: "An API client receives error responses whose shape is unknown until runtime, and needs to safely check for a specific known error format before using it.", objective: "Write a type guard `function isApiErrorShape(value: unknown): value is { code: string; message: string }` that checks value is a non-null object with both a string `code` and string `message` property. Use it inside a catch block to safely branch on a caught unknown error.", constraints: "Must be a genuine type predicate function (`value is {...}`), not a boolean-returning function used with a manual cast. Must check both properties' existence and type before returning true.", expectedOutput: "Given a caught value `{ code: \"E1\", message: \"bad\" }`, `isApiErrorShape(err)` narrows err so `err.code` and `err.message` are accessible without further casts.", check: "Confirm the guard returns false (and does not narrow) for a caught value missing the code property, or where code is a number instead of a string." },
  { id: 14, level: 3, title: "The Multi-Error Batch Reporter", scenario: "A batch job processes many independent records and needs to report every failure at the end, not stop at the first one.", objective: "Write `function processAll(records: string[]): { succeeded: number; errors: Error[] }` that attempts `JSON.parse` on each record inside a per-record try/catch, collecting all thrown errors (normalized to Error instances) into an array, and counting successes separately.", constraints: "A single failing record must not stop processing of the remaining records — use a try/catch inside the loop, not around it. Normalize any non-Error thrown value into a real Error before collecting it.", expectedOutput: "Given `['{\"a\":1}', \"bad\", '{\"b\":2}']`, returns `{ succeeded: 2, errors: [<one Error>] }`.", check: "Confirm `errors.length` matches the number of genuinely invalid records, and that every entry in errors is `instanceof Error`." },
  { id: 15, level: 3, title: "The Safe Optional Chain Reporter", scenario: "A user profile display needs to gracefully handle deeply nested, possibly-missing data from an inconsistent API response without throwing or showing \"undefined\" to the user.", objective: "Given `interface Profile { address?: { city?: string } }`, write `function displayCity(profile: Profile): string` that uses optional chaining and nullish coalescing to safely produce the city name or a fallback string \"Unknown location\".", constraints: "Must use `?.` for the nested access and `??` (not `||`) for the fallback. Do not use try/catch — this should be handled purely through safe navigation.", expectedOutput: "`displayCity({})` returns \"Unknown location\". `displayCity({ address: { city: \"Reno\" } })` returns \"Reno\".", check: "Confirm a profile with `address: {}` (city missing but address present) also correctly returns \"Unknown location\" rather than throwing." },
  { id: 16, level: 4, title: "The Result Combinator Library", scenario: "A validation pipeline chains several fallible steps together and wants to avoid deeply nested if/else checks after each one.", objective: "Define `type Result<T, E> = { ok: true; value: T } | { ok: false; error: E }`. Write two generic combinators: `function map<T, U, E>(r: Result<T, E>, fn: (v: T) => U): Result<U, E>` and `function flatMap<T, U, E>(r: Result<T, E>, fn: (v: T) => Result<U, E>): Result<U, E>`. Use them to chain a parse-then-validate pipeline on a string input.", constraints: "Both combinators must correctly pass through a failure Result unchanged, without calling fn. Must be fully generic (no `any`).", expectedOutput: "Chaining `flatMap(parseResult, validate)` on a failing parseResult short-circuits and returns the original error without calling validate.", check: "Test both combinators independently: map on a Failure must return the same Failure untouched; flatMap on a Success must correctly invoke fn and return its Result." },
  { id: 17, level: 4, title: "The Retryable vs Fatal Error Distinction", scenario: "A job runner needs to decide whether to automatically retry a failed task or give up immediately, based on the nature of the failure.", objective: "Create `class RetryableError extends Error {}` and `class FatalError extends Error {}`. Write `async function runWithRetry(task: () => Promise<void>, maxAttempts: number): Promise<void>` that retries only when the caught error is a RetryableError, rethrowing immediately (without retrying) for a FatalError or any other unrecognized error.", constraints: "Must distinguish the three cases (RetryableError, FatalError, unknown) using instanceof checks in the correct order. Must stop retrying and rethrow once maxAttempts is exhausted, even for a RetryableError.", expectedOutput: "A task throwing FatalError fails immediately on the first attempt with no retries. A task throwing RetryableError twice then succeeding resolves successfully after 3 total attempts.", check: "Instrument the task with an attempt counter to confirm FatalError results in exactly 1 attempt, while a RetryableError-then-success task results in exactly the expected number of attempts." },
  { id: 18, level: 4, title: "The Schema-Validated Config Parser", scenario: "A configuration object loaded from an untrusted JSON file must be verified to actually match the expected shape before the rest of the app trusts it.", objective: "Write `function parseConfig(raw: unknown): Result<{ port: number; host: string }, string[]>` that validates raw is an object with a numeric `port` and string `host`, collecting a list of specific issue messages for anything that does not match, returning a failure Result with all issues if any exist.", constraints: "raw must be typed `unknown` (simulating untrusted JSON.parse output). Must collect ALL shape issues (not just the first) into the failure's string array.", expectedOutput: "Given `{ port: \"8080\", host: 123 }`, returns a failure listing two issues (port not a number, host not a string). Given `{ port: 8080, host: \"localhost\" }`, returns a success with that typed object.", check: "Confirm the success branch's value is genuinely typed `{ port: number; host: string }` with no remaining `unknown` or `any` in its type." },
  { id: 19, level: 4, title: "The Aggregate Failure Reporter", scenario: "A deployment script runs several independent async checks (health, disk space, connectivity) and wants to report all failures together if more than one check fails.", objective: "Given three functions each returning `Promise<void>` (rejecting on failure), use `Promise.allSettled` to run all of them, collect every rejection reason into an array, and if any exist, throw a single `AggregateError` wrapping them with a summary message.", constraints: "Must use `Promise.allSettled`, not `Promise.all`. Must use the real built-in `AggregateError` constructor, not a custom class with a similar name.", expectedOutput: "If two of the three checks fail, the thrown AggregateError has `errors.length === 2`, each entry being the original rejection reason.", check: "Confirm that when all checks succeed, no AggregateError is thrown at all, and the function completes normally." },
  { id: 20, level: 4, title: "The Branded Error Code Guard", scenario: "A large codebase wants to prevent arbitrary strings from being accidentally used as error codes anywhere a validated code is expected, catching typos at compile time.", objective: "Define a branded type `type ErrorCode = string & { readonly __brand: \"ErrorCode\" }`. Write `function toErrorCode(raw: string): ErrorCode` that validates raw matches a fixed set of known codes (e.g. via an array `includes` check) and either returns it cast to ErrorCode, or throws if invalid. Write a function `logError(code: ErrorCode): void` that only accepts the branded type.", constraints: "logError must reject a plain, unbranded string argument at compile time — only values that passed through toErrorCode should be assignable. toErrorCode must validate against a real, finite list of known codes at runtime.", expectedOutput: "`logError(toErrorCode(\"NOT_FOUND\"))` compiles and runs; `logError(\"NOT_FOUND\")` (a raw string, skipping validation) must fail to compile.", check: "Confirm calling toErrorCode with an unrecognized string throws, and confirm (via a comment, since it should not compile) that passing a bare string literal directly to logError is rejected by the type checker." },
  { id: 21, level: 5, title: "The Typed Error Boundary Simulator", scenario: "A UI component tree needs a generic \"error boundary\" abstraction that can wrap any risky synchronous render function, catch failures, and expose a typed fallback state.", objective: "Write a generic class `ErrorBoundary<T>` with a method `render(fn: () => T, fallback: (err: Error) => T): T` that calls fn, and if it throws, normalizes the caught value to a real Error (using a helper) and calls fallback with it, returning fallback's result instead of propagating the exception.", constraints: "Must be generic over T so both fn and fallback share the same return type. Must normalize any non-Error thrown value (string, number, etc.) into a genuine Error before passing it to fallback.", expectedOutput: "Given a throwing fn and a fallback returning a default value, render() returns the fallback value instead of throwing. Given a non-throwing fn, render() returns fn's own result directly.", check: "Test with a fn that throws a plain string (not an Error) and confirm fallback still receives a genuine Error instance with a sensible message." },
  { id: 22, level: 5, title: "The Structured Error Serialization Layer", scenario: "A logging pipeline needs to serialize arbitrary caught errors (including custom subclasses with extra fields) into a consistent JSON-safe shape for a log aggregation service.", objective: "Create a class hierarchy: `class AppError extends Error` with a `readonly code: string` and a `toJSON(): { name: string; code: string; message: string; cause?: unknown }` method that also recursively serializes a chained `cause` if it is itself an AppError. Create at least one subclass with an additional field also included in its overridden toJSON.", constraints: "toJSON must be overridden in the subclass to include its extra field while still including all base fields. The cause chain serialization must handle at least 2 levels of nested AppError causes.", expectedOutput: "`JSON.stringify(new SpecificAppError(...))` produces a complete, nested JSON object reflecting the full error chain and all custom fields, not the default `{}` you get from stringifying a plain Error.", check: "Construct a 2-level cause chain (AppError caused by another AppError) and confirm the serialized JSON includes both levels with all their respective custom fields intact." },
  { id: 23, level: 5, title: "The Compile-Time Exhaustive State Machine", scenario: "An order fulfillment system models its lifecycle as a strict state machine, and any missing transition handling for a state must be caught by the compiler, not discovered in production.", objective: "Define a discriminated union `OrderState` with at least 5 variants (e.g. \"created\", \"paid\", \"shipped\", \"delivered\", \"cancelled\"), each carrying only the data relevant to that state. Write `function transition(state: OrderState, event: string): OrderState` handling every state with a switch and a never-typed exhaustiveness guard, throwing a custom `InvalidTransitionError` for disallowed event/state combinations.", constraints: "Every state variant must carry only its own relevant fields (illegal states unrepresentable). The exhaustiveness guard must be a real never-typed default branch, not a comment. InvalidTransitionError must be a proper Error subclass with fields for both the attempted event and the current state.", expectedOutput: "A valid transition (e.g. \"created\" + \"pay\" event) returns the new \"paid\" state. An invalid one (e.g. \"delivered\" + \"cancel\" event) throws InvalidTransitionError with both details.", check: "Add a 6th state variant without updating the switch and confirm a compile error appears at the never-typed exhaustiveness check." },
  { id: 24, level: 5, title: "The Async Validation Pipeline with Rollback", scenario: "A multi-step account creation process performs several async side effects (create user, provision storage, send welcome email) and must cleanly roll back prior steps if a later one fails.", objective: "Write `async function createAccount(input: SignupInput): Promise<Account>` that runs each async step in sequence, tracking a stack of \"undo\" functions for completed steps; if any step throws, catch it, run all recorded undo functions in reverse order (each wrapped in its own try/catch so an undo failure does not mask the original error), then rethrow the original error wrapped with `{ cause }`.", constraints: "Undo functions must run in strictly reverse order of the completed steps. A failure inside an undo function must be logged but must NOT replace or suppress the original error being rethrown.", expectedOutput: "If step 2 of 3 fails, step 1's undo function runs (step 3 never started, so nothing to undo there), and the final rejection is a wrapped error whose `cause` is the original step-2 failure.", check: "Simulate an undo function that itself throws, and confirm the original step failure is still what ultimately propagates to the caller, with the undo failure only logged separately." },
  { id: 25, level: 5, title: "The Type-Safe Error Middleware Chain", scenario: "A web framework needs a way for different middleware layers to handle specific error types thrown anywhere earlier in a request pipeline, falling through to the next handler if a given middleware does not recognize the error.", objective: "Define `type ErrorHandler<E extends Error = Error> = (err: E, next: () => void) => void`. Write `function composeErrorHandlers(handlers: Array<{ matches: (err: unknown) => boolean; handle: ErrorHandler<any> }>): (err: unknown) => void` that tries each handler in order (checking matches first), calling handle only for the first matching one, and falling through to a final \"unhandled error\" log if none match.", constraints: "matches must be checked before handle is invoked for each entry. Provide at least two concrete handler entries for two distinct custom Error subclasses to demonstrate correct routing, plus the fallback path for an unrecognized error.", expectedOutput: "An error matching the second handler in the array is routed directly to it (the first handler's handle is never called); a completely unrecognized error falls through to the final unhandled-error log.", check: "Instrument each handler with a call counter to prove exactly one handle function (or none, for the fallback case) runs per dispatched error, never more than one." },
],
tsconfig: [
  { id: 1, level: 1, title: "The First Project Scaffold", scenario: "You are starting a brand-new Node.js command-line tool from scratch and need a working tsconfig.json before writing any code.", objective: "Create a tsconfig.json with `compilerOptions` containing `\"target\": \"ES2020\"`, `\"module\": \"commonjs\"`, `\"strict\": true`, and `\"outDir\": \"./dist\"`. Add a top-level `\"include\": [\"src/**/*.ts\"]`.", constraints: "Must use the exact top-level key `compilerOptions` for the settings. Must include both `include` and the four listed compiler options — no extras required.", expectedOutput: "Running `tsc` compiles every .ts file under src/ into corresponding .js files under dist/, with strict type-checking enabled.", check: "Verify a file with an implicit any parameter fails to compile due to strict, and that output files land in dist/ matching the src/ structure." },
  { id: 2, level: 1, title: "The Loosened Legacy Build", scenario: "You inherited an old codebase that fails to compile under strict mode, and need a working baseline config while the team plans a gradual migration.", objective: "Create a tsconfig.json with `\"strict\": false`, `\"target\": \"ES5\"`, `\"module\": \"commonjs\"`, and `\"noImplicitAny\": false` explicitly, so the project compiles without immediate type errors.", constraints: "strict must be explicitly false (not just omitted). Add a comment (outside the JSON, in your notes) explaining this is a temporary starting point, not a long-term goal.", expectedOutput: "A file using implicit any parameters and loose null handling compiles successfully without errors.", check: "Confirm that later flipping \"strict\" to true on the same source files reveals multiple new compile errors, demonstrating what was being silently allowed." },
  { id: 3, level: 1, title: "The Declaration File Publisher", scenario: "You are publishing a small utility library to npm and want consumers to get full type information alongside the compiled JavaScript.", objective: "Configure tsconfig.json with `\"declaration\": true`, `\"outDir\": \"./dist\"`, `\"target\": \"ES2019\"`, and `\"module\": \"commonjs\"`, so building the project produces both .js and matching .d.ts files.", constraints: "declaration must be explicitly set to true. Verify the emitted dist/ folder contains a .d.ts file for every source .ts file.", expectedOutput: "After running tsc, dist/index.js and dist/index.d.ts both exist and the .d.ts file accurately reflects the exported functions' types.", check: "Confirm that a consuming project importing from the published package gets full IntelliSense/type-checking, not `any`, by inspecting the generated .d.ts content." },
  { id: 4, level: 1, title: "The Debuggable Source Map Setup", scenario: "A Node.js service is throwing errors in production, and you want stack traces to point to the original .ts lines instead of the compiled .js output.", objective: "Add `\"sourceMap\": true` to an existing tsconfig.json alongside `\"outDir\": \"./dist\"` and `\"target\": \"ES2020\"`. Compile the project and confirm a .map file is generated next to each .js file.", constraints: "sourceMap must be true. Do not enable inlineSourceMap at the same time — use separate .map files for this task.", expectedOutput: "Running the compiled dist/index.js with a debugger (or an error stack trace) correctly maps back to the original .ts source lines.", check: "Confirm each generated .js file has a matching .js.map file in the same output folder, and that the .js file's final line references it via a sourceMappingURL comment." },
  { id: 5, level: 1, title: "The Excluded Test Files Build", scenario: "A project has both source code and test files (*.test.ts) intermixed in the same src/ folder, but the production build should not compile the tests.", objective: "Configure `\"include\": [\"src/**/*.ts\"]` and `\"exclude\": [\"src/**/*.test.ts\"]` in tsconfig.json, so building the project skips all test files while still compiling everything else.", constraints: "Must use exclude specifically for the test file pattern, not by restructuring folders. include must still broadly cover src/.", expectedOutput: "Running tsc produces compiled output for every non-test file under src/, with zero .test.js files appearing in the output.", check: "Add a deliberately broken (type-error-containing) test file matching the exclude pattern and confirm the build still succeeds, proving it was truly excluded from type-checking." },
  { id: 6, level: 2, title: "The Interop-Friendly Import Config", scenario: "A project imports several CommonJS-only npm packages (like older Express-style libraries) using default-import syntax, and the compiler currently rejects it.", objective: "Add `\"esModuleInterop\": true` and `\"allowSyntheticDefaultImports\": true` to tsconfig.json, then verify a default import like `import express from \"express\"` compiles cleanly.", constraints: "Both flags must be explicitly set (even though esModuleInterop implies the other, set both to demonstrate understanding). Do not use `import * as express from \"express\"` as a workaround — the whole point is enabling the default-import form.", expectedOutput: "The default import compiles and, at runtime, resolves to the correct CommonJS module export.", check: "Temporarily remove esModuleInterop and confirm the same import either fails to compile or behaves incorrectly at runtime, demonstrating what the flag fixes." },
  { id: 7, level: 2, title: "The Path Alias Resolver", scenario: "A growing frontend project has deeply nested relative imports like `../../../utils/format` that are hard to read and error-prone to refactor.", objective: "Configure `\"baseUrl\": \"./src\"` and `\"paths\": { \"@utils/*\": [\"utils/*\"] }` in tsconfig.json, then rewrite an import from a relative path to `import { formatDate } from \"@utils/date\"`.", constraints: "baseUrl must point to the src folder. The paths mapping must use the exact `@utils/*` wildcard pattern shown.", expectedOutput: "The aliased import type-checks successfully in the editor and with tsc, resolving to src/utils/date.ts.", check: "Note in a comment that the bundler/runtime (webpack, Jest, ts-node, etc.) will need a matching alias configuration for the import to actually resolve at runtime, since tsconfig paths only affects type-checking." },
  { id: 8, level: 2, title: "The Unused Code Detector", scenario: "A code review keeps finding leftover unused variables and forgotten function parameters that should have been cleaned up before merging.", objective: "Add `\"noUnusedLocals\": true` and `\"noUnusedParameters\": true` to tsconfig.json. Introduce a function with an unused local variable and an unused parameter, and observe the resulting compile errors.", constraints: "Both flags must be enabled together. Do not use an underscore-prefixed parameter name to silently bypass the check for this task — actually remove the unused code once you observe the error.", expectedOutput: "The build fails with errors pointing at the specific unused local variable and unused parameter; after removing them, the build succeeds.", check: "Confirm a parameter deliberately prefixed with an underscore (a common convention some codebases allow) is still flagged unless the project explicitly configures an exception, or note that TypeScript does not exempt underscore-prefixed names by default for this flag." },
  { id: 9, level: 2, title: "The Fast Dependency-Skipping Build", scenario: "A project's build has become slow, and investigation shows most of the time is spent re-checking type declaration files from third-party npm packages.", objective: "Add `\"skipLibCheck\": true` to tsconfig.json and measure/compare build time before and after (or reason about why it would help) for a project with several dependencies.", constraints: "skipLibCheck must be added without changing target, module, or strict settings. Explain in a comment that this only skips .d.ts checking, not your own .ts files.", expectedOutput: "Build time is noticeably reduced (or, in a smaller test project, the compiler no longer surfaces a type error originating from inside node_modules' declaration files).", check: "Confirm your own project's source files are still fully type-checked (introduce a deliberate type error in your own code and confirm it is still caught) even with skipLibCheck enabled." },
  { id: 10, level: 2, title: "The JSON-Importing Config Loader", scenario: "A build script wants to import a JSON configuration file directly and use its values with proper types, instead of using fs.readFileSync and JSON.parse manually.", objective: "Enable `\"resolveJsonModule\": true` in tsconfig.json, then write `import config from \"./config.json\"` and use one of its properties with full type inference (no manual type annotation).", constraints: "Must use a direct ES import of the .json file, not a runtime fs read. resolveJsonModule must be explicitly enabled — do not rely on any default.", expectedOutput: "TypeScript infers the shape of config.json automatically (e.g. as a literal object type) and using a property with the wrong assumed type produces a compile error.", check: "Change a value in config.json (e.g. a number to a string) and confirm code relying on the old inferred type now shows a compile error, proving real type inference from the JSON content." },
  { id: 11, level: 3, title: "The Null-Safety Migration Sprint", scenario: "A mid-sized codebase wants to adopt strictNullChecks but discovers dozens of existing compile errors when flipping it on all at once.", objective: "Start from `\"strict\": true, \"strictNullChecks\": false` (deliberately overriding just that one sub-flag). Fix the type errors in one specific file by flipping strictNullChecks to true only after adding proper null checks/optional chaining to that file, then note the remaining project-wide errors are still suppressed.", constraints: "Must demonstrate the override mechanism (strict:true with one sub-flag explicitly false). Fix at least one real null-related bug uncovered when testing with strictNullChecks temporarily true.", expectedOutput: "With strictNullChecks temporarily enabled, at least one specific, real null-handling bug is caught and fixed with an explicit check or `?.`/`??`.", check: "Confirm reverting strictNullChecks to false again removes that specific error, demonstrating the override truly controls just that one check." },
  { id: 12, level: 3, title: "The Monorepo Shared Base Config", scenario: "A monorepo has three packages that should all share the same strict compiler settings but need different output directories.", objective: "Create a `tsconfig.base.json` with shared settings (`\"strict\": true`, `\"target\": \"ES2020\"`, `\"module\": \"commonjs\"`, `\"esModuleInterop\": true`). Create three package-level tsconfig.json files, each with `\"extends\": \"../tsconfig.base.json\"` and their own distinct `\"outDir\"` and `\"rootDir\"`.", constraints: "The base config must not include outDir/rootDir (those are package-specific). Each package config must override only outDir/rootDir/include, inheriting everything else.", expectedOutput: "All three packages enforce the same strict rules, but each compiles into its own separate output folder.", check: "Change one strict setting in the base config and confirm all three packages immediately reflect the change without editing each individually." },
  { id: 13, level: 3, title: "The Node ESM Migration", scenario: "A Node.js backend service is migrating from CommonJS to native ES modules and needs its tsconfig updated to match Node's actual module resolution rules.", objective: "Update tsconfig.json to `\"module\": \"nodenext\"` and `\"moduleResolution\": \"nodenext\"`, ensure package.json has `\"type\": \"module\"`, and update at least one relative import to include an explicit `.js` extension (matching the compiled output) as Node ESM requires.", constraints: "Must use nodenext for both module and moduleResolution together. Relative imports must include explicit extensions once migrated — do not leave any extensionless relative import in the migrated file.", expectedOutput: "The project compiles under nodenext with no resolution errors, and the emitted JavaScript runs correctly under `node` with ESM semantics.", check: "Confirm that reverting the explicit .js extension on the relative import reintroduces a resolution error under nodenext, demonstrating the requirement is actually enforced." },
  { id: 14, level: 3, title: "The Composite Project References Split", scenario: "A single large tsconfig.json project has grown slow to build, and the team wants to split it into two logically separate, independently buildable sub-projects: \"core\" and \"app\", where app depends on core.", objective: "Create core/tsconfig.json and app/tsconfig.json, both with `\"composite\": true` and `\"declaration\": true`. In app/tsconfig.json, add `\"references\": [{ \"path\": \"../core\" }]`. Create a root tsconfig.json with no own files, just `\"references\"` listing both projects, for use with `tsc --build`.", constraints: "Both sub-projects must have composite:true — omitting it on core must produce the documented \"referenced project is not composite\" error, which you should intentionally trigger once to observe.", expectedOutput: "Running `tsc --build` from the root builds core first, then app, reusing core's emitted declarations; changing only app's source does not trigger a rebuild of core.", check: "Make a breaking change to a core export used by app and confirm `tsc --build` surfaces the resulting type error in app after rebuilding core's declarations." },
  { id: 15, level: 3, title: "The Cross-Platform Casing Guard", scenario: "A team's CI pipeline (running on Linux) keeps failing with mysterious \"cannot find module\" errors that never reproduce on any team member's Windows or macOS machine.", objective: "Add `\"forceConsistentCasingInFileNames\": true` to tsconfig.json. Find (or intentionally create) an import whose casing does not exactly match the real file name on disk, and confirm it now produces a local compile error instead of only failing on Linux CI.", constraints: "Must actually reproduce a casing mismatch (e.g. import \"./Utils\" against a file named utils.ts) to verify the flag catches it locally. Fix the mismatch once confirmed.", expectedOutput: "Before the flag: the mismatched-casing import compiles fine locally (on a case-insensitive file system) but would fail on Linux. After enabling the flag: it fails to compile locally too, catching the issue before CI does.", check: "Confirm the fixed (correctly-cased) import compiles cleanly with the flag still enabled, proving the flag only flags genuine mismatches." },
  { id: 16, level: 4, title: "The Index Access Safety Net", scenario: "A data-processing service repeatedly crashes in production with \"Cannot read properties of undefined\" when looking up values in a plain object by a dynamic string key.", objective: "Enable `\"noUncheckedIndexedAccess\": true` in tsconfig.json. Find (or write) a function doing `const value = someRecord[dynamicKey]; return value.toUpperCase();` on a `Record<string, string>`, observe the new compile error, and fix it with an explicit undefined check.", constraints: "Must use a genuine Record or index-signature type (not a class with fixed known properties) to trigger the flag's effect. The fix must add a real runtime check, not a type assertion bypassing it.", expectedOutput: "Before the fix: a compile error on the unguarded `.toUpperCase()` call. After the fix: the function safely handles a missing key (e.g. returning a fallback or throwing a clear error) and compiles cleanly.", check: "Confirm calling the fixed function with a key that does not exist in the record behaves correctly (no runtime crash) rather than just silencing the compiler with an assertion." },
  { id: 17, level: 4, title: "The Single-File-Safe Type Export", scenario: "A project is being migrated to use esbuild for fast, non-type-aware transpilation, and needs to ensure no TypeScript syntax pattern would compile incorrectly under a single-file transpiler.", objective: "Enable `\"isolatedModules\": true`. Find (or create) a file re-exporting an interface with a plain `export { SomeInterface }` statement, observe the resulting error, and fix it using `export type { SomeInterface }`.", constraints: "Must reproduce the actual ambiguous-re-export error isolatedModules is designed to catch, not just add the flag without triggering it once. The fix must use the type-only export syntax, not remove the export.", expectedOutput: "Before the fix: a compile error about the ambiguous type-only re-export. After: it compiles cleanly and remains correctly type-only.", check: "Confirm a normal (non-type) value re-export in the same file continues to work unmodified, showing the fix was scoped correctly to just the type-only case." },
  { id: 18, level: 4, title: "The Override Safety Audit", scenario: "A class hierarchy has grown over time, and a recent refactor accidentally introduced a subclass method that unintentionally shadows a base class method with a slightly different signature, causing a subtle bug.", objective: "Enable `\"noImplicitOverride\": true`. Add the `override` keyword to every method in the codebase (or a representative sample) that genuinely overrides a base class method, and find at least one case where a method you expected to be an override actually is not recognized as one (revealing a naming/signature mismatch bug).", constraints: "Must apply override to at least 3 real overriding methods across a small class hierarchy you create for this task. Must identify and document at least one mismatch case the flag helps surface.", expectedOutput: "All genuine overrides compile cleanly with the override keyword; a method that does NOT actually match the base signature produces a clear compile error when override is mistakenly added to it.", check: "Confirm removing override from a genuine override method (with noImplicitOverride still enabled) produces the expected \"must have override modifier\" error." },
  { id: 19, level: 4, title: "The Type-Declaration-Only Build Pipeline", scenario: "A team adopts esbuild for fast application bundling but still needs tsc to produce accurate .d.ts declaration files for their published npm package.", objective: "Configure a tsconfig.json with `\"declaration\": true` and `\"emitDeclarationOnly\": true`, and confirm running `tsc` produces only .d.ts files (no .js output) in the configured outDir, while a separate (simulated or real) esbuild invocation handles producing the actual JavaScript.", constraints: "emitDeclarationOnly must be paired with declaration:true. Confirm no .js files appear in tsc's own output folder after this change.", expectedOutput: "Running tsc alone produces a full set of .d.ts files reflecting the public API accurately, with zero accompanying .js files.", check: "Introduce a type error in the source and confirm tsc still reports it (declaration-only mode does not skip type-checking), even though it produces no JS output." },
  { id: 20, level: 4, title: "The Bundler-Aware Resolution Upgrade", scenario: "A frontend project using Vite reports confusing type-resolution errors for some package imports that work fine at runtime, because tsconfig's moduleResolution does not match Vite's actual resolution behavior.", objective: "Change `\"moduleResolution\"` from `\"node\"` to `\"bundler\"` (TypeScript 5.0+) and adjust `\"module\"` to `\"esnext\"` if needed. Find and fix at least one import that was failing to type-check under the old setting but resolves correctly under bundler mode.", constraints: "Must use a real dependency (or a locally simulated package.json with an \"exports\" field) whose resolution genuinely differs between \"node\" and \"bundler\" moduleResolution to demonstrate the fix.", expectedOutput: "Before the change: a \"cannot find module\" or similar resolution error for the affected import, despite it working at runtime via Vite. After: the import type-checks cleanly.", check: "Document in a comment which specific package.json field or resolution rule (e.g. \"exports\" conditions) caused the mismatch between the two moduleResolution strategies." },
  { id: 21, level: 5, title: "The Dual CJS/ESM Publish Pipeline", scenario: "A library author needs to publish a single npm package that works correctly for both older CommonJS `require()` consumers and modern native-ESM `import` consumers, each with accurate matching type declarations.", objective: "Create two tsconfig files (e.g. tsconfig.cjs.json and tsconfig.esm.json, both extending a shared tsconfig.base.json) differing in \"module\"/\"outDir\", each producing its own build with declarations. Configure package.json's \"exports\" field to route \"require\" and \"import\" conditions to the correct respective build outputs and their type declarations.", constraints: "Both builds must emit accurate, matching declaration files. The package.json exports map must correctly use \"require\"/\"import\" (and \"types\") conditions pointing at the right files for each format.", expectedOutput: "A CommonJS consumer using require() gets correctly-typed CJS output; an ESM consumer using import gets correctly-typed native ESM output — both from the same published package.", check: "Simulate both a require() and an import consumer (or reason through package.json exports resolution rules) and confirm each resolves to its intended build artifacts and matching .d.ts files." },
  { id: 22, level: 5, title: "The Incremental Build Performance Audit", scenario: "A very large single-project (non-monorepo) codebase's `tsc --noEmit` CI step has become a major bottleneck, taking many minutes per run.", objective: "Enable `\"incremental\": true` with a persisted `.tsbuildinfo` file cached between CI runs (document the caching strategy). Audit and adjust `\"skipLibCheck\"`, `\"types\"`, and `\"lib\"` to eliminate unnecessary third-party or global type-checking overhead. Measure (or reason through, with supporting comments) the before/after impact of each individual change.", constraints: "Must address at least three distinct levers (incremental caching, skipLibCheck, and a narrowed types/lib configuration). Must explain, per change, specifically why it reduces type-checking work.", expectedOutput: "A documented, ordered list of applied optimizations with the reasoning for each, and confirmation that the project still fully type-checks correctly after all changes (no false negatives introduced).", check: "Introduce a deliberate type error after all optimizations are applied and confirm it is still caught, proving the speedups did not silently disable real type-checking." },
  { id: 23, level: 5, title: "The Legacy Strict Mode Rollout Plan", scenario: "A 200-file legacy codebase needs to adopt full strict mode, but flipping it on everywhere at once produces over a thousand errors, making the migration seem impossible to land incrementally via pull requests.", objective: "Design and implement a phased tsconfig strategy: start with `\"strict\": true` plus most individual strict sub-flags explicitly disabled, then create a second, stricter tsconfig (e.g. tsconfig.strict.json extending the base) applied only to a growing allowlist of already-migrated files via a scoped include, while the main config still governs the rest.", constraints: "Must demonstrate the mechanism for progressively \"graduating\" files from the loose config to the strict one (e.g. via include/exclude patterns or a documented file-by-file migration list) rather than an all-or-nothing flip.", expectedOutput: "At project completion, both configs coexist during the transition: newly migrated files are fully strict-checked, unmigrated files still compile under the looser settings, and CI enforces no regression in the already-migrated set.", check: "Simulate migrating one specific file: move it from the loose scope into the strict scope, fix the resulting new errors, and confirm CI (or a local dual-config check) now holds that file to the full strict standard going forward." },
  { id: 24, level: 5, title: "The Type-Stripping Compatibility Audit", scenario: "A team wants their TypeScript source to run directly under Node's native type-stripping support (which only erases type syntax, without understanding TypeScript-specific runtime constructs), without a separate build step for local development.", objective: "Enable `\"erasableSyntaxOnly\": true` in a development-focused tsconfig.json. Audit the codebase for any use of non-erasable constructs (regular enums, namespaces containing runtime code, parameter properties) that would break under pure type-stripping, and refactor each into an erasable-safe equivalent (e.g. converting an enum to a const object with an inferred union type, or parameter properties to explicit constructor assignments).", constraints: "Must identify and refactor at least two real non-erasable patterns. The refactored equivalents must preserve the original type-safety and developer-facing API as closely as possible.", expectedOutput: "The audited tsconfig reports zero erasableSyntaxOnly violations after refactoring, and the refactored code is verified to behave identically to the original at runtime.", check: "Confirm reverting one refactor (e.g. back to a regular enum) reproduces the erasableSyntaxOnly compile error, proving the check is genuinely active and the refactor was necessary." },
  { id: 25, level: 5, title: "The Full-Stack Reference Graph Architecture", scenario: "A company's monorepo has grown to 8 packages (shared types, database layer, business logic, two backend services, and three frontend apps) with a tangled, undocumented set of cross-package dependencies causing frequent accidental circular imports and slow, unpredictable builds.", objective: "Design a complete TypeScript project references graph: create composite tsconfig.json files for all 8 packages with correctly declared \"references\" reflecting only genuine, intentional dependencies (no cycles), a root orchestrating tsconfig.json with no own files, and appropriate \"paths\"/package.json wiring so both tsc --build and the actual runtime bundlers resolve packages consistently.", constraints: "The reference graph must be acyclic — attempting to introduce a circular reference (e.g. shared-types depending on a backend service) must be caught and fixed. Every composite package must have declaration and appropriate rootDir/outDir settings avoiding overlap.", expectedOutput: "`tsc --build` from the root builds all 8 packages in correct dependency order with proper incremental caching; introducing an accidental circular reference produces a clear build error rather than an infinite loop or silent misbehavior.", check: "Deliberately introduce a circular reference between two packages, confirm tsc --build reports it clearly, then remove it and confirm a full clean build succeeds end-to-end with correct ordering." },
],
};